window.DL_LADDERS = Object.assign(window.DL_LADDERS || {}, {"m3-1|1. 실수와 그 계산|01. 제곱근이란 무엇일까?": [{"kind": "뜻", "q": "어떤 수 x를 \"a의 제곱근\"이라고 부르는 건 x가 어떤 조건을 만족할 때야? 16의 제곱근을 예로 들어 말해 봐.", "ideas": [["x를 제곱하면 a가 될 때 x를 a의 제곱근이라고 한다", "제곱근의 \"제곱\"은 x에 무엇을 한다는 뜻일까?"], ["16의 제곱근은 제곱해서 16이 되는 4와 −4이다", "음수 중에도 제곱해서 16이 되는 수가 있을까?"]], "teach": "제곱해서 a가 되는 수, 즉 x²=a 를 만족하는 x가 a의 제곱근이야. 4²=16 이고 (−4)²=16 이니까 16의 제곱근은 4와 −4 두 개야.", "again": "9의 제곱근이 무엇인지, 제곱근의 뜻을 써서 말해 봐.", "fig": false, "src": "19쪽", "miscon": "제곱근을 \"그 수를 제곱한 값\"으로 거꾸로 앎", "record": "제곱근의 뜻(제곱해서 a가 되는 수)을 말하지 못하거나 제곱과 반대로 알고 있음"}, {"kind": "함정", "q": "\"(−5)²의 제곱근\"을 구하라고 하면 무엇부터 해야 하고, 답은 몇 개일까?", "ideas": [["(−5)²을 먼저 계산해서 25로 바꾼다", "(−5)²은 얼마야? 제곱근을 구할 대상은 −5일까, 그 계산 결과일까?"], ["25의 제곱근이므로 5와 −5 두 개이다", "제곱해서 25가 되는 수는 몇 개이고 무엇이지?"]], "teach": "\"(−5)²의 제곱근\"은 (−5)²=25 의 제곱근이라는 뜻이야. 그래서 −5 하나가 아니라 제곱해서 25가 되는 5와 −5 두 개가 답이야.", "again": "\"(−3)²의 제곱근\"을 구할 때 −3이라고 답하면 왜 틀리는지 말해 봐.", "fig": false, "src": "19쪽 예제 1", "miscon": "(−5)²의 제곱근을 −5로 봄", "record": "제곱근을 구할 대상을 먼저 계산하지 않고 식에 보이는 수를 답으로 씀"}], "m3-1|1. 실수와 그 계산|02. 어떤 수든지 제곱근은 항상 2개일까?": [{"kind": "성질", "q": "양수, 0, 음수의 제곱근은 각각 몇 개야?", "ideas": [["양수의 제곱근은 양수와 음수 2개이고 절댓값이 같다", "9의 제곱근을 떠올려 봐. 몇 개였지?"], ["0의 제곱근은 0 하나뿐이다", "제곱해서 0이 되는 수가 0 말고 또 있을까?"], ["음수의 제곱근은 없다", "제곱해서 −4가 되는 수를 찾을 수 있을까?"]], "teach": "양수는 제곱근이 2개(예: 9 → 3, −3), 0은 0 하나, 음수는 제곱근이 없어. 그래서 \"제곱근은 항상 2개\"가 아니야.", "again": "4, 0, −4의 제곱근의 개수를 각각 말해 봐.", "fig": false, "src": "20쪽", "miscon": "0이나 음수도 제곱근이 2개라고 생각함", "record": "양수·0·음수에 따라 제곱근의 개수가 다르다는 것을 구분하지 못함"}, {"kind": "이유", "q": "음수의 제곱근이 없는 이유는 뭘까?", "ideas": [["양수든 음수든 제곱하면 양수가 되어, 제곱해서 음수가 되는 수가 없다", "음수를 제곱하면 부호가 어떻게 되지?"]], "teach": "3²=9, (−3)²=9 처럼 어떤 수를 제곱해도 0보다 작아지지 않아. 제곱해서 음수가 되는 수가 없으니 음수의 제곱근도 없어.", "again": "제곱해서 −9가 되는 수가 없는 이유를 한 문장으로 말해 봐.", "fig": false, "src": "20쪽", "miscon": "음수×음수가 음수라고 착각함", "record": "음수의 제곱근이 없는 이유(제곱하면 항상 0 이상)를 설명하지 못함"}], "m3-1|1. 실수와 그 계산|03. 제곱근을 나타내는 기호는?": [{"kind": "뜻", "q": "근호 √는 무엇을 나타내는 기호이고, √a와 −√a는 각각 무엇을 뜻해?", "ideas": [["√는 제곱근을 나타내는 기호로 근호라고 한다", "제곱근을 매번 말로 쓰기 번거로워서 만든 기호의 이름이 뭐였지?"], ["a>0일 때 √a는 a의 양의 제곱근, −√a는 a의 음의 제곱근이다", "√a와 −√a 중 양수인 것은 어느 쪽일까?"]], "teach": "√를 근호라고 하고 √a를 \"제곱근 a\" 또는 \"루트 a\"라고 읽어. a>0일 때 √a는 a의 양의 제곱근, −√a는 음의 제곱근이라서 a의 제곱근은 ±√a야. a=0이면 제곱근은 0 하나야.", "again": "5의 양의 제곱근과 음의 제곱근을 기호로 어떻게 쓰는지 말해 봐.", "fig": false, "src": "20~21쪽", "miscon": "√a가 양·음 두 제곱근을 모두 나타낸다고 생각함", "record": "√a는 양의 제곱근 하나만 나타낸다는 것을 구분하지 못함"}, {"kind": "이유", "q": "넓이가 5인 정사각형의 한 변의 길이를 왜 √5로 나타낼까?", "ideas": [["한 변의 길이는 제곱해서 5가 되는 양수이다", "정사각형의 넓이는 한 변의 길이를 어떻게 해서 구하지?"], ["그 수, 즉 5의 양의 제곱근을 기호로 √5라고 나타낸다", "제곱해서 5가 되는 양수를 부르는 이름과 그 기호가 뭐였지?"]], "teach": "넓이=(한 변)² 이니까 한 변은 제곱해서 5가 되는 양수, 곧 5의 양의 제곱근이야. 그 수를 기호로 √5라고 써. (√5가 어떤 종류의 수인지는 무리수에서 배워.)", "again": "넓이가 3인 정사각형의 한 변의 길이를 기호로 쓰는 이유를 말해 봐.", "fig": true, "src": "20쪽", "miscon": "넓이를 2로 나눠 한 변을 구함", "record": "정사각형의 넓이와 한 변의 관계(제곱)를 제곱근과 연결하지 못함", "figScene": {"title": "넓이가 5인 정사각형", "points": {"A": [120, 80], "B": [300, 80], "C": [300, 260], "D": [120, 260]}, "shapes": [{"points": ["A", "B", "C", "D"], "fill": "#eef3f9", "stroke": "#185FA5"}], "labels": [{"text": "넓이 5", "dx": -24, "dy": 6, "at": [210, 170]}, {"text": "한 변의 길이 = ?", "dx": -52, "dy": 24, "at": [210, 260]}]}}], "m3-1|1. 실수와 그 계산|04. √16을 근호를 사용하지 않고 나타내면?": [{"kind": "방법", "q": "√16이나 −√25처럼 근호 안의 수가 어떤 수의 제곱일 때, 근호를 쓰지 않고 나타내는 방법을 말해 봐.", "ideas": [["√16은 16의 양의 제곱근이므로 제곱해서 16이 되는 양수로 나타낸다", "√16은 16의 양의 제곱근일까, 음의 제곱근일까?"], ["−√25는 음의 제곱근이므로 − 부호를 붙인 음수로 나타낸다", "−√25는 25의 어떤 제곱근이야?"]], "teach": "√16은 16의 양의 제곱근이라 4 하나야(−4는 아님). −√25는 25의 음의 제곱근이라 −5야. 근호 안이 제곱인 수면 근호를 없앨 수 있어.", "again": "√36과 −√144를 근호 없이 나타내는 방법을 말해 봐.", "fig": false, "src": "22쪽", "miscon": "√16을 ±4로 봄", "record": "√a와 \"a의 제곱근\"을 구분하지 못해 부호를 틀림"}, {"kind": "함정", "q": "√0.04를 근호 없이 나타낼 때 0.2와 0.02 중 무엇일까? 어떻게 확인해?", "ideas": [["제곱해서 0.04가 되는 양수를 찾는다", "√0.04는 어떤 수를 제곱했을 때 0.04가 되는 수야?"], ["후보를 직접 제곱해 보면 0.02를 제곱하면 0.0004라서 0.2가 맞다", "0.02를 제곱하면 0.04가 될까?"]], "teach": "√0.04는 제곱해서 0.04가 되는 양수야. 0.2²=0.04 이고 0.02²=0.0004 라서 √0.04=0.2. 소수는 자릿수가 헷갈리니 제곱해서 확인해.", "again": "√0.09를 근호 없이 나타낼 때 확인하는 방법을 말해 봐.", "fig": false, "src": "22쪽 예제 4", "miscon": "소수의 제곱근을 자릿수만 보고 짐작함", "record": "소수의 제곱근을 제곱해서 확인하지 않아 자릿수를 틀림"}], "m3-1|1. 실수와 그 계산|05. 3의 제곱근과 제곱근 3은 어떻게 다를까?": [{"kind": "함정", "q": "\"3의 제곱근\"과 \"제곱근 3\"은 어떻게 다를까? 기호로는 각각 어떻게 써?", "ideas": [["\"3의 제곱근\"은 제곱해서 3이 되는 수 두 개로 ±√3이다", "제곱해서 3이 되는 수는 몇 개일까?"], ["\"제곱근 3\"은 √3을 읽은 말로 3의 양의 제곱근 √3 하나이다", "√3을 소리 내어 읽으면 어떻게 읽지?"]], "teach": "\"3의 제곱근\"은 제곱해서 3이 되는 수라서 √3과 −√3, 두 개야. \"제곱근 3\"은 기호 √3을 읽는 이름이라 √3 하나야.", "again": "\"7의 제곱근\"과 \"제곱근 7\"을 기호로 각각 말해 봐.", "fig": false, "src": "22쪽", "miscon": "\"3의 제곱근\"과 \"제곱근 3\"을 같은 것으로 봄", "record": "\"a의 제곱근\"(±√a)과 \"제곱근 a\"(√a)를 구분하지 못함"}, {"kind": "적용", "q": "\"√16의 제곱근\"을 구할 때 무엇부터 해야 하고, 틀리기 쉬운 점은 뭘까?", "ideas": [["√16을 먼저 근호 없이 4로 바꾼다", "√16은 근호 없이 어떤 수지?"], ["4의 제곱근을 구해야 하므로 ±2이고, ±4라고 하면 틀린다", "제곱근을 구할 대상이 16일까, 4일까?"]], "teach": "\"√16의 제곱근\"은 √16=4 의 제곱근이야. 그러니 ±2가 답이고, 16의 제곱근인 ±4와 헷갈리면 안 돼.", "again": "\"√81의 제곱근\"을 구하는 순서를 말해 봐.", "fig": false, "src": "22쪽", "miscon": "√16의 제곱근을 16의 제곱근(±4)으로 착각함", "record": "제곱근을 구할 대상(√16=4)을 먼저 정리하지 않음"}], "m3-1|1. 실수와 그 계산|06. a>0일 때, (√a)², √(a²)의 값은?": [{"kind": "성질", "q": "a>0일 때 (√a)²과 √(a²)은 각각 무엇이 되고, 그 이유는 뭘까?", "ideas": [["√a는 제곱하면 a가 되는 수라서 (√a)²=a이다", "√a는 무엇을 제곱했을 때 a가 되는 수였지?"], ["√(a²)은 a²의 양의 제곱근인데 a>0이므로 a이다", "제곱해서 a²이 되는 양수는 무엇일까?"]], "teach": "√a는 a의 제곱근이니까 제곱하면 a로 돌아와. √(a²)은 a²의 양의 제곱근인데 a가 양수라서 a야. √와 제곱이 만나면 근호가 사라지는 셈이야.", "again": "(√7)²과 √(7²)이 모두 7이 되는 이유를 말해 봐.", "fig": false, "src": "23쪽", "miscon": "(√a)²을 a²으로 계산함", "record": "(√a)²=a, √(a²)=a가 되는 이유를 제곱근의 뜻으로 설명하지 못함"}, {"kind": "성질", "q": "a>0일 때 (−√a)²과 √((−a)²)도 a가 되는 이유를 말해 봐.", "ideas": [["−√a도 a의 제곱근이라서 제곱하면 a가 된다", "−√a는 a의 어떤 제곱근이지?"], ["(−a)²은 a²과 같아서 근호를 씌우면 양수 a가 된다", "(−a)²과 a²은 서로 같을까?"]], "teach": "−√a는 a의 음의 제곱근이라 제곱해도 a야. (−a)²=a² 이니까 √((−a)²)=√(a²)=a. 제곱이 − 부호를 + 로 바꿔 줘.", "again": "(−√3)²과 √((−3)²)이 모두 3인 이유를 말해 봐.", "fig": false, "src": "23쪽", "miscon": "√((−a)²)의 − 부호가 그대로 남는다고 생각함", "record": "제곱이 − 부호를 없앤다는 것을 제곱근 계산에 연결하지 못함"}, {"kind": "방법", "q": "5를 근호를 사용해 나타내면 √25가 되는 이유와, −5는 어떻게 나타내는지 말해 봐.", "ideas": [["근호 안에 그 수의 제곱인 수를 넣어 5=√(5²)=√25로 나타낸다", "√ 안에 무엇을 넣어야 근호를 벗겼을 때 5가 나올까?"], ["음수는 − 부호를 근호 밖에 두어 −5=−√25로 나타낸다", "−5를 나타낼 때 − 부호는 근호 안과 밖 중 어디에 둬야 할까?"]], "teach": "근호를 없애는 것과 반대로, 근호 안에 그 수의 제곱을 쓰면 돼: 5=√25. 음수는 − 를 밖에 둬서 −5=−√25. 근호 안에 −25를 넣으면 안 돼.", "again": "−3을 근호를 사용해 나타낼 때 조심할 점을 말해 봐.", "fig": false, "src": "24쪽", "miscon": "음수를 근호 안에 넣어 √(−25)로 씀", "record": "근호 밖의 − 부호를 근호 안으로 넣으면 안 된다는 것을 모름"}], "m3-1|1. 실수와 그 계산|07. a<0일 때, √(a²)의 값은?": [{"kind": "성질", "q": "a<0일 때 √(a²)이 a가 아니라 −a가 되는 이유를 말해 봐.", "ideas": [["√로 나타낸 값은 양의 제곱근이라 항상 0 이상이다", "√(a²)은 a²의 양의 제곱근일까, 음의 제곱근일까?"], ["a가 음수이면 부호를 바꾼 −a가 양수이므로 √(a²)=−a이다", "a가 음수일 때 a와 −a 중 양수는 어느 쪽이지?"]], "teach": "√(a²)은 양의 제곱근이라 결과가 양수여야 해. a<0 이면 a는 음수라 답이 될 수 없고, 부호를 바꾼 −a 가 양수야. 예: a=−3 이면 √9=3=−(−3).", "again": "a=−2일 때 √(a²)을 a로 쓰면 왜 틀리는지 말해 봐.", "fig": false, "src": "24쪽", "miscon": "√와 제곱은 부호와 관계없이 무조건 지워진다고 생각함", "record": "√(a²) 공식은 기억하지만, a<0일 때 결과가 −a가 되는 이유를 설명하지 못함"}, {"kind": "방법", "q": "0<a<1일 때 √((a−2)²)을 근호 없이 간단히 하려면 먼저 무엇을 확인하고 어떻게 정리해?", "ideas": [["제곱된 식 a−2가 양수인지 음수인지 먼저 확인한다", "a가 0과 1 사이면 a−2는 양수일까, 음수일까?"], ["a−2가 음수이므로 부호를 바꾼 −(a−2), 즉 −a+2로 나타낸다", "제곱된 식이 음수이면 근호를 벗길 때 무엇을 붙여야 할까?"]], "teach": "근호 안이 문자식의 제곱이면 그 식의 부호부터 봐. 0<a<1 이면 a−2<0 이라서 √((a−2)²)=−(a−2)=−a+2. 양수였다면 그대로 나와.", "again": "√((a−2)²)을 간단히 할 때 a−2의 부호를 먼저 따져야 하는 이유를 말해 봐.", "fig": false, "src": "24쪽 예제 7", "miscon": "제곱된 식의 부호를 보지 않고 그대로 꺼냄", "record": "근호 안에서 제곱된 식의 부호를 확인해야 한다는 것을 적용하지 못함"}], "m3-1|1. 실수와 그 계산|08. √((-3)²)+(-√10)²-√25를 계산하면?": [{"kind": "방법", "q": "√((−3)²)+(−√10)²−√25 같은 식을 계산할 때 어떤 성질을 어떤 순서로 쓰는지 말해 봐.", "ideas": [["제곱근의 성질로 각 항의 근호를 먼저 없애 근호가 없는 수로 바꾼다", "√((−3)²), (−√10)², √25를 각각 근호 없이 나타낼 수 있을까?"], ["그다음 보통의 덧셈·뺄셈을 한다", "근호가 모두 없어지면 식은 어떤 계산이 될까?"]], "teach": "각 항을 제곱근의 성질로 근호 없는 수로 바꾸면 √((−3)²)=3, (−√10)²=10, √25=5. 그러면 3+10−5 인 보통 계산이 돼.", "again": "√(11²)+(−√7)²−√36을 계산하는 순서를 말해 봐.", "fig": false, "src": "25쪽", "miscon": "근호 안의 수끼리 먼저 더하거나 뺌", "record": "제곱근의 성질로 근호를 먼저 없애는 순서를 모름"}, {"kind": "함정", "q": "√((−3)²)을 −3이라고 쓰면 왜 틀릴까?", "ideas": [["(−3)²=9이고 √9는 9의 양의 제곱근이라 3이다", "(−3)²은 얼마고, 그 수의 양의 제곱근은 무엇이지?"]], "teach": "근호 안부터 보면 (−3)²=9 야. √9는 양의 제곱근이라 3. √와 제곱이 만나 사라질 때 − 부호까지 그대로 남는 게 아니라 양수가 나와.", "again": "√((−7)²)의 값이 양수가 되는 이유를 말해 봐.", "fig": false, "src": "25쪽", "miscon": "√((−3)²)=−3 처럼 부호를 그대로 둠", "record": "√((−3)²)이 양수 3이 되는 이유를 설명하지 못함"}], "m3-1|1. 실수와 그 계산|09. √(3×x)가 자연수가 되도록 하는 가장 작은 자연수 x의 값은?": [{"kind": "이유", "q": "√(3×x)가 자연수가 되려면 근호 안의 3×x는 어떤 수여야 하고, 그 수는 소인수분해하면 어떤 특징이 있어?", "ideas": [["3×x가 제곱수여야 한다", "√9=3 처럼 근호가 없어지려면 근호 안이 어떤 수여야 할까?"], ["제곱수를 소인수분해하면 모든 소인수의 지수가 짝수이다", "36=2²×3² 처럼 제곱수를 소인수분해하면 지수에 어떤 특징이 있어?"]], "teach": "√(제곱수)=자연수 라서 근호 안이 1, 4, 9, 16… 같은 제곱수여야 해. 제곱수는 소인수분해하면 지수가 모두 짝수야(36=2²×3²).", "again": "√(5×x)가 자연수가 되기 위한 조건을 말해 봐.", "fig": false, "src": "25쪽", "miscon": "3의 배수이면 된다고 생각함", "record": "근호 안이 제곱수(소인수의 지수가 모두 짝수)여야 한다는 조건을 모름"}, {"kind": "방법", "q": "√(18×x)가 자연수가 되도록 하는 가장 작은 자연수 x는 어떻게 찾아?", "ideas": [["18을 소인수분해해서 2×3²으로 나타낸다", "18을 소인수분해하면 어떻게 되지?"], ["지수가 홀수인 소인수만 곱해서 모든 지수를 짝수로 만든다", "2×3² 에서 지수가 홀수인 소인수는 무엇이고, 무엇을 곱하면 짝수가 될까?"]], "teach": "18=2×3² 에서 3은 이미 지수가 짝수, 2만 홀수야. 2를 한 번 더 곱하면 2²×3² 인 제곱수가 되니까 가장 작은 x는 2야. 18을 곱해도 제곱수지만 가장 작지는 않아.", "again": "√(12×x)가 자연수가 되는 가장 작은 x를 찾는 방법을 말해 봐.", "fig": false, "src": "26쪽 예제 9", "miscon": "18을 곱하면 된다고 생각함(가장 작은 수 조건 무시)", "record": "지수가 홀수인 소인수만 곱해 가장 작은 수를 찾는 방법을 모름"}, {"kind": "함정", "q": "√(20−x)가 자연수가 되는 가장 작은 자연수 x를 구할 때는 √(20×x)와 방법이 어떻게 달라?", "ideas": [["20−x가 20보다 작은 제곱수(1, 4, 9, 16) 중 하나가 되어야 한다", "20−x는 20보다 클까, 작을까? 그 범위의 제곱수는 뭐가 있어?"], ["x가 가장 작으려면 20−x가 그중 가장 큰 제곱수 16이 되어야 한다", "x를 작게 하려면 20−x는 커야 할까, 작아야 할까?"]], "teach": "빼기 꼴은 소인수분해가 아니라 \"20−x 가 제곱수\"인 경우를 따져. 20보다 작은 제곱수는 1, 4, 9, 16 이고, x가 가장 작으려면 20−x가 가장 커야 하니 16, 즉 x=4.", "again": "√(30−x)가 자연수가 되는 가장 작은 x를 찾는 방법을 말해 봐.", "fig": false, "src": "26쪽 예제 9", "miscon": "뺄셈 꼴에도 소인수분해 방법을 그대로 씀", "record": "√(20−x) 꼴에서는 20보다 작은 제곱수를 따져야 한다는 것을 구분하지 못함"}], "m3-1|1. 실수와 그 계산|10. 제곱근의 대소 관계는 어떻게 알 수 있을까?": [{"kind": "성질", "q": "a>0, b>0일 때 √a와 √b의 크기는 어떻게 비교하고, 정사각형으로 보면 왜 그럴까?", "ideas": [["a<b이면 √a<√b, 근호 안의 수가 클수록 제곱근이 크다", "근호 안의 수 3과 5 중 큰 쪽의 제곱근이 더 클까?"], ["넓이가 a, b인 정사각형의 한 변이 √a, √b인데 넓이가 넓을수록 한 변도 길다", "넓이가 더 넓은 정사각형은 한 변도 더 길까?"]], "teach": "넓이가 3, 5인 정사각형의 한 변은 √3, √5야. 넓을수록 한 변이 길어서 3<5 이면 √3<√5. 거꾸로 √a<√b 이면 a<b 도 성립해.", "again": "√6과 √7의 크기를 비교하는 방법과 이유를 말해 봐.", "fig": true, "src": "26~27쪽", "miscon": "근호 안의 수가 크면 제곱근은 작다고 생각함", "record": "제곱근의 대소를 근호 안의 수로 비교하는 이유(정사각형의 넓이와 한 변)를 설명하지 못함", "figScene": {"title": "넓이가 3, 5인 두 정사각형", "points": {"A": [60, 110], "B": [190, 110], "C": [190, 240], "D": [60, 240], "E": [240, 72], "F": [408, 72], "G": [408, 240], "H": [240, 240]}, "shapes": [{"points": ["A", "B", "C", "D"], "fill": "#eef3f9", "stroke": "#185FA5"}, {"points": ["E", "F", "G", "H"], "fill": "#fdeee8", "stroke": "#D85A30"}], "labels": [{"text": "넓이 3", "dx": -22, "dy": 6, "at": [125, 175]}, {"text": "넓이 5", "dx": -22, "dy": 6, "at": [324, 160]}, {"text": "√3", "dx": -8, "dy": 22, "at": [125, 240]}, {"text": "√5", "dx": -8, "dy": 22, "at": [324, 240]}]}}, {"kind": "방법", "q": "√5와 2처럼 근호가 있는 수와 없는 수의 크기는 어떻게 비교해?", "ideas": [["근호가 없는 수를 근호가 있는 수로 바꾼다(2=√4)", "2를 근호를 사용해 나타내면 어떻게 될까?"], ["두 수의 근호 안의 수를 비교한다", "√5와 √4는 무엇을 비교하면 될까?"]], "teach": "2=√4 로 바꾸면 √5와 √4 비교가 돼. 5>4 이니까 √5>2. 근호가 없는 수를 근호 안으로 넣어 같은 모양으로 맞추는 게 핵심이야.", "again": "3과 √10의 크기를 비교하는 방법을 말해 봐.", "fig": false, "src": "27쪽 예제 10", "miscon": "√5를 5로 보고 비교함", "record": "근호가 없는 수를 근호로 바꿔 비교하는 방법을 모름"}, {"kind": "함정", "q": "−√2와 −√3 중 어느 수가 더 클까? 양수일 때와 무엇이 달라?", "ideas": [["√2<√3이지만 음수가 되면 크기가 거꾸로 되어 −√2>−√3이다", "−2와 −3 중 어느 쪽이 더 큰지 떠올려 봐."], ["음수는 근호 안의 수가 작을수록 더 크다", "음수끼리는 절댓값이 클수록 크기가 어떻게 되지?"]], "teach": "양수일 때는 근호 안이 클수록 크지만, 음수는 절댓값이 클수록 작아. √2<√3 이니까 −√2>−√3.", "again": "−√5와 −√7 중 더 큰 수를 고르는 방법을 말해 봐.", "fig": false, "src": "27쪽", "miscon": "음수도 근호 안이 클수록 크다고 생각함", "record": "음수인 제곱근의 대소가 거꾸로 된다는 것을 적용하지 못함"}], "m3-1|1. 실수와 그 계산|11. 무리수와 실수는 어떤 수인가?": [{"kind": "뜻", "q": "무리수는 어떤 수이고, 실수는 어떤 수를 말해?", "ideas": [["무리수는 유리수가 아닌 수로, 순환하지 않는 무한소수로 나타나는 수이다", "분수로 나타낼 수 없는 소수는 어떤 소수였지?"], ["실수는 유리수와 무리수를 통틀어 이르는 말이다", "유리수와 무리수를 한꺼번에 부르는 이름이 뭐지?"]], "teach": "유한소수와 순환소수는 분수로 나타낼 수 있는 유리수야. 순환하지 않는 무한소수는 분수로 나타낼 수 없어서 무리수라고 해. 유리수와 무리수를 합쳐 실수라고 불러.", "again": "√2가 무리수인 이유와, √2가 실수에도 속하는 이유를 말해 봐.", "fig": false, "src": "29~30쪽", "miscon": "무한소수를 모두 무리수로 봄", "record": "무리수와 실수의 뜻을 구분해 말하지 못함"}, {"kind": "함정", "q": "\"무한소수는 모두 무리수이다\"는 왜 틀린 말일까?", "ideas": [["무한소수 중 순환소수는 분수로 나타낼 수 있어서 유리수이다", "0.333…은 분수로 나타낼 수 있을까?"], ["무한소수 중 순환하지 않는 것만 무리수이다", "무리수가 되려면 무한소수 중에서도 어떤 조건이 필요할까?"]], "teach": "0.333…=1/3 처럼 순환소수는 끝이 없어도 분수로 쓸 수 있어서 유리수야. 무리수는 무한소수 중에서도 순환하지 않는 것뿐이야.", "again": "0.121212…가 무리수가 아닌 이유를 말해 봐.", "fig": false, "src": "31쪽 예제 11", "miscon": "끝이 없는 소수는 모두 무리수라고 생각함", "record": "순환소수와 순환하지 않는 무한소수를 구분하지 못함"}, {"kind": "적용", "q": "π와 3+√2가 무리수인 이유를 말해 봐.", "ideas": [["π는 순환하지 않는 무한소수이다", "π=3.141592…는 어떤 소수일까?"], ["3+√2는 유리수 3에 무리수 √2를 더해서 소수 부분이 순환하지 않는다", "√2=1.414…에 3을 더하면 소수 부분이 순환하게 될까?"]], "teach": "π는 소수점 아래가 순환하지 않고 끝없이 이어져서 무리수야. 3+√2=4.414… 로 √2의 소수 부분이 그대로 남아 순환하지 않으니 역시 무리수야.", "again": "1−√3이 무리수인지 판단하는 방법을 말해 봐.", "fig": false, "src": "31쪽 예제 11", "miscon": "유리수를 더하면 유리수가 된다고 생각함", "record": "유리수와 무리수의 합이 무리수인 이유를 설명하지 못함"}], "m3-1|1. 실수와 그 계산|12. √9는 유리수일까? 무리수일까?": [{"kind": "함정", "q": "√9를 \"근호가 있으니까 무리수\"라고 하면 왜 틀릴까?", "ideas": [["근호 안의 수가 제곱수이면 근호를 없앨 수 있다", "9는 어떤 수의 제곱이지?"], ["√9=3이므로 분수로 나타낼 수 있는 유리수이다", "√9를 근호 없이 나타낸 수는 분수로 나타낼 수 있을까?"]], "teach": "근호가 있다고 다 무리수는 아니야. 9=3² 이라 √9=3 으로 근호가 없어지고, 3은 유리수야.", "again": "√4가 유리수인 이유를 말해 봐.", "fig": false, "src": "31쪽", "miscon": "근호가 붙으면 모두 무리수라고 생각함", "record": "근호가 있어도 근호 안이 제곱수면 유리수라는 것을 모름"}, {"kind": "방법", "q": "근호가 있는 수가 유리수인지 무리수인지 판단하는 방법을 √0.04와 √0.4로 설명해 봐.", "ideas": [["근호 안의 수가 어떤 유리수의 제곱인지 확인한다", "0.04와 0.4 중 어떤 유리수를 제곱해서 나오는 수는?"], ["근호 안이 0 이상의 유리수일 때, 어떤 유리수의 제곱이면 그 제곱근은 유리수이고 아니면 무리수이다", "근호를 없앨 수 없으면 그 수는 어떤 수가 될까?"]], "teach": "근호 안이 0 이상의 유리수일 때 판단법이야. 0.04=0.2² 이라 √0.04=0.2 는 유리수. 0.4는 어떤 유리수의 제곱도 아니라 √0.4는 근호를 없앨 수 없는 무리수야.", "again": "√(1/4)과 √(1/2) 중 유리수인 것을 고르는 방법을 말해 봐.", "fig": false, "src": "31쪽", "miscon": "소수로 적힌 수의 제곱근은 모두 유리수라고 봄", "record": "근호 안이 유리수의 제곱인지로 유리수·무리수를 판정하지 못함"}], "m3-1|1. 실수와 그 계산|13. 제곱근의 값을 어림하여 정리해 놓은 표가 있다?": [{"kind": "방법", "q": "제곱근표는 어떤 표이고, √1.34의 어림값은 표에서 어떻게 찾아?", "ideas": [["1.00부터 99.9까지의 수의 양의 제곱근을 어림해 정리한 표이다", "제곱근표에는 어떤 범위의 수의 제곱근이 적혀 있지?"], ["왼쪽 세로줄에서 1.3을, 위쪽 가로줄에서 4를 찾아 만나는 칸의 수를 읽는다", "1.34를 1.3과 4로 나누면 각각 표의 어디에서 찾을까?"]], "teach": "제곱근표는 1.00~99.9 인 수의 양의 제곱근을 반올림해 소수점 아래 셋째 자리까지 적은 표야. √1.34 는 왼쪽 1.3 줄과 위쪽 4 칸이 만나는 1.158 을 읽어.", "again": "√1.45의 어림값을 제곱근표에서 찾는 방법을 말해 봐.", "fig": false, "src": "31~32쪽", "miscon": "표에서 찾지 않고 직접 제곱해서 찾으려 함", "record": "제곱근표의 범위와 읽는 방법을 모름"}, {"kind": "이유", "q": "무리수를 실생활에서 쓸 때 제곱근표 같은 어림값을 쓰는 이유는 뭘까? 표의 값은 정확한 값일까?", "ideas": [["무리수는 순환하지 않는 무한소수라 정확한 값을 끝까지 쓸 수 없다", "√2를 소수로 쓰면 끝이 날까?"], ["표의 값은 반올림한 어림값이지 정확한 값이 아니다", "제곱근표의 1.158은 √1.34와 완전히 같은 수일까?"]], "teach": "무리수는 소수점 아래가 끝없이 순환하지 않아 정확히 다 쓸 수 없어. 그래서 실생활에서는 어림값을 쓰는데, 표의 1.158 도 반올림한 값이라 √1.34 와 완전히 같지는 않아.", "again": "원주율을 3.14로 계산하는 것과 제곱근표를 쓰는 것이 비슷한 이유를 말해 봐.", "fig": false, "src": "31쪽", "miscon": "제곱근표의 값을 정확한 값으로 봄", "record": "어림값과 정확한 값을 구분하지 못함"}], "m3-1|1. 실수와 그 계산|14. 무리수를 수직선 위에 어떻게 나타낼 수 있을까?": [{"kind": "방법", "q": "√2를 수직선 위에 나타내는 방법을 말해 봐.", "ideas": [["한 변이 1인 정사각형의 대각선 길이가 피타고라스 정리로 √2임을 이용한다", "가로 1, 세로 1인 직각삼각형의 빗변의 길이는 얼마일까?"], ["원점을 중심으로 그 대각선을 반지름으로 하는 원을 그려 수직선과 만나는 점을 찾는다", "길이가 √2인 선분을 수직선 위로 옮기려면 무엇을 그리면 될까?"]], "teach": "한 변이 1인 정사각형의 대각선은 √(1²+1²)=√2 야. 원점을 중심으로 그 길이를 반지름으로 원을 그리면 수직선의 오른쪽 점이 √2, 왼쪽 점이 −√2 야.", "again": "√5를 수직선 위에 나타낼 때 어떤 직각삼각형을 쓰는지 말해 봐.", "fig": true, "src": "32쪽", "miscon": "어림값 위치에 점을 찍음", "record": "피타고라스 정리와 원을 이용해 무리수의 위치를 정하는 방법을 모름", "figScene": {"title": "한 변이 1인 정사각형과 원", "axes": {"xMin": -2, "xMax": 2.4, "yMin": -1.6, "yMax": 1.8, "ticks": true}, "curves": [], "points": {"O": [0, 0], "A": [1, 0], "B": [1, 1], "C": [0, 1], "P": [1.4142, 0]}, "labels": [{"text": "", "dx": 0, "dy": 0, "point": "B"}, {"text": "P", "dx": 4, "dy": 16, "point": "P"}], "shapes": [{"points": ["O", "A", "B", "C"], "stroke": "#185FA5"}, {"points": ["O", "B"], "close": false, "stroke": "#D85A30"}], "circles": [{"center": "O", "through": "B", "color": "#9A9890", "style": "dashed"}]}}, {"kind": "함정", "q": "한 변이 1인 정사각형을 점 1을 꼭짓점으로 그리고 점 1을 중심으로 원을 그렸을 때, 오른쪽 점이 √2가 아니라 1+√2가 되는 이유는?", "ideas": [["원의 중심, 즉 기준점이 0이 아니라 1이다", "원의 중심이 수직선의 어느 점에 있어?"], ["기준점에서 오른쪽으로 √2만큼 가면 1+√2, 왼쪽으로 가면 1−√2이다", "기준점 1에서 왼쪽으로 √2만큼 가면 어떤 수가 될까?"]], "teach": "반지름은 √2 로 같지만 출발점이 1이야. 1에서 오른쪽으로 √2만큼 가면 1+√2, 왼쪽으로 가면 1−√2. 기준점이 어디인지 먼저 봐야 해.", "again": "점 2를 중심으로 반지름 √5인 원을 그렸을 때 수직선과 만나는 두 점을 말해 봐.", "fig": true, "src": "32~33쪽", "miscon": "기준점과 상관없이 반지름 값이 곧 좌표라고 생각함", "record": "기준점에서 반지름만큼 이동한다는 것을 좌표에 반영하지 못함", "figScene": {"title": "점 1을 꼭짓점으로 하는 정사각형", "axes": {"xMin": -1, "xMax": 3.2, "yMin": -1.6, "yMax": 1.8, "ticks": true}, "curves": [], "points": {"A": [1, 0], "B": [2, 0], "C": [2, 1], "D": [1, 1], "Q": [2.4142, 0]}, "labels": [{"text": "Q", "dx": 4, "dy": 16, "point": "Q"}], "shapes": [{"points": ["A", "B", "C", "D"], "stroke": "#185FA5"}, {"points": ["A", "C"], "close": false, "stroke": "#D85A30"}], "circles": [{"center": "A", "through": "C", "color": "#9A9890", "style": "dashed"}]}}], "m3-1|1. 실수와 그 계산|15. 실수의 대소 관계는 수직선을 이용하면 된다?": [{"kind": "성질", "q": "수직선과 실수는 어떤 관계이고, 수직선에서 두 실수의 크기는 어떻게 비교해?", "ideas": [["모든 실수는 수직선 위의 한 점에 대응하고, 수직선은 실수로 완전히 메워져 있다", "수직선 위의 점 중에서 실수가 대응하지 않는 점이 있을까?"], ["수직선에서 오른쪽에 있는 수가 왼쪽에 있는 수보다 크다", "수직선에서 더 큰 수는 왼쪽과 오른쪽 중 어디에 있지?"]], "teach": "유리수와 무리수를 합친 실수로 수직선이 빈틈 없이 채워져. 모든 실수가 수직선의 한 점에 대응하니까 크기도 유리수처럼 \"오른쪽이 더 크다\"로 비교해.", "again": "−√3과 −0.2를 수직선에 나타내면 어느 쪽이 더 큰지 말해 봐.", "fig": false, "src": "33~34쪽", "miscon": "무리수는 수직선에 나타낼 수 없다고 생각함", "record": "실수와 수직선 위의 점이 하나씩 대응한다는 것을 모름"}, {"kind": "방법", "q": "3+√7과 √7+√8의 크기를 어림값을 구하지 않고 어떻게 비교할 수 있어?", "ideas": [["양쪽에 똑같이 있는 √7은 두고 나머지 3과 √8만 비교한다", "두 수에 공통으로 들어 있는 수는 무엇이지?"], ["3=√9이고 √9>√8이므로 3+√7이 더 크다", "3을 근호로 나타내서 √8과 비교해 볼래?"]], "teach": "두 수 모두 √7이 더해져 있으니 나머지만 비교하면 돼(부등식의 성질). 3=√9 >√8 이니까 3+√7>√7+√8.", "again": "−√3+2와 1의 크기를 비교하는 방법을 말해 봐.", "fig": false, "src": "34쪽 예제 14", "miscon": "√7+√8을 √15로 합침", "record": "공통인 부분을 두고 나머지만 비교하는 방법을 모름"}, {"kind": "성질", "q": "1과 2 사이에 무리수가 몇 개나 있을까? 예를 들어 설명해 봐.", "ideas": [["서로 다른 두 수 사이에는 무리수가 무수히 많다", "1과 2 사이에 √2 말고 무리수가 또 있을까?"], ["두 수 사이에서 무리수를 하나 찾으면, 그 수와 한쪽 끝 사이에서 또 찾을 수 있어 끝없이 이어진다", "1과 √2 사이에도 무리수를 또 찾을 수 있을까?"]], "teach": "1과 2 사이에 √2가 있고, 1과 √2 사이에도 √1.5가 있어. 새로 찾은 두 수 사이에서도 계속 찾을 수 있으니 무리수는 무수히 많아. 두 무리수 사이의 유리수도 마찬가지야.", "again": "√2와 √3 사이에 유리수가 있는지 예를 들어 말해 봐.", "fig": false, "src": "33쪽 참고", "miscon": "무리수가 몇 개만 있다고 생각함", "record": "두 수 사이에 무리수가 무수히 많은 이유를 설명하지 못함"}], "m3-1|1. 실수와 그 계산|16. √5의 정수 부분과 소수 부분은?": [{"kind": "방법", "q": "√5의 정수 부분과 소수 부분은 어떻게 구해?", "ideas": [["√4<√5<√9처럼 제곱수 사이에 넣어 2<√5<3이므로 정수 부분은 2이다", "5는 어떤 두 제곱수 사이에 있지?"], ["소수 부분은 √5에서 정수 부분을 뺀 √5−2로 나타낸다", "소수 부분을 소수로 다 쓸 수 없다면 어떤 식으로 나타낼 수 있을까?"]], "teach": "4<5<9 이니까 √4<√5<√9, 즉 2<√5<3. 정수 부분은 2이고, (무리수)=(정수 부분)+(소수 부분) 이므로 소수 부분은 √5−2.", "again": "√10의 정수 부분과 소수 부분을 구하는 방법을 말해 봐.", "fig": false, "src": "34~35쪽", "miscon": "소수 부분을 어림값으로 씀", "record": "소수 부분을 (무리수)−(정수 부분)으로 나타내는 방법을 모름"}, {"kind": "이유", "q": "무리수의 소수 부분을 0.236처럼 쓰지 않고 √5−2처럼 빼기로 나타내는 이유는 뭘까?", "ideas": [["소수 부분은 순환하지 않는 무한소수라 정확한 값을 소수로 끝까지 쓸 수 없다", "√5=2.236…의 소수 부분은 어디서 끝날까?"], ["(무리수)=(정수 부분)+(소수 부분)이므로 빼면 정확한 값을 나타낼 수 있다", "√5를 정수 부분과 소수 부분의 합으로 쓰면, 소수 부분은 어떻게 나타낼 수 있지?"]], "teach": "√5의 소수 부분은 끝없이 이어져서 0.236 은 어림값일 뿐이야. 대신 √5=2+(소수 부분) 이니까 소수 부분=√5−2 로 쓰면 정확한 값이 돼.", "again": "√7의 소수 부분을 소수로 쓰면 안 되는 이유와 대신 쓰는 방법을 말해 봐.", "fig": false, "src": "34쪽", "miscon": "어림값 0.236을 정확한 소수 부분으로 봄", "record": "소수 부분을 빼기로 나타내는 이유(정확한 값)를 설명하지 못함"}], "m3-1|1. 실수와 그 계산|17. √x의 정수 부분이 3일 때, x가 될 수 있는 자연수의 개수는?": [{"kind": "방법", "q": "√x의 정수 부분이 3일 때 x가 될 수 있는 자연수를 구하는 방법을 말해 봐.", "ideas": [["정수 부분이 3이므로 3≤√x<4로 나타낸다", "정수 부분이 3인 수는 어떤 범위에 있지?"], ["각 변을 제곱해 9≤x<16으로 바꾼 뒤 그 범위의 자연수를 센다", "3≤√x<4 를 x에 대한 범위로 바꾸려면 어떻게 하지?"]], "teach": "정수 부분이 3이면 3≤√x<4 야. 모두 양수라 제곱해도 부등호가 그대로라서 9≤x<16. x는 9, 10, …, 15 로 7개.", "again": "√x의 정수 부분이 7일 때 x의 범위를 구하는 방법을 말해 봐.", "fig": false, "src": "35쪽", "miscon": "정수 부분이 3이면 x=9 하나라고 생각함", "record": "정수 부분 조건을 부등식으로 바꾸고 제곱해 범위를 구하는 방법을 모름"}, {"kind": "함정", "q": "3≤√x<4를 9<x≤16이나 9≤x≤16으로 바꾸면 왜 틀릴까?", "ideas": [["√x=3일 때 정수 부분이 3이므로 x=9는 포함된다", "√9의 정수 부분은 몇이지?"], ["√x=4이면 정수 부분이 4가 되므로 x=16은 빠져야 한다", "√16의 정수 부분은 3일까?"]], "teach": "√9=3 은 정수 부분이 3이라 포함, √16=4 는 정수 부분이 4라 제외. 그래서 9 이상 16 미만, 등호 위치를 조심해.", "again": "√x의 정수 부분이 5일 때 x의 범위의 양 끝을 어떻게 정하는지 말해 봐.", "fig": false, "src": "35쪽", "miscon": "범위의 양 끝을 모두 빼거나 모두 넣음", "record": "범위의 양 끝(등호)을 정하는 기준을 설명하지 못함"}], "m3-1|1. 실수와 그 계산|18. √a√b는 어떻게 계산할까?": [{"kind": "방법", "q": "a>0, b>0 일 때 √a×√b 를 근호 하나로 나타내는 방법과, 2√3×5√2 처럼 근호 밖에도 수가 있을 때 계산하는 방법을 말해 봐.", "ideas": [["근호 안의 수끼리 곱해서 근호 하나로 만든다", "√2×√3 을 근호 하나로 쓰면 근호 안에는 무엇이 들어갈까?"], ["근호 밖의 수는 근호 밖의 수끼리 곱한다", "근호 밖에 있는 2와 5는 어디에 어떻게 계산해야 할까?"]], "teach": "제곱근끼리 곱할 때는 근호 안의 수끼리 곱해서 √a×√b=√(ab). 근호 밖에 수가 있으면 밖은 밖끼리, 안은 안끼리 곱해. 2√3×5√2=(2×5)√(3×2)=10√6.", "again": "3√5×2√6 을 계산하는 방법을 말로 설명해 봐.", "fig": false, "src": "45쪽", "miscon": "근호 안의 수끼리 더함", "record": "근호 밖·안을 나누어 곱하는 방법을 모름"}, {"kind": "이유", "q": "√a×√b=√(ab) (a>0, b>0) 가 성립하는 이유를, √a×√b 를 제곱해 보는 방법으로 설명해 봐.", "ideas": [["√a×√b 를 제곱하면 (√a)²×(√b)² 이 되어 ab 가 된다", "√a×√b 를 제곱하면 (√a)² 과 (√b)² 은 각각 무엇이 될까?"], ["√a×√b 는 양수이면서 제곱하면 ab 이므로 ab 의 양의 제곱근 √(ab) 와 같다", "제곱해서 ab 가 되는 수 중에서 양수인 것을 기호로 어떻게 쓰지?"]], "teach": "(√a×√b)²=(√a)²×(√b)²=ab 야. 즉 √a×√b 는 \"제곱하면 ab 가 되는 양수\", 곧 ab 의 양의 제곱근이야. 그걸 기호로 쓰면 √(ab) 라서 둘이 같아.", "again": "√2×√3 이 √6 과 같다는 것을 제곱근의 뜻을 써서 말해 봐.", "fig": false, "src": "45쪽", "miscon": "규칙을 이유 없이 외움", "record": "√a×√b=√(ab)를 제곱근의 뜻으로 설명하지 못함"}], "m3-1|1. 실수와 그 계산|19. √b/√a는 어떻게 계산할까?": [{"kind": "방법", "q": "a>0, b>0 일 때 √b÷√a 를 근호 하나로 나타내는 방법과, 4√6÷2√3 처럼 근호 밖에도 수가 있을 때 계산하는 방법을 말해 봐.", "ideas": [["근호 안의 수끼리 나누어 근호 하나로 만든다", "√6÷√2 를 근호 하나로 쓰면 근호 안에는 무엇이 들어갈까?"], ["근호 밖의 수는 근호 밖의 수끼리 나눈다", "근호 밖에 있는 4와 2는 어떻게 계산해야 할까?"]], "teach": "제곱근끼리 나눌 때는 근호 안의 수끼리 나눠서 √b÷√a=√(b/a). 근호 밖의 수는 밖끼리 나눠. 4√6÷2√3=(4÷2)√(6÷3)=2√2.", "again": "6√10÷3√5 를 계산하는 방법을 말로 설명해 봐.", "fig": false, "src": "46쪽", "miscon": "근호 안의 수끼리 뺌", "record": "제곱근의 나눗셈에서 안·밖을 나누어 계산하는 방법을 모름"}, {"kind": "방법", "q": "√3÷(√2/√5) 처럼 분수 꼴의 제곱근으로 나눌 때는 먼저 식을 어떻게 바꿔서 계산해?", "ideas": [["나누는 수의 역수를 곱하는 곱셈으로 바꾼다", "분수로 나눌 때 나눗셈을 무엇으로 바꿨었지?"], ["곱셈으로 바꾼 뒤 근호 안은 안끼리, 밖은 밖끼리 계산한다", "곱셈으로 바꾼 다음에는 근호 안의 수들을 어떻게 계산하면 될까?"]], "teach": "분수로 나누는 건 역수를 곱하는 것과 같아. √3÷(√2/√5)=√3×(√5/√2) 로 바꾸면 제곱근의 곱셈이 되니까 근호 안끼리 곱하고 나누면 돼.", "again": "√6÷(√3/√2) 를 계산할 때 가장 먼저 무엇을 하는지 말해 봐.", "fig": false, "src": "46쪽", "miscon": "분모끼리, 분자끼리 따로 나눔", "record": "분수로 나누는 제곱근을 역수의 곱셈으로 바꾸지 못함"}], "m3-1|1. 실수와 그 계산|20. √(a²b)를 간단히 나타내면?": [{"kind": "방법", "q": "√12 처럼 근호 안에 제곱인 인수가 들어 있을 때, 근호 안의 수를 가장 작은 자연수로 만드는 방법을 말해 봐.", "ideas": [["근호 안의 수를 소인수분해해서 제곱인 인수를 찾는다", "12를 소인수분해하면 제곱인 부분이 보일까?"], ["제곱인 인수는 그 제곱근을 근호 밖으로 꺼내고 나머지는 근호 안에 남긴다", "12=2²×3 에서 2² 이 근호 밖으로 나오면 무엇이 될까?"]], "teach": "근호 안을 소인수분해해서 제곱인 인수를 찾아. 12=2²×3 이니까 2² 은 밖으로 나와 2가 되고 3은 안에 남아서 √12=2√3. 50=5²×2 라서 √50=5√2.", "again": "√18 을 a√b 꼴로 바꾸는 방법을 말해 봐.", "fig": false, "src": "47~48쪽", "miscon": "근호 안을 2로 나눠 꺼냄", "record": "제곱인 인수를 찾아 근호 밖으로 꺼내는 방법을 모름"}, {"kind": "이유", "q": "a>0, b>0 일 때 √(a²b)=a√b 가 되는 이유를 제곱근의 곱셈을 이용해 설명해 봐.", "ideas": [["√(a²b) 를 √(a²)×√b 로 나눌 수 있다", "근호 안의 곱 a²×b 를 근호 두 개의 곱으로 나눌 수 있을까?"], ["a>0 이면 √(a²)=a 이다", "a 가 양수일 때 √(a²) 은 무엇이지?"]], "teach": "제곱근의 곱셈을 거꾸로 쓰면 √(a²b)=√(a²)×√b 야. a 가 양수면 √(a²)=a 라서 a√b 가 돼.", "again": "√(3²×5) 가 3√5 와 같은 이유를 한 문장으로 말해 봐.", "fig": false, "src": "47쪽", "miscon": "a²에서 2를 나눠 a가 된다고 봄", "record": "√(a²b)=a√b를 제곱근의 곱셈과 √(a²)=a로 설명하지 못함"}, {"kind": "함정", "q": "3√2 나 −4√2 처럼 근호 밖의 수를 근호 안으로 넣을 때, 각각 무엇을 조심해야 해?", "ideas": [["근호 밖의 양수는 제곱해서 근호 안에 넣는다", "근호 밖의 3이 근호 안으로 들어가면 3 그대로일까?"], ["음수 부호(−)는 근호 안으로 들어갈 수 없어서 근호 밖에 남긴다", "근호 안에 음수를 넣어서 √ 값이 음수가 될 수 있을까?"]], "teach": "3√2 는 3=√9 이니까 √(3²×2)=√18. −4√2 는 4만 제곱해서 넣고 − 는 밖에 남겨 −√32. √ 로 나타낸 값은 항상 0 이상이라 − 는 들어갈 수 없어.", "again": "−2√5 를 −√a 꼴로 나타낼 때 조심할 점을 말해 봐.", "fig": false, "src": "48쪽", "miscon": "−4√2를 √32로 만듦(− 부호를 근호 안으로 넣음)", "record": "근호 밖의 − 부호를 근호 안으로 넣을 수 없다는 것을 모름"}], "m3-1|1. 실수와 그 계산|21. 분모의 유리화란?": [{"kind": "뜻", "q": "분모의 유리화는 무엇이고, 1/√3 처럼 분모에 √3 이 있으면 무엇을 해서 유리화해?", "ideas": [["무리수인 분모를 유리수로 고치는 것이다", "분모에 √ 가 있을 때 그 분모를 어떤 수로 바꾸는 걸 유리화라고 할까?"], ["분모와 분자에 똑같이 √3 을 곱한다", "√3 에 무엇을 곱하면 근호가 없어질까? 그걸 분모에만 곱해도 될까?"]], "teach": "분모의 유리화는 분모가 근호를 포함한 무리수일 때 분모를 유리수로 고치는 거야. 1/√3 은 분모·분자에 √3 을 곱해서 √3/3.", "again": "5/√7 의 분모를 유리화하려면 무엇을 어디에 곱하는지 말해 봐.", "fig": false, "src": "48~49쪽", "miscon": "분모에만 √3을 곱함", "record": "분모·분자에 같은 수를 곱해 유리화하는 방법을 모름"}, {"kind": "이유", "q": "분모를 유리화할 때 분모와 분자에 같은 수를 곱해도 분수의 값이 변하지 않는 이유는 뭘까?", "ideas": [["분모와 분자에 같은 수를 곱하는 것은 1을 곱하는 것과 같다", "√3/√3 은 얼마일까? 그걸 곱하면 값이 바뀔까?"]], "teach": "분모와 분자에 똑같이 √3 을 곱하는 건 √3/√3, 즉 1을 곱하는 거야. 어떤 수에 1을 곱해도 값은 그대로라서 모양만 바뀌고 값은 같아.", "again": "3/√2 의 분모와 분자에 √2 를 곱해도 괜찮은 이유를 한 문장으로 말해 봐.", "fig": false, "src": "48쪽", "miscon": "같은 수를 곱하면 값이 커진다고 생각함", "record": "분모·분자에 같은 수를 곱해도 값이 같은 이유(1을 곱함)를 설명하지 못함"}], "m3-1|1. 실수와 그 계산|22. 곱셈과 나눗셈이 섞여 있는 제곱근의 계산은 어떻게 할까?": [{"kind": "방법", "q": "√8×√6÷√3 처럼 제곱근의 곱셈과 나눗셈이 섞여 있는 식은 어떤 순서로 계산해?", "ideas": [["나눗셈은 역수의 곱셈으로 바꾼다", "나눗셈이 섞여 있으면 먼저 무엇으로 바꾸면 곱셈만 남을까?"], ["근호 안은 안끼리, 근호 밖은 밖끼리 계산한다", "곱셈만 남으면 근호 안의 수들은 어떻게 계산하지?"], ["마지막에 근호 안을 가장 작은 자연수로 만들거나 분모를 유리화한다", "계산이 끝났는데 근호 안에 제곱인 인수가 남아 있으면 어떻게 할까?"]], "teach": "÷√3 을 ×(1/√3) 로 바꾸면 곱셈만 남아. 근호 안끼리 계산하면 √(8×6÷3)=√16=4. 결과에 제곱인 인수가 남거나 분모에 √ 가 있으면 마지막에 정리해.", "again": "√18÷√6×√2 를 계산하는 순서를 말해 봐.", "fig": false, "src": "50쪽", "miscon": "근호 밖의 수를 근호 안에 그냥 곱함", "record": "곱셈·나눗셈이 섞인 제곱근 계산 순서를 모름"}, {"kind": "함정", "q": "√12÷√3×√2 를 √12÷(√3×√2) 처럼 계산하면 왜 틀릴까?", "ideas": [["÷√3 다음에 오는 ×√2 까지 나누는 수로 묶어 버렸다", "÷√3 뒤에 있는 ×√2 는 나누는 수일까, 곱하는 수일까?"], ["나눗셈을 역수의 곱셈으로 바꾸면 √2 는 곱해져야 한다", "÷√3 을 ×(1/√3) 로 바꿔 쓰면 √2 는 식의 어디에 있게 될까?"]], "teach": "÷√3 을 ×(1/√3) 로 바꾸면 √12×(1/√3)×√2 라서 √2 는 곱해지는 수야. 맞게 하면 2√2, 괄호로 묶으면 √2 가 나와서 틀려.", "again": "곱셈과 나눗셈이 섞인 식에서 나눗셈을 역수의 곱셈으로 바꾸면 좋은 점을 말해 봐.", "fig": false, "src": "50쪽", "miscon": "나눗셈 뒤에 오는 수를 모두 나누는 수로 묶음", "record": "나눗셈을 역수의 곱셈으로 바꿔 순서를 바르게 처리하지 못함"}], "m3-1|1. 실수와 그 계산|23. 제곱근의 덧셈과 뺄셈은 다항식의 계산과 비슷하다?": [{"kind": "방법", "q": "2√3+4√3 처럼 근호 안의 수가 같은 제곱근끼리 더하거나 뺄 때 어떻게 계산하고, 왜 다항식 계산과 비슷하다고 할까?", "ideas": [["근호 부분은 그대로 두고 앞의 수(계수)끼리 더하거나 뺀다", "2√3+4√3 에서 √3 은 그대로 두고 무엇을 계산할까?"], ["√3 을 문자 x 처럼 보면 2x+4x 같은 동류항 계산과 같다", "√3 자리에 x 를 넣으면 어떤 다항식 계산이 될까?"]], "teach": "√3 을 x 라고 보면 2√3+4√3 은 2x+4x=6x 와 같은 모양이라 6√3. 근호 부분은 그대로, 계수만 계산해.", "again": "5√2−2√2 를 다항식 계산에 빗대어 설명해 봐.", "fig": false, "src": "52쪽", "miscon": "근호 안의 수까지 더함", "record": "제곱근의 덧셈을 동류항 계산과 연결하지 못함"}, {"kind": "함정", "q": "곱셈에서는 √2×√3=√6 이 되는데, 덧셈에서는 √2+√3 이 √5 가 되지 않아. 왜 그런지 말해 봐.", "ideas": [["근호 안의 수끼리 합칠 수 있는 규칙은 곱셈과 나눗셈에만 있고 덧셈·뺄셈에는 없다", "√a×√b=√(ab) 같은 규칙이 덧셈에도 있었어?"], ["어림값으로 확인하면 √2+√3 은 약 3.1 이고 √5 는 약 2.2 라서 다르다", "√2≈1.4, √3≈1.7 을 더한 값과 √5≈2.2 를 비교해 볼래?"]], "teach": "√a×√b=√(ab) 는 제곱해서 확인한 곱셈의 규칙이야. 덧셈에는 그런 규칙이 없어서 √a+√b≠√(a+b). 실제로 √2+√3≈1.41+1.73=3.14 인데 √5≈2.24 야.", "again": "√9+√16 과 √25 를 계산해서 비교하면 무엇을 알 수 있는지 말해 봐.", "fig": false, "src": "53쪽 주의", "miscon": "덧셈도 근호 안끼리 더할 수 있다고 생각함", "record": "√a+√b≠√(a+b)인 이유를 설명하지 못함"}], "m3-1|1. 실수와 그 계산|24. 근호 안의 수가 같아야만 덧셈, 뺄셈을 할 수 있다?": [{"kind": "방법", "q": "3√2+5√8 처럼 근호 안의 수가 달라 보일 때, 더할 수 있는지 어떻게 확인하고 계산해?", "ideas": [["근호 안을 가장 작은 자연수로 먼저 바꾼다(√8=2√2)", "√8 의 근호 안에 제곱인 인수가 숨어 있을까?"], ["바꾼 뒤 근호 안의 수가 같아지면 계수끼리 계산한다", "간단히 한 다음 두 항의 근호 안이 같아졌다면 어떻게 계산할까?"]], "teach": "근호 안을 가장 작은 자연수로 만들어 비교해. √8=2√2 라서 3√2+5√8=3√2+10√2=13√2. 간단히 해도 근호 안이 다르면(2√3+3√5) 더 합칠 수 없어.", "again": "√18+√50 을 계산하기 전에 먼저 해야 할 일을 말해 봐.", "fig": false, "src": "53쪽", "miscon": "근호 안이 달라 보이면 계산할 수 없다고 판단함", "record": "근호 안을 가장 작은 자연수로 바꾼 뒤 비교하는 방법을 모름"}, {"kind": "함정", "q": "√3+2/√3 은 두 항에 모두 √3 이 보이는데 바로 더할 수 없어. 먼저 무엇을 해야 하고 왜 그래?", "ideas": [["2/√3 의 분모를 유리화해 2√3/3 으로 바꾼다", "2/√3 은 분모에 √ 가 있어. 그걸 먼저 어떻게 고치지?"], ["유리화하면 두 항이 모두 (수)×√3 꼴이 되어 계수끼리 계산할 수 있다", "2√3/3 과 √3 은 모두 무엇이 곱해진 꼴이야?"]], "teach": "2/√3 은 √3 이 분모에 있어서 √3 의 동류항 모양이 아니야. 유리화하면 2√3/3 이 되어 √3+2√3/3=(1+2/3)√3=5√3/3.", "again": "√48−6/√3 을 계산할 때 순서를 말해 봐.", "fig": false, "src": "53쪽", "miscon": "분모에 근호가 있는데도 동류항으로 보고 바로 더함", "record": "분모의 근호를 먼저 유리화해야 동류항이 된다는 것을 모름"}], "m3-1|1. 실수와 그 계산|25. 뺄셈을 이용하여 두 실수의 대소 관계를 알 수 있다?": [{"kind": "방법", "q": "두 실수 a, b 의 크기를 뺄셈을 이용해 비교하는 방법을 말해 봐.", "ideas": [["a−b 를 계산해서 그 부호를 본다", "a 와 b 의 차를 구하면 무엇을 확인하면 될까?"], ["a−b>0 이면 a>b, a−b<0 이면 a<b, a−b=0 이면 a=b", "a−b 가 음수라면 a 와 b 중 어느 쪽이 작을까?"]], "teach": "두 수의 차 a−b 의 부호를 보면 돼. 양수면 a 가 크고, 음수면 a 가 작고, 0이면 같아. 무리수가 섞여도 차의 부호만 알면 비교할 수 있어.", "again": "(3+√2)−4 가 음수라면 3+√2 와 4 중 어느 수가 큰지 말해 봐.", "fig": false, "src": "54쪽", "miscon": "a−b를 쓰는 방법은 알지만 음수일 때 대소 방향을 반대로 판단함", "record": "방법은 기억하지만 a−b가 음수일 때 대소 방향을 반대로 판단함"}, {"kind": "적용", "q": "5−√30 이 양수인지 음수인지 계산기 없이 어떻게 알 수 있어?", "ideas": [["5 를 √25 로 바꾼다", "5 를 근호가 있는 수로 나타내면 어떻게 될까?"], ["√25 와 √30 을 비교하면 근호 안이 작은 √25 가 더 작으므로 5−√30<0 이다", "근호 안의 수가 클수록 제곱근의 크기는 어떻게 될까?"]], "teach": "5=√25 야. 양수의 제곱근은 근호 안의 수가 클수록 크니까 √25<√30. 그래서 5−√30 은 음수이고 5<√30.", "again": "4−√15 의 부호를 판단하는 방법을 말해 봐.", "fig": false, "src": "54쪽", "miscon": "5−30으로 계산해 결론만 맞힘", "record": "근호가 없는 수를 근호로 바꿔 부호를 판단하는 방법을 모름"}], "m3-1|1. 실수와 그 계산|26. 사칙 계산이 섞여 있는 근호를 포함한 식의 계산은 어떻게 할까?": [{"kind": "방법", "q": "괄호, 곱셈, 나눗셈, 덧셈, 뺄셈이 섞여 있는 근호를 포함한 식은 어떤 순서로 계산해?", "ideas": [["괄호가 있으면 괄호 안을 먼저 계산하거나, 필요하면 분배법칙으로 괄호를 푼다", "괄호가 있으면 가장 먼저 무엇을 처리하지?"], ["곱셈·나눗셈을 먼저 하고 덧셈·뺄셈을 나중에 한다", "유리수 계산에서 곱셈·나눗셈과 덧셈·뺄셈 중 무엇을 먼저 했지?"], ["근호 안의 제곱인 인수는 꺼내고 분모의 무리수는 유리화한 뒤 동류항끼리 계산한다", "마지막에 더하고 빼기 전에 각 항을 어떤 꼴로 정리해 둬야 할까?"]], "teach": "순서는 유리수 계산과 같아: 괄호(괄호 안 계산, 또는 분배법칙으로 풀기) → 곱셈·나눗셈 → 덧셈·뺄셈. 중간에 근호 안의 제곱인 인수는 꺼내고, 분모의 무리수는 유리화해서 근호 안이 같은 항끼리 모아.", "again": "√3(√2+2√3) 을 계산할 때 가장 먼저 무엇을 하는지 말해 봐.", "fig": false, "src": "55쪽", "miscon": "앞에서부터 차례로 계산함", "record": "근호가 섞인 식의 계산 순서(괄호→곱셈·나눗셈→덧셈·뺄셈)를 모름"}, {"kind": "함정", "q": "4√5−√6×√10÷√3 을 계산할 때 4√5−√6 부터 먼저 계산하려고 하면 왜 틀릴까?", "ideas": [["곱셈·나눗셈을 덧셈·뺄셈보다 먼저 해야 한다", "이 식에서 뺄셈과 곱셈·나눗셈 중 무엇을 먼저 해야 할까?"], ["4√5 와 √6 은 근호 안의 수가 달라 뺄 수도 없다", "4√5 와 √6 은 근호 안의 수가 같아?"]], "teach": "곱셈·나눗셈 먼저: √6×√10÷√3=√20=2√5. 그다음 4√5−2√5=2√5. 게다가 4√5 와 √6 은 근호 안이 달라서 처음부터 뺄 수 없는 두 수야.", "again": "곱셈·나눗셈과 덧셈·뺄셈이 섞인 근호 식에서 계산 순서를 지켜야 하는 이유를 말해 봐.", "fig": false, "src": "55쪽", "miscon": "덧셈·뺄셈을 먼저 해도 된다고 생각함", "record": "계산 순서와 동류항 조건을 함께 적용하지 못함"}], "m3-1|1. 실수와 그 계산|27. 제곱근표에 없는 수에 대한 제곱근의 어림한 값은 어떻게 알 수 있을까?": [{"kind": "방법", "q": "제곱근표에는 1.00부터 99.9까지의 수만 있어. √200 처럼 표에 없는 수의 제곱근의 어림값은 어떻게 구해?", "ideas": [["근호 안의 수를 100이나 10000 과 표에 있는 수의 곱(또는 나눗셈)으로 바꾼다", "200 을 100×(표에 있는 수) 로 나타내면 어떻게 될까?"], ["√100=10 처럼 꺼낸 수의 제곱근을 곱하거나 나누어 어림값을 구한다", "√(100×2) 에서 100 이 근호 밖으로 나오면 얼마가 될까?"]], "teach": "200=100×2 로 바꾸면 √200=√100×√2=10√2≈10×1.414=14.14. 0.02=2/100 이면 √0.02=√2/10≈0.1414. 표에 있는 수로 바꾼 뒤 10, 100 을 곱하거나 나눠.", "again": "√3000 의 어림값을 제곱근표로 구하는 방법을 말해 봐.", "fig": false, "src": "56쪽", "miscon": "표에 없는 수는 어림할 수 없다고 생각함", "record": "근호 안을 100배·1/100 꼴로 바꿔 제곱근표를 쓰는 방법을 모름"}, {"kind": "함정", "q": "√2≈1.414 를 이용해 √200 을 구하면서 200=100×2 이니까 100×1.414 라고 하면 왜 틀릴까?", "ideas": [["√(100×2) 는 100×√2 가 아니라 √100×√2=10√2 이다", "100 을 근호 밖으로 꺼내면 100 그대로 나올까?"], ["그래서 근호 안의 수가 100배가 되면 제곱근은 10배가 된다", "근호 안이 100배일 때 제곱근은 몇 배가 될까?"]], "teach": "근호 안의 100 은 밖으로 나올 때 √100=10 이 돼. 그래서 √200=10×1.414=14.14. 근호 안이 100배면 제곱근은 10배, 10000배면 100배야.", "again": "근호 안의 수가 10000배가 되면 제곱근의 값은 몇 배가 되는지 이유와 함께 말해 봐.", "fig": false, "src": "56쪽", "miscon": "근호 안이 100배면 제곱근도 100배라고 생각함", "record": "근호 안의 배수와 제곱근의 배수 관계를 설명하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|28. (다항식)×(다항식)은 어떻게 계산할까?": [{"kind": "방법", "q": "(a+b)(c+d)처럼 다항식끼리 곱할 때 어떤 방법으로 계산하고, 마지막에 무엇을 해?", "ideas": [["분배법칙으로 한 식의 각 항을 다른 식의 각 항에 빠짐없이 곱한다", "(a+b)(c+d)에서 a는 c와 d 중 어디에 곱해야 할까?"], ["곱한 뒤 동류항끼리 모아 간단히 정리한다", "전개한 결과에 문자와 차수가 같은 항이 있으면 어떻게 할까?"]], "teach": "(a+b)(c+d)=ac+ad+bc+bd. 앞 식의 모든 항을 뒤 식의 모든 항에 한 번씩 곱하고, 동류항이 있으면 모아서 정리해. 가로 a+b, 세로 c+d인 직사각형을 네 칸으로 나눈 넓이의 합과 같아.", "again": "(2a+3)(a−4)를 전개하는 방법을 말로 설명해 봐.", "fig": false, "src": "80쪽", "miscon": "(a+b)(c+d)=ac+bd처럼 같은 자리끼리만 곱함", "record": "다항식의 곱에서 모든 항끼리 빠짐없이 곱하는 분배법칙을 적용하지 못함"}, {"kind": "함정", "q": "(a+b)(x+y+z)처럼 한쪽 식의 항이 3개일 때 빠뜨리지 않고 전개하려면 어떻게 해야 해? 동류항 정리 전에 항은 몇 개가 나올까?", "ideas": [["앞 식의 항 하나씩을 차례로 뒤 식의 모든 항에 곱한다", "a를 곱할 때 x, y, z 중 몇 개에 곱해야 할까?"], ["항이 2개와 3개이므로 정리 전에 2×3, 즉 6개의 항이 나온다", "a가 만드는 항과 b가 만드는 항을 합치면 몇 개일까?"]], "teach": "a를 x, y, z에 모두 곱하고, 이어서 b를 x, y, z에 모두 곱해: ax+ay+az+bx+by+bz. 항이 2개와 3개면 곱한 항은 2×3=6개라서, 개수를 세어 보면 빠뜨렸는지 확인할 수 있어.", "again": "(x+y)(x−y+2)를 전개하면 정리 전에 항이 몇 개 나오는지와 그 이유를 말해 봐.", "fig": false, "src": "81쪽", "miscon": "항의 개수가 다르면 일부 항을 빠뜨림", "record": "항이 3개 이상인 다항식의 곱을 빠뜨리지 않고 전개하는 방법을 모름"}], "m3-1|2. 다항식의 곱셈과 인수분해|29. (a+b)²과 (a-b)²은 어떻게 전개할까?": [{"kind": "성질", "q": "(a+b)²을 전개하면 어떤 식이 되고, 가운데 항이 2ab가 되는 이유는 뭘까?", "ideas": [["(a+b)²=a²+2ab+b²이다", "(a+b)(a+b)를 전개하면 어떤 항들이 나올까?"], ["전개할 때 ab와 ba가 한 번씩 나와서 ab가 두 번, 곧 2ab가 된다", "(a+b)(a+b)에서 a×b와 b×a는 각각 몇 번 나오지?"]], "teach": "(a+b)²=(a+b)(a+b)=a²+ab+ba+b²=a²+2ab+b². 한 변이 a+b인 정사각형을 나누면 a², b² 정사각형 하나씩과 ab 직사각형 두 개가 생겨.", "again": "(x+3)²을 전개할 때 가운데 항이 6x가 되는 이유를 말해 봐.", "fig": true, "src": "81~82쪽", "miscon": "(a+b)²=a²+b²으로 가운데 항을 빠뜨림", "record": "합의 제곱에서 2ab 항이 생기는 이유를 설명하지 못함", "figScene": {"points": {"A": [90, 60], "B": [340, 60], "C": [340, 310], "D": [90, 310], "T": [260, 60], "U": [260, 310], "L": [90, 230], "R": [340, 230]}, "shapes": [{"points": ["A", "B", "C", "D"], "fill": "#eef3f9", "stroke": "#185FA5"}, {"points": ["T", "U"], "close": false, "stroke": "#185FA5"}, {"points": ["L", "R"], "close": false, "stroke": "#185FA5"}], "labels": [{"text": "a", "dx": -6, "dy": -10, "at": [175.0, 60]}, {"text": "b", "dx": -6, "dy": -10, "at": [300.0, 60]}, {"text": "a", "dx": -26, "dy": 5, "at": [90, 145.0]}, {"text": "b", "dx": -26, "dy": 5, "at": [90, 270.0]}], "title": "한 변이 a+b인 정사각형"}}, {"kind": "함정", "q": "(a−b)²을 전개하면 어떻게 되고, (b−a)²은 (a−b)²과 같을까 다를까?", "ideas": [["(a−b)²=a²−2ab+b²으로 가운데 항의 부호만 −이다", "(a−b)(a−b)에서 a×(−b)의 부호는 어떻게 될까?"], ["b−a는 a−b의 부호를 바꾼 수라서 제곱하면 (a−b)²과 같다", "−3과 3을 각각 제곱하면 결과가 같을까?"]], "teach": "(a−b)²=a²−ab−ba+b²=a²−2ab+b², 끝 항 b²은 +야. b−a=−(a−b)이고 부호가 반대인 수를 제곱하면 같아서 (b−a)²=(a−b)². (x−3y)²처럼 계수가 있으면 (3y)²=9y²까지 제곱해야 해.", "again": "(−x+2)²과 (x−2)²이 같은 이유를 말해 봐.", "fig": false, "src": "82쪽", "miscon": "(a−b)²=a²−b²이나 a²−2ab−b²으로 부호를 틀림", "record": "차의 제곱에서 각 항의 부호와 (a−b)²=(b−a)²인 이유를 설명하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|30. (a+b)(a-b)는 어떻게 전개할까?": [{"kind": "성질", "q": "(a+b)(a−b)를 전개하면 왜 항이 두 개만 남을까?", "ideas": [["전개하면 −ab와 +ab가 서로 없어진다", "(a+b)(a−b)를 하나씩 곱했을 때 ab가 들어간 항들은 부호가 어떻게 돼?"], ["그래서 a²−b², 곧 (제곱)−(제곱)만 남는다", "없어지고 남는 두 항은 무엇과 무엇이야?"]], "teach": "(a+b)(a−b)=a²−ab+ba−b²=a²−b². 가운데 −ab와 +ab가 지워져서 합과 차의 곱은 \"제곱 빼기 제곱\"이 돼.", "again": "(x+5)(x−5)를 전개하면 x항이 없는 이유를 말해 봐.", "fig": true, "src": "82쪽", "miscon": "합과 차의 곱을 a²+b²이나 a²−2ab+b²으로 봄", "record": "합과 차의 곱에서 가운데 항이 사라지는 이유를 설명하지 못함", "figScene": {"title": "한 변이 a인 정사각형에서 한 변이 b인 정사각형을 떼어 냄", "points": {"A": [100, 60], "B": [320, 60], "C": [320, 280], "D": [100, 280], "E": [240, 200], "F": [320, 200], "G": [240, 280]}, "shapes": [{"points": ["A", "B", "C", "D"], "fill": "#eef3f9", "stroke": "#185FA5"}, {"points": ["E", "F", "C", "G"], "fill": "#ffffff", "stroke": "#D85A30", "style": "dashed"}], "labels": [{"text": "a", "dx": -4, "dy": -10, "at": [210, 60]}, {"text": "a", "dx": -20, "dy": 5, "at": [100, 170]}, {"text": "b", "dx": -4, "dy": 20, "at": [280, 280]}, {"text": "b", "dx": 8, "dy": 5, "at": [320, 240]}]}}, {"kind": "함정", "q": "(−a+b)(a+b)를 합과 차의 곱 공식으로 전개하려면 어떻게 봐야 할까?", "ideas": [["교환법칙으로 순서를 바꿔 (b−a)(b+a)로 본다", "−a+b를 순서를 바꿔 쓰면 어떤 꼴이 될까?"], ["두 식에서 부호가 같은 b의 제곱에서 부호가 다른 a의 제곱을 빼 b²−a²이 된다", "두 괄호에서 부호가 같은 문자와 부호가 다른 문자는 각각 무엇이지?"]], "teach": "(−a+b)(a+b)=(b−a)(b+a)=b²−a². 두 식에서 부호가 같은 항의 제곱이 앞, 부호가 다른 항의 제곱을 빼. 순서만 보고 a²−b²이라고 쓰면 부호가 반대가 돼.", "again": "(−x−3)(x−3)을 공식으로 전개할 때 어떤 항의 제곱이 앞에 오는지 말해 봐.", "fig": false, "src": "83쪽 예제 3", "miscon": "항의 순서만 보고 a²−b²으로 씀", "record": "부호가 같은 항과 다른 항을 구분해 합과 차의 곱을 적용하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|31. (x+a)(x+b)는 어떻게 전개할까?": [{"kind": "성질", "q": "(x+a)(x+b)를 전개하면 x의 계수와 상수항은 각각 무엇이 될까? 이유도 말해 봐.", "ideas": [["x의 계수는 두 상수의 합 a+b이다", "전개했을 때 x가 들어간 항 bx와 ax를 모으면 계수가 뭐가 되지?"], ["상수항은 두 상수의 곱 ab이다", "x가 없는 항은 무엇과 무엇을 곱해서 생겨?"]], "teach": "(x+a)(x+b)=x²+bx+ax+ab=x²+(a+b)x+ab. 처음 식의 두 상수를 더하면 x의 계수, 곱하면 상수항이야.", "again": "(x+3)(x+4)에서 x의 계수와 상수항을 구하는 방법을 말해 봐.", "fig": false, "src": "83쪽", "miscon": "계수와 상수항 자리에 곱과 합을 바꿔 씀", "record": "(x+a)(x+b)에서 합과 곱이 각각 어디에 오는지 설명하지 못함"}, {"kind": "함정", "q": "(x−2)(x+5)처럼 부호가 다른 상수가 있을 때 x의 계수와 상수항을 구하면서 조심할 점은?", "ideas": [["상수를 부호까지 포함해 −2와 +5로 본다", "(x−2)에서 더해지는 수는 2일까, −2일까?"], ["합과 곱을 부호까지 계산해서 합은 양수, 곱은 음수가 될 수 있다", "−2와 5를 곱하면 부호가 어떻게 돼?"]], "teach": "(x−2)(x+5)는 (x+(−2))(x+5)야. x의 계수는 (−2)+5, 상수항은 (−2)×5라서 x²+3x−10. 부호를 떼고 2와 5로 계산하면 틀려.", "again": "(x−4)(x−3)의 상수항이 양수가 되는 이유를 말해 봐.", "fig": false, "src": "83쪽 예제 4", "miscon": "상수의 부호를 빼고 합·곱을 계산함", "record": "상수의 부호를 포함해 합과 곱을 계산하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|32. (ax+b)(cx+d)는 어떻게 전개할까?": [{"kind": "성질", "q": "(ax+b)(cx+d)를 전개하면 x²의 계수, x의 계수, 상수항은 각각 어떻게 구해?", "ideas": [["x²의 계수는 x의 계수끼리 곱한 ac이다", "ax와 cx를 곱하면 무엇이 나와?"], ["x의 계수는 ad와 bc를 더한 것이다", "x가 한 번만 들어가는 항은 어떤 두 곱에서 생길까?"], ["상수항은 상수끼리 곱한 bd이다", "x가 없는 항은 무엇끼리 곱해서 생기지?"]], "teach": "(ax+b)(cx+d)=acx²+adx+bcx+bd=acx²+(ad+bc)x+bd. x의 계수는 \"바깥끼리 곱 ad\"와 \"안쪽끼리 곱 bc\"의 합이야.", "again": "(2x+1)(3x+5)에서 x의 계수를 구하는 방법을 말해 봐.", "fig": true, "src": "84쪽", "miscon": "x의 계수를 ad+bc가 아니라 계수끼리 더한 값으로 봄", "record": "(ax+b)(cx+d)에서 x의 계수가 ad+bc가 되는 이유를 설명하지 못함", "figScene": {"points": {"A": [100, 60], "B": [350, 60], "C": [350, 270], "D": [100, 270], "T": [280, 60], "U": [280, 270], "L": [100, 210], "R": [350, 210]}, "shapes": [{"points": ["A", "B", "C", "D"], "fill": "#eef3f9", "stroke": "#185FA5"}, {"points": ["T", "U"], "close": false, "stroke": "#185FA5"}, {"points": ["L", "R"], "close": false, "stroke": "#185FA5"}], "labels": [{"text": "ax", "dx": -6, "dy": -10, "at": [190.0, 60]}, {"text": "b", "dx": -6, "dy": -10, "at": [315.0, 60]}, {"text": "cx", "dx": -26, "dy": 5, "at": [100, 135.0]}, {"text": "d", "dx": -26, "dy": 5, "at": [100, 240.0]}], "title": "가로 ax+b, 세로 cx+d인 직사각형"}}, {"kind": "연결", "q": "(x+a)(x+b) 공식은 (ax+b)(cx+d) 공식과 어떤 관계일까?", "ideas": [["x의 계수가 모두 1인 특별한 경우이다", "(ax+b)(cx+d)에서 x의 계수 a, c에 1을 넣으면?"], ["그러면 x의 계수가 두 상수의 합, 상수항이 두 상수의 곱이 되어 같은 식이 된다", "x의 계수가 둘 다 1이면 ad+bc는 무엇이 될까?"]], "teach": "(ax+b)(cx+d)에서 a=c=1이면 x²+(d+b)x+bd, 곧 (x+b)(x+d)의 공식과 같아. 곱셈 공식은 따로 외울 게 아니라 하나에서 나온 거야.", "again": "(x+2)(x+7)을 (ax+b)(cx+d) 공식으로 전개해도 되는 이유를 말해 봐.", "fig": false, "src": "84쪽", "miscon": "곱셈 공식을 따로따로 외워 서로 연결하지 못함", "record": "곱셈 공식들 사이의 관계(특별한 경우)를 설명하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|33. (a-b+2)(a-b+1)은 어떻게 전개할까?": [{"kind": "방법", "q": "(a−b+2)(a−b+1)처럼 항이 3개인 두 식의 곱을 곱셈 공식으로 전개하려면 어떻게 해?", "ideas": [["두 식에 공통으로 있는 a−b를 A처럼 한 문자로 치환한다", "두 괄호에 똑같이 들어 있는 부분은 무엇이지?"], ["(A+2)(A+1)을 곱셈 공식으로 전개한 뒤 A에 a−b를 다시 대입한다", "A로 바꿔 전개했으면 마지막에 무엇을 해야 할까?"]], "teach": "a−b=A로 두면 (A+2)(A+1)=A²+3A+2. 여기에 A=a−b를 다시 넣어 (a−b)²+3(a−b)+2를 전개하면 돼. 공통부분이 보이면 치환해서 공식을 쓸 수 있어.", "again": "(x+y+3)(x+y−5)를 전개하는 방법을 말해 봐.", "fig": false, "src": "85쪽", "miscon": "항이 많으면 곱셈 공식을 쓸 수 없다고 생각하거나 치환 후 대입을 빠뜨림", "record": "공통부분을 치환해 곱셈 공식을 쓰는 방법을 모름"}, {"kind": "전략", "q": "(x−3)(x−1)(x+1)(x+3)을 편하게 전개하려면 네 식을 어떻게 짝지어야 할까?", "ideas": [["합과 차의 곱이 되도록 (x+3)(x−3)과 (x+1)(x−1)로 짝짓는다", "합과 차의 곱 공식을 쓰려면 어떤 두 식을 묶어야 할까?"], ["그러면 (x²−9)(x²−1)이 되어 x²이 공통으로 나와 전개가 쉬워진다", "두 묶음을 각각 전개하면 공통으로 들어 있는 식은 무엇이지?"]], "teach": "앞에서부터 차례로 곱하면 복잡해. (x+3)(x−3)=x²−9, (x+1)(x−1)=x²−1로 짝지으면 (x²−9)(x²−1)=x⁴−10x²+9로 쉽게 전개돼.", "again": "(x+1)(x+2)(x−1)(x−2)를 어떻게 짝지으면 좋은지 말해 봐.", "fig": false, "src": "85쪽", "miscon": "앞에서부터 순서대로만 곱해 계산이 복잡해짐", "record": "곱셈 공식을 쓸 수 있도록 식을 짝짓는 방법을 모름"}], "m3-1|2. 다항식의 곱셈과 인수분해|34. 곱셈 공식으로 복잡한 수의 곱을 계산한다?": [{"kind": "방법", "q": "1003²이나 48×52 같은 수의 계산을 곱셈 공식으로 빠르게 하려면 어떻게 해?", "ideas": [["계산하기 쉬운 수(1000, 50 같은)와의 합이나 차로 바꾼다", "1003을 1000과 어떤 수의 합으로 나타낼 수 있을까?"], ["(a+b)²이나 (a+b)(a−b) 같은 곱셈 공식을 적용한다", "48×52를 (50−2)(50+2)로 보면 어떤 공식을 쓸 수 있지?"]], "teach": "1003²=(1000+3)²=1000²+2×1000×3+3², 48×52=(50−2)(50+2)=50²−2². 수를 딱 떨어지는 수와의 합·차로 바꾸면 공식으로 쉽게 계산돼.", "again": "99²을 곱셈 공식으로 계산하는 방법을 말해 봐.", "fig": false, "src": "86쪽", "miscon": "수를 식처럼 볼 생각을 못함", "record": "수를 합·차로 바꿔 곱셈 공식을 쓰는 방법을 모름"}, {"kind": "적용", "q": "(√5+√2)(√5−√2)처럼 근호가 있는 식에도 곱셈 공식을 쓸 수 있는 이유와 방법을 말해 봐.", "ideas": [["제곱근을 문자처럼 보면 (a+b)(a−b) 꼴이다", "√5를 a, √2를 b라고 보면 어떤 꼴이지?"], ["그래서 (√5)²−(√2)²으로 계산하면 근호가 없어진다", "(√5)²과 (√2)²은 각각 무엇이야?"]], "teach": "√5=a, √2=b로 보면 (a+b)(a−b)=a²−b²이라 (√5)²−(√2)²=5−2=3. 근호가 있어도 식의 모양이 같으면 곱셈 공식을 그대로 쓸 수 있어.", "again": "(√10−4)(√10+2)에 쓸 수 있는 곱셈 공식을 말해 봐.", "fig": false, "src": "86쪽", "miscon": "근호가 있으면 곱셈 공식을 쓸 수 없다고 생각함", "record": "제곱근을 문자로 보고 곱셈 공식을 적용하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|35. (a+b)(a-b)의 전개식을 이용하여 분모를 유리화한다?": [{"kind": "방법", "q": "1/(√3+1)처럼 분모가 √a+b 꼴이면 무엇을 곱해서 유리화하고, 왜 그걸 곱해?", "ideas": [["분모와 가운데 부호가 반대인 √3−1을 분모와 분자에 곱한다", "√3+1과 곱해서 근호가 없어지려면 어떤 식을 곱하면 될까?"], ["(a+b)(a−b)=a²−b²이 되어 분모의 근호가 없어진다", "(√3+1)(√3−1)에는 어떤 곱셈 공식을 쓸 수 있지?"]], "teach": "(√3+1)(√3−1)=(√3)²−1²=2 라서 분모의 근호가 사라져. 그래서 1/(√3+1)=(√3−1)/2. 분모가 √a+√b 면 √a−√b, √a+b 면 √a−b 를 곱해.", "again": "3/(√5+√2)를 유리화할 때 곱할 식과 이유를 말해 봐.", "fig": false, "src": "87쪽", "miscon": "√3만 곱해 분모에 근호가 남음", "record": "분모가 √a+b 꼴일 때 합과 차의 곱으로 유리화하는 방법을 모름"}, {"kind": "함정", "q": "1/(√3+1)을 유리화하면서 분모와 분자에 √3만 곱하면 왜 안 될까?", "ideas": [["√3×(√3+1)=3+√3이 되어 분모에 여전히 근호가 남는다", "√3과 √3+1을 곱하면 근호가 모두 없어질까?"]], "teach": "√3을 곱하면 분모가 3+√3 이라 여전히 무리수야. 분모의 두 항 중 근호가 있는 항만 없애려면 합과 차의 곱이 필요해서 √3−1 을 곱해야 해.", "again": "분모가 √2−1 일 때 무엇을 곱해야 근호가 완전히 없어지는지 말해 봐.", "fig": false, "src": "87쪽", "miscon": "분모의 근호 부분에만 곱하면 된다고 생각함", "record": "분모의 항이 두 개일 때 한쪽만 곱해서는 유리화가 안 되는 이유를 설명하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|36. a+b, ab의 값을 이용하여 a²+b²의 값을 구할 수 있다?": [{"kind": "방법", "q": "a, b의 값을 몰라도 a+b와 ab의 값을 알면 a²+b²을 구할 수 있어. 어떤 식을 이용하고, 그 식은 어디서 나왔어?", "ideas": [["a²+b²=(a+b)²−2ab를 이용한다", "a²+b²을 a+b와 ab로 나타낼 수 있을까?"], ["(a+b)²=a²+2ab+b²에서 2ab를 옮겨 얻은 식이다", "(a+b)²을 전개한 식에서 a²+b²만 남기려면 무엇을 빼야 할까?"]], "teach": "(a+b)²=a²+2ab+b² 이니까 a²+b²=(a+b)²−2ab. a−b 와 ab 를 알면 a²+b²=(a−b)²+2ab. 곱셈 공식을 거꾸로 옮긴 거야.", "again": "a−b와 ab를 알 때 a²+b²을 구하는 식을 말해 봐.", "fig": false, "src": "88쪽", "miscon": "a²+b²=(a+b)²으로 봄", "record": "곱셈 공식을 변형해 a²+b²을 합·곱으로 나타내지 못함"}, {"kind": "연결", "q": "a+1/a의 값을 알면 a를 구하지 않고도 a²+1/a²의 값을 구할 수 있어. 그 이유는 뭘까?", "ideas": [["a×(1/a)=1이라 두 수의 곱을 이미 알고 있다", "a와 1/a를 곱하면 얼마야?"], ["그래서 a²+1/a²=(a+1/a)²−2로 합만 알면 구할 수 있다", "a²+b²=(a+b)²−2ab에서 ab 자리에 1을 넣으면?"]], "teach": "a와 1/a 는 곱이 늘 1이야. 그래서 a²+1/a²=(a+1/a)²−2×1, 또는 (a−1/a)²+2. 합이나 차 하나만 알아도 값을 구할 수 있어.", "again": "a−1/a를 알 때 a²+1/a²을 구하는 방법을 말해 봐.", "fig": false, "src": "88쪽", "miscon": "a의 값을 직접 구해야만 한다고 생각함", "record": "역수 관계에서 곱이 1임을 이용해 식의 값을 구하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|37. x=(무리수)일 때, 식의 값을 어떻게 구할까?": [{"kind": "전략", "q": "x=2+√3, y=2−√3일 때 x²+y²+5xy의 값을 구하려면 x, y를 바로 대입하는 것보다 어떤 방법이 편할까?", "ideas": [["x+y와 xy를 먼저 구하면 근호가 사라진다", "(2+√3)+(2−√3)과 (2+√3)(2−√3)에는 근호가 남을까?"], ["주어진 식을 x+y와 xy로 나타낸 뒤 대입한다", "x²+y²을 x+y와 xy로 나타내면 어떻게 되지?"]], "teach": "x+y=4, xy=1 로 근호가 없어져. x²+y²+5xy=(x+y)²−2xy+5xy=(x+y)²+3xy 로 바꿔 넣으면 계산이 짧아. 두 방법 중 편한 쪽을 고르면 돼.", "again": "x=1/(√2−1), y=1/(√2+1)일 때 x²+y²−xy를 구하는 순서를 말해 봐.", "fig": false, "src": "89쪽", "miscon": "대입 전에 식을 바꿔 볼 생각을 못함", "record": "대입 전에 식을 변형해 계산을 줄이는 방법을 떠올리지 못함"}, {"kind": "방법", "q": "x=1/(√2+1)일 때 x²+2x+5의 값을 조건을 변형해서 구하는 방법을 말해 봐.", "ideas": [["x를 유리화해 √2−1로 만든 뒤 x+1=√2처럼 근호만 한쪽에 남긴다", "x=√2−1에서 근호만 한쪽에 남기려면 어떻게 이항하지?"], ["양변을 제곱해 x²+2x의 값을 얻어 식에 대입한다", "x+1=√2의 양변을 제곱하면 무엇이 나올까?"]], "teach": "x=√2−1 이니까 x+1=√2. 양변을 제곱하면 x²+2x+1=2, 곧 x²+2x=1. 그래서 x²+2x+5=1+5=6. 근호가 있는 수를 그대로 제곱해 넣는 것보다 짧아.", "again": "x=√3+1일 때 x²−2x의 값을 구하려면 조건을 어떻게 바꾸면 되는지 말해 봐.", "fig": false, "src": "89쪽", "miscon": "근호가 남은 채로 제곱해 계산이 복잡해짐", "record": "근호만 남기고 제곱해 식을 간단히 하는 방법을 모름"}], "m3-1|2. 다항식의 곱셈과 인수분해|38. 인수분해란?": [{"kind": "뜻", "q": "인수분해는 무엇이고, 전개와는 어떤 관계야?", "ideas": [["하나의 다항식을 두 개 이상의 다항식의 곱으로 나타내는 것이다", "x²−3x+2를 (x−1)(x−2)로 바꾸는 건 합의 꼴을 무엇의 꼴로 바꾼 걸까?"], ["전개를 거꾸로 하는 과정이다", "(x−1)(x−2)를 전개하면 무엇이 되지? 인수분해는 그 반대 방향일까?"]], "teach": "(x−1)(x−2)를 전개하면 x²−3x+2. 반대로 x²−3x+2 를 (x−1)(x−2) 처럼 곱의 꼴로 나타내는 것이 인수분해야. 합의 꼴 → 곱의 꼴.", "again": "x²−9=(x+3)(x−3)에서 어느 방향이 인수분해인지 말해 봐.", "fig": false, "src": "96쪽", "miscon": "인수분해와 전개를 같은 것으로 봄", "record": "인수분해의 뜻과 전개와의 관계를 설명하지 못함"}, {"kind": "뜻", "q": "x²−3x+2=(x−1)(x−2)에서 인수는 무엇무엇이야? 인수를 찾을 때 빠뜨리기 쉬운 것은?", "ideas": [["곱해진 각각의 식 x−1, x−2가 인수이다", "(x−1)(x−2)에서 곱해져 있는 식은 무엇무엇이지?"], ["1과 자기 자신 x²−3x+2도 인수이다", "6의 약수에 1과 6이 들어가듯, 다항식의 인수에도 빠뜨린 게 없을까?"]], "teach": "인수는 곱을 이루는 각각의 식이야. x²−3x+2 의 인수는 1, x−1, x−2, x²−3x+2. 약수처럼 1과 자기 자신도 인수야.", "again": "x²−x=x(x−1)의 인수를 모두 말해 봐.", "fig": false, "src": "96쪽", "miscon": "1과 자기 자신을 인수에서 빠뜨림", "record": "인수의 뜻과 1·자기 자신도 인수라는 것을 모름"}], "m3-1|2. 다항식의 곱셈과 인수분해|39. 공통인수를 이용하여 어떻게 인수분해할까?": [{"kind": "방법", "q": "ma+mb처럼 모든 항에 공통으로 들어 있는 인수가 있을 때 어떻게 인수분해해?", "ideas": [["모든 항에 공통으로 들어 있는 인수를 찾는다", "ma와 mb에 똑같이 들어 있는 것은 무엇이지?"], ["분배법칙을 거꾸로 써서 공통인수를 괄호 밖으로 묶어 낸다", "m(a+b)를 전개하면 ma+mb가 되지? 그 반대로 하면?"]], "teach": "ma+mb=m(a+b). 각 항에 공통으로 있는 인수를 공통인수라고 하고, 분배법칙을 거꾸로 써서 괄호 밖으로 묶어. 괄호 안에는 각 항에서 남은 것을 써.", "again": "6a²−3ab+3ac를 인수분해하는 방법을 말해 봐.", "fig": true, "src": "97쪽", "miscon": "공통이 아닌 인수까지 묶거나 일부만 묶음", "record": "공통인수를 찾아 분배법칙으로 묶어 내는 방법을 모름", "figScene": {"title": "세로 m, 가로 a와 b인 두 직사각형", "points": {"A": [80, 110], "T": [240, 110], "B": [360, 110], "C": [360, 220], "U": [240, 220], "D": [80, 220]}, "shapes": [{"points": ["A", "B", "C", "D"], "fill": "#eef3f9", "stroke": "#185FA5"}, {"points": ["T", "U"], "close": false, "stroke": "#185FA5"}], "labels": [{"text": "a", "dx": -4, "dy": -10, "at": [160, 110]}, {"text": "b", "dx": -4, "dy": -10, "at": [300, 110]}, {"text": "m", "dx": -22, "dy": 5, "at": [80, 165]}]}}, {"kind": "함정", "q": "2x²+4x를 x(2x+4)로 인수분해하면 왜 덜 된 걸까? 공통인수를 묶을 때 규칙은?", "ideas": [["괄호 안에 공통인수 2가 남아 있어 끝까지 묶지 않았다", "2x+4의 두 항에 공통으로 들어 있는 수가 있을까?"], ["수는 최대공약수로, 문자는 차수가 가장 낮은 것으로 남김없이 묶는다", "2x²과 4x의 수 부분 최대공약수와 공통인 문자는 무엇이지?"]], "teach": "2x²+4x 의 공통인수는 x 가 아니라 2x 야. 2x(x+2) 까지 묶어야 끝. 수는 최대공약수, 문자는 가장 낮은 차수로 묶어. ax+ay−a 처럼 한 항 전체가 묶이면 괄호 안에 1이 남는 것도 조심해.", "again": "ax+ay−a를 인수분해할 때 조심할 점을 말해 봐.", "fig": false, "src": "97쪽", "miscon": "공통인수를 일부만 묶고 끝냄", "record": "공통인수를 남김없이(최대공약수·가장 낮은 차수) 묶어야 한다는 것을 모름"}], "m3-1|2. 다항식의 곱셈과 인수분해|40. 괄호로 묶인 부분이 공통인수일 때는 어떻게 인수분해할까?": [{"kind": "방법", "q": "a(x+y)−b(x+y)처럼 괄호로 묶인 부분이 두 항에 공통으로 있을 때 어떻게 인수분해해?", "ideas": [["괄호로 묶인 x+y 전체를 공통인수로 보고 묶어 낸다", "두 항에 똑같이 들어 있는 것은 x 하나일까, (x+y) 전체일까?"], ["헷갈리면 x+y를 A로 치환해 aA−bA=A(a−b)로 묶는다", "x+y를 한 문자로 바꾸면 어떤 식이 되지?"]], "teach": "공통인수는 수나 문자뿐 아니라 괄호로 묶인 식이어도 돼. a(x+y)−b(x+y)=(x+y)(a−b). 실수가 걱정되면 x+y=A 로 치환해서 묶어.", "again": "a(x+1)−(x+1)을 인수분해할 때 −(x+1)에서 괄호 밖에 남는 것이 무엇인지 말해 봐.", "fig": false, "src": "98쪽", "miscon": "괄호 전체를 하나의 인수로 보지 못함", "record": "괄호로 묶인 식 전체를 공통인수로 보고 묶는 방법을 모름"}, {"kind": "함정", "q": "5x(x+2)−3y(x+2)를 x+2=A로 치환해 인수분해한 뒤 A(5x−3y)로 끝내면 왜 틀릴까?", "ideas": [["치환한 A에 원래 식 x+2를 다시 대입해야 한다", "A는 원래 어떤 식이었지?"], ["답에는 문제에 있던 문자만 들어 있어야 인수분해가 끝난 것이다", "문제에 없던 문자 A가 답에 남아 있어도 될까?"]], "teach": "A 는 계산을 쉽게 하려고 잠깐 바꾼 이름이야. 인수분해한 다음에는 반드시 A=x+2 를 다시 넣어 (x+2)(5x−3y) 로 써야 끝나.", "again": "치환을 이용해 인수분해할 때 마지막에 꼭 해야 하는 일을 말해 봐.", "fig": false, "src": "98쪽 참고", "miscon": "치환한 문자를 답에 그대로 남김", "record": "치환 후 원래 식을 대입해 마무리하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|41. ax+a+bx+b는 어떻게 인수분해할까?": [{"kind": "방법", "q": "ax+a+bx+b처럼 네 항 전체에 공통인수가 보이지 않을 때 어떻게 인수분해해?", "ideas": [["두 항씩 묶어 각각 공통인수로 묶는다", "ax+a와 bx+b를 각각 인수분해하면 어떻게 되지?"], ["그러면 생긴 공통인수 x+1로 한 번 더 묶는다", "a(x+1)+b(x+1)에 공통으로 있는 것은?"]], "teach": "ax+a=a(x+1), bx+b=b(x+1) 이라 전체는 a(x+1)+b(x+1)=(x+1)(a+b). 전체 공통인수가 없어도 두 항씩 묶으면 공통인수가 생길 수 있어.", "again": "xy−x+y−1을 인수분해하는 방법을 말해 봐.", "fig": false, "src": "98쪽", "miscon": "전체 공통인수가 없으면 인수분해할 수 없다고 판단함", "record": "두 항씩 묶어 공통인수를 만드는 방법을 모름"}, {"kind": "함정", "q": "ax+a+bx+b를 (ax+bx)+(a+b)로 묶어도 될까? 두 항씩 묶을 때 짝은 어떻게 정해?", "ideas": [["묶은 뒤 괄호 안이 같은 식이 되도록 짝을 정한다", "a(x+1)과 b(x+1)처럼 괄호 안이 같아야 다음에 무엇을 할 수 있지?"], ["(ax+bx)+(a+b)=x(a+b)+(a+b)도 괄호 안이 같아 (a+b)(x+1)이 되므로 이렇게 묶어도 된다", "x(a+b)+(a+b)에서 공통인수는 무엇이지?"]], "teach": "짝을 어떻게 짓든 묶은 뒤 괄호 안이 같아지면 돼. x(a+b)+(a+b)=(a+b)(x+1) 로 같은 답이 나와. 괄호 안이 달라지는 짝은 다시 골라.", "again": "두 항씩 묶었는데 괄호 안이 서로 달라졌다면 어떻게 해야 하는지 말해 봐.", "fig": false, "src": "98쪽", "miscon": "묶는 짝이 하나로 정해져 있다고 생각함", "record": "공통인수가 생기도록 짝을 정하는 기준을 설명하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|42. a²+2ab+b², a²-2ab+b²은 어떻게 인수분해할까?": [{"kind": "방법", "q": "x²+10x+25가 (x+5)²으로 인수분해된다는 걸 어떻게 알아봐?", "ideas": [["처음과 끝 항이 각각 x²과 5²처럼 어떤 식의 제곱인지 본다", "x²과 25는 각각 무엇의 제곱이지?"], ["가운데 항이 2×x×5와 같은지 확인한다", "x와 5를 곱해서 2배 하면 가운데 항과 같을까?"]], "teach": "a²+2ab+b²=(a+b)² 은 곱셈 공식을 거꾸로 쓴 거야. x²+10x+25 는 양 끝이 x², 5² 이고 가운데가 2×x×5 라서 (x+5)². 가운데가 − 이면 (a−b)².", "again": "4x²−4x+1이 완전제곱식으로 인수분해되는지 확인하는 방법을 말해 봐.", "fig": false, "src": "100쪽", "miscon": "가운데 항의 계수를 그대로 괄호 안에 씀", "record": "a²±2ab+b² 꼴인지(양 끝이 제곱·가운데가 2ab) 확인하는 방법을 모름"}, {"kind": "함정", "q": "3x²−18x+27을 완전제곱식으로 인수분해할 때 먼저 할 일은 뭐고, 괄호 안의 부호는 어떻게 정해?", "ideas": [["공통인수 3을 먼저 묶어 3(x²−6x+9)로 만든다", "세 항에 공통으로 들어 있는 수가 있을까?"], ["가운데 항이 −이면 (x−3)²처럼 괄호 안도 −이다", "가운데 항 −6x의 부호는 괄호 안의 어느 부호와 같을까?"]], "teach": "3 을 먼저 묶으면 3(x²−6x+9)=3(x²−2×x×3+3²)=3(x−3)². 공통인수를 안 묶으면 27 이 제곱수가 아니라 완전제곱식이 안 보여.", "again": "2x²+8x+8을 인수분해하는 순서를 말해 봐.", "fig": false, "src": "100쪽 예제 15", "miscon": "공통인수를 묶지 않아 완전제곱식을 알아보지 못함", "record": "공통인수를 먼저 묶고 부호를 맞춰 완전제곱식으로 인수분해하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|43. 완전제곱식으로 인수분해할 식인지 어떻게 확인할 수 있을까?": [{"kind": "성질", "q": "x²+ax+b가 완전제곱식이 될 조건은 뭐고, 왜 그런지 (x+a/2)²을 전개해서 설명해 봐.", "ideas": [["x의 계수의 절반의 제곱이 상수항과 같아야 한다", "x²+2x+1에서 x의 계수 2의 절반을 제곱하면 얼마야?"], ["(x+a/2)²=x²+ax+(a/2)²이기 때문이다", "(x+a/2)²을 전개하면 상수항은 무엇이 되지?"]], "teach": "(x+a/2)² 을 전개하면 x²+ax+(a/2)². 그래서 x²+ax+b 가 완전제곱식이 되려면 b=(a/2)², 곧 \"x 의 계수 절반의 제곱 = 상수항\" 이어야 해. x²−6x+9 는 (−6/2)²=9 라서 (x−3)².", "again": "x²−6x+9가 완전제곱식인 이유를 조건을 써서 말해 봐.", "fig": false, "src": "101쪽", "miscon": "상수항이 제곱수이기만 하면 완전제곱식이라고 생각함", "record": "완전제곱식이 될 조건(계수 절반의 제곱=상수항)을 설명하지 못함"}, {"kind": "성질", "q": "9x²+24x+16처럼 x²의 계수가 1이 아닐 때는 완전제곱식인지 어떻게 확인해?", "ideas": [["x의 계수의 절반의 제곱이 x²의 계수와 상수항의 곱과 같은지 본다", "24의 절반을 제곱한 값과 9×16을 비교해 볼래?"], ["(ax+c)²을 전개하면 x²의 계수 a², 상수항 c², x의 계수 2ac라서 절반의 제곱이 두 수의 곱과 같기 때문이다", "(3x+4)²을 전개해서 x²의 계수와 상수항을 곱해 볼래?"]], "teach": "(ax+c)²=a²x²+2acx+c². x 의 계수 절반 ac 를 제곱하면 a²c², 곧 (x²의 계수)×(상수항). 9x²+24x+16 은 12²=144=9×16 이라 (3x+4)².", "again": "4x²−12xy+9y²이 완전제곱식인지 확인하는 방법을 말해 봐.", "fig": false, "src": "101쪽", "miscon": "x²의 계수가 1일 때만 완전제곱식이 된다고 생각함", "record": "x²의 계수가 1이 아닌 경우의 완전제곱식 조건을 모름"}], "m3-1|2. 다항식의 곱셈과 인수분해|44. x²+□x+25가 완전제곱식이 되도록 하는 □의 값은?": [{"kind": "함정", "q": "x²+□x+25가 완전제곱식이 되도록 □에 알맞은 수를 구할 때, 10 하나만 답하면 왜 부족할까?", "ideas": [["(x+5)²과 (x−5)² 둘 다 상수항이 25이다", "(x−5)²을 전개해도 상수항이 25일까?"], ["가운데 항은 +, − 부호를 모두 가질 수 있어서 □는 두 값이다", "(x−5)²을 전개하면 가운데 항의 부호는?"]], "teach": "(x+5)²=x²+10x+25, (x−5)²=x²−10x+25. 둘 다 상수항이 25 라서 □ 는 10 과 −10 두 가지야. \"양수\" 같은 조건이 없으면 둘 다 써야 해.", "again": "x²+□x+36이 완전제곱식이 되도록 □를 구할 때 조심할 점을 말해 봐.", "fig": false, "src": "101쪽", "miscon": "양수만 생각해 음수 값을 빠뜨림", "record": "완전제곱식의 가운데 항이 두 부호를 가질 수 있다는 것을 모름"}, {"kind": "함정", "q": "x²+□x+25y²이 완전제곱식이 되려면 □에 무엇이 들어가야 할까? 수만 넣으면 왜 틀릴까?", "ideas": [["상수 부분 25y²이 (5y)²이라 (x±5y)² 꼴이 되어야 한다", "25y²은 무엇의 제곱이지?"], ["가운데 항이 2×x×5y이므로 □에는 문자 y까지 붙어야 한다", "가운데 항에 y가 없으면 (x+5y)²을 전개한 식과 같아질까?"]], "teach": "25y²=(5y)² 이니까 (x±5y)² 이 되어야 해. 가운데 항은 2×x×(±5y)=±10xy 라서 □ 에는 ±10y 가 들어가. 문자를 빠뜨리지 마.", "again": "□x²+12xy+4y²이 완전제곱식이 되는 □를 구할 때 확인할 것을 말해 봐.", "fig": false, "src": "101쪽", "miscon": "문자를 빠뜨리고 수만 씀", "record": "완전제곱식에서 문자까지 포함해 가운데 항을 정하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|45. a²-b²은 어떻게 인수분해할까?": [{"kind": "방법", "q": "a²−b²은 어떻게 인수분해하고, 이 공식을 쓸 수 있는 식인지는 어떻게 알아봐?", "ideas": [["a²−b²=(a+b)(a−b)로 합과 차의 곱으로 인수분해한다", "합과 차의 곱 (a+b)(a−b)를 전개하면 무엇이었지?"], ["항이 2개이고 둘 다 제곱 꼴이며 빼기로 연결되어 있는지 본다", "36x²−25y²의 두 항은 각각 무엇의 제곱이고 어떻게 연결돼 있지?"]], "teach": "(a+b)(a−b)=a²−b² 을 거꾸로 쓰면 a²−b²=(a+b)(a−b). \"제곱 − 제곱\" 꼴인지만 보면 돼: 36x²−25y²=(6x)²−(5y)²=(6x+5y)(6x−5y).", "again": "x²−16을 인수분해할 수 있는 이유를 말해 봐.", "fig": true, "src": "102쪽", "miscon": "(a−b)²과 혼동함", "record": "제곱의 차를 합과 차의 곱으로 인수분해하지 못함", "figScene": {"title": "한 변이 a인 정사각형에서 한 변이 b인 정사각형을 떼어 냄", "points": {"A": [100, 60], "B": [320, 60], "C": [320, 280], "D": [100, 280], "E": [240, 200], "F": [320, 200], "G": [240, 280]}, "shapes": [{"points": ["A", "B", "C", "D"], "fill": "#eef3f9", "stroke": "#185FA5"}, {"points": ["E", "F", "C", "G"], "fill": "#ffffff", "stroke": "#D85A30", "style": "dashed"}], "labels": [{"text": "a", "dx": -4, "dy": -10, "at": [210, 60]}, {"text": "a", "dx": -20, "dy": 5, "at": [100, 170]}, {"text": "b", "dx": -4, "dy": 20, "at": [280, 280]}, {"text": "b", "dx": 8, "dy": 5, "at": [320, 240]}]}}, {"kind": "함정", "q": "a²−1이나 −4x²+25는 제곱의 차 공식을 쓰려면 어떻게 바꿔서 봐야 할까?", "ideas": [["1을 1²으로 본다", "1은 무엇의 제곱일까?"], ["−4x²+25는 순서를 바꿔 5²−(2x)²으로 본다", "−4x²+25의 두 항 순서를 바꾸면 어떤 꼴이 될까?"]], "teach": "a²−1=a²−1²=(a+1)(a−1). −4x²+25=25−4x²=5²−(2x)²=(5+2x)(5−2x). 제곱의 차가 보이게 식을 살짝 바꿔 보는 눈이 필요해.", "again": "−a²+b²을 인수분해하는 방법을 말해 봐.", "fig": false, "src": "102쪽", "miscon": "1이나 순서가 바뀐 식을 제곱의 차로 알아보지 못함", "record": "식을 a²−b² 꼴로 바꿔 보는 변형을 하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|46. x²+(a+b)x+ab는 어떻게 인수분해할까?": [{"kind": "방법", "q": "x²+5x+6을 (x+a)(x+b) 꼴로 인수분해하려면 어떤 두 수를 어떻게 찾아?", "ideas": [["곱이 상수항 6이고 합이 x의 계수 5인 두 수를 찾는다", "(x+a)(x+b)를 전개하면 상수항과 x의 계수에 각각 무엇이 오지?"], ["곱이 6인 두 정수를 먼저 나열한 뒤 그중 합이 5인 것을 고른다", "곱과 합 중 어느 쪽부터 찾으면 경우가 적을까?"]], "teach": "x²+(a+b)x+ab=(x+a)(x+b). 곱이 6 인 두 정수는 (1,6), (2,3), (−1,−6), (−2,−3) 뿐이라 곱부터 찾고, 그중 합이 5 인 (2,3) 을 골라 (x+2)(x+3).", "again": "x²+3x+2를 인수분해할 두 수를 찾는 방법을 말해 봐.", "fig": true, "src": "103쪽", "miscon": "합과 곱의 자리를 바꿔 찾음", "record": "곱이 상수항, 합이 x의 계수인 두 수를 찾는 방법을 모름", "figScene": {"points": {"A": [100, 60], "B": [330, 60], "C": [330, 320], "D": [100, 320], "T": [270, 60], "U": [270, 320], "L": [100, 230], "R": [330, 230]}, "shapes": [{"points": ["A", "B", "C", "D"], "fill": "#eef3f9", "stroke": "#185FA5"}, {"points": ["T", "U"], "close": false, "stroke": "#185FA5"}, {"points": ["L", "R"], "close": false, "stroke": "#185FA5"}], "labels": [{"text": "x", "dx": -6, "dy": -10, "at": [185.0, 60]}, {"text": "2", "dx": -6, "dy": -10, "at": [300.0, 60]}, {"text": "x", "dx": -26, "dy": 5, "at": [100, 145.0]}, {"text": "3", "dx": -26, "dy": 5, "at": [100, 275.0]}], "title": "가로 x+2, 세로 x+3인 직사각형"}}, {"kind": "함정", "q": "x²−2x−8처럼 부호가 섞여 있을 때 두 수를 찾으면서 조심할 점은?", "ideas": [["상수항이 음수이면 두 수의 부호가 서로 다르다", "곱이 −8이 되려면 두 수의 부호는 어때야 할까?"], ["합이 음수이면 절댓값이 큰 쪽이 음수이다", "합이 −2가 되려면 2와 4 중 어느 쪽에 −를 붙여야 할까?"]], "teach": "곱 −8 → 두 수의 부호가 달라. 합 −2 → 절댓값이 큰 쪽이 음수. 그래서 2 와 −4, (x+2)(x−4). 절댓값만 보고 (x+2)(x+4) 로 쓰면 틀려.", "again": "x²+2x−15를 인수분해할 때 두 수의 부호를 정하는 방법을 말해 봐.", "fig": false, "src": "103쪽 예제 18", "miscon": "부호를 무시하고 절댓값만으로 두 수를 고름", "record": "상수항과 x의 계수의 부호로 두 수의 부호를 정하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|47. acx²+(ad+bc)x+bd는 어떻게 인수분해할까?": [{"kind": "방법", "q": "2x²+7x+3처럼 x²의 계수가 1이 아닌 이차식은 어떻게 인수분해해?", "ideas": [["x²의 계수와 상수항을 각각 두 수의 곱으로 나눠 세로로 놓는다", "2와 3을 각각 어떤 두 수의 곱으로 나눌 수 있지?"], ["대각선 방향으로 곱한 두 값의 합이 x의 계수가 되는 배치를 찾는다", "대각선으로 곱한 두 수를 더하면 7이 되는지 확인해 볼래?"]], "teach": "2=2×1, 3=1×3 으로 놓으면 대각선 곱 2×3=6, 1×1=1 의 합이 7 이라 성공. 같은 가로 줄끼리 묶어 (2x+1)(x+3).", "again": "2x²+x−15를 인수분해하는 방법을 말해 봐.", "fig": false, "src": "104쪽", "miscon": "x²의 계수를 무시하고 (x+a)(x+b) 방법을 그대로 씀", "record": "x²의 계수까지 나눠 대각선 곱의 합을 맞추는 방법을 모름"}, {"kind": "함정", "q": "3x²−x−4를 인수분해할 때 수의 위치와 부호를 바꾸면 대각선 곱의 합이 여러 가지로 나와. 맞는 배치를 찾은 뒤 식으로 쓸 때 틀리기 쉬운 점은?", "ideas": [["합이 x의 계수와 같아질 때까지 수의 위치와 부호를 바꿔 본다", "−1과 4, 1과 −4 중 어떤 배치가 합 −1을 만들까?"], ["식을 쓸 때는 대각선이 아니라 같은 가로 줄의 수끼리 묶는다", "3과 같은 가로 줄에 있는 수는 무엇이고, 그 둘로 어떤 일차식을 만들지?"]], "teach": "1, 1 / 3, −4 로 놓으면 대각선 곱 1×(−4)=−4 와 3×1=3 의 합이 −1. 식은 가로 줄끼리 (x+1)(3x−4). 대각선끼리 묶어 쓰면 틀려.", "again": "대각선 곱의 합을 확인한 뒤 일차식을 만들 때 어느 방향으로 묶는지 이유와 함께 말해 봐.", "fig": false, "src": "104쪽", "miscon": "식을 쓸 때 대각선 방향으로 묶음", "record": "배치를 바꿔 합을 맞추고 가로 줄로 묶어 쓰는 과정을 정확히 하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|48. 2x²+Ax-6이 x-2로 나누어 떨어질 때, A의 값은?": [{"kind": "방법", "q": "2x²+Ax−6이 x−2로 나누어떨어질 때 A를 구하려면 식을 어떻게 놓고 생각해?", "ideas": [["2x²+Ax−6=(x−2)(□)처럼 x−2를 인수로 놓는다", "x가 2로 나누어떨어지면 x=2×□라고 놓았지?"], ["x²의 계수와 상수항에 맞게 □를 정한 뒤 x의 계수를 비교해 A를 구한다", "x×□가 2x²이 되고 (−2)×(□의 상수)가 −6이 되려면 □는?"]], "teach": "나누어떨어진다 = x−2 가 인수. 2x²+Ax−6=(x−2)(2x+3) 이어야 x² 의 계수 2, 상수항 −6 이 맞아. 이제 x 의 계수 3−4=−1 이 A.", "again": "3x²+Ax−5가 x−1을 인수로 가질 때 A를 구하는 방법을 말해 봐.", "fig": false, "src": "105쪽", "miscon": "나누어떨어진다는 뜻을 인수와 연결하지 못함", "record": "나누어떨어짐을 인수분해(인수)로 바꿔 생각하지 못함"}, {"kind": "연결", "q": "같은 문제를 x=2를 대입해서 풀 수도 있어. x−2로 나누어떨어지면 왜 x=2를 넣은 값이 0이 될까?", "ideas": [["x−2가 인수이면 x=2일 때 그 인수가 0이 된다", "x=2를 넣으면 x−2는 얼마가 되지?"], ["인수 하나가 0이면 곱 전체가 0이라서 2×2²+2A−6=0으로 A를 구할 수 있다", "0에 어떤 수를 곱하면 얼마야?"]], "teach": "2x²+Ax−6=(x−2)×(□) 에 x=2 를 넣으면 오른쪽은 0×(□)=0. 그래서 왼쪽도 0 이 되어 8+2A−6=0. 인수와 방정식의 해가 연결돼.", "again": "다항식이 x+1로 나누어떨어질 때 어떤 값을 대입하면 0이 되는지와 이유를 말해 봐.", "fig": false, "src": "105쪽", "miscon": "대입한 값이 0이 되는 이유를 모르고 임의로 대입함", "record": "인수와 방정식의 해(대입하면 0)를 연결하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|49. 치환을 이용하여 어떻게 인수분해할까?": [{"kind": "방법", "q": "(x+y)²+10(x+y)+24는 어떻게 인수분해해?", "ideas": [["반복해서 나오는 x+y를 A로 치환한다", "식에서 두 번 반복해서 나오는 부분은 무엇이지?"], ["A²+10A+24를 인수분해한 뒤 A에 x+y를 다시 대입한다", "A로 인수분해를 끝냈으면 마지막에 무엇을 해야 할까?"]], "teach": "x+y=A 로 두면 A²+10A+24=(A+4)(A+6). 여기에 A=x+y 를 다시 넣어 (x+y+4)(x+y+6). (A+4)(A+6) 에서 멈추면 틀려.", "again": "(x−y+1)(x−y−6)+10을 인수분해하는 방법을 말해 봐.", "fig": false, "src": "107쪽", "miscon": "공통부분을 보지 못하고 전개부터 함", "record": "공통부분을 치환해 인수분해 공식을 쓰는 방법을 모름"}, {"kind": "함정", "q": "(2x+3)²−(x+4)²을 인수분해할 때 어떤 공식을 쓰고, 마지막에 무엇을 조심해야 해?", "ideas": [["2x+3=A, x+4=B로 치환하면 A²−B²이라 (A+B)(A−B)로 인수분해한다", "A²−B²은 어떤 공식으로 인수분해하지?"], ["원래 식을 대입해 괄호를 풀 때 빼는 식의 부호를 모두 바꾼다", "(2x+3)−(x+4)에서 괄호를 풀면 4의 부호는?"]], "teach": "(A+B)(A−B)={(2x+3)+(x+4)}{(2x+3)−(x+4)}=(3x+7)(x−1). 빼는 괄호를 풀 때 x+4 의 두 항 부호를 모두 바꿔야 해.", "again": "(a+1)²−(a−2)²을 인수분해할 때 부호를 조심해야 하는 곳을 말해 봐.", "fig": false, "src": "108쪽 예제 21", "miscon": "제곱의 차를 차의 제곱으로 봄", "record": "치환 후 제곱의 차 공식을 적용하고 부호를 정리하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|50. ( )( )( )( )+k 꼴은 어떻게 인수분해할까?": [{"kind": "방법", "q": "(x−1)(x−3)(x+2)(x+4)+24는 어떻게 인수분해를 시작해?", "ideas": [["전개했을 때 공통부분이 생기도록 두 개씩 짝지어 전개한다", "(x−1)(x+2)와 (x−3)(x+4)를 전개하면 x의 계수가 같아질까?"], ["공통부분 x²+x를 A로 치환해 인수분해한다", "두 전개식에 똑같이 들어 있는 부분은 무엇이지?"]], "teach": "상수의 합이 같도록 짝지으면 (x−1)(x+2)=x²+x−2, (x−3)(x+4)=x²+x−12 로 x²+x 가 공통. A=x²+x 로 두면 (A−2)(A−12)+24=A²−14A+48=(A−6)(A−8).", "again": "(x+1)(x+2)(x−3)(x−4)+4를 짝짓는 방법을 말해 봐.", "fig": false, "src": "108쪽", "miscon": "+k가 있어도 인수분해가 끝났다고 봄", "record": "짝지어 전개해 공통부분을 만드는 방법을 모름"}, {"kind": "함정", "q": "(x−1)(x−3)(x+2)(x+4)+24가 이미 곱의 꼴로 보이는데 인수분해가 끝난 게 아닌 이유는? A로 인수분해한 뒤에는 무엇을 더 확인해야 해?", "ideas": [["마지막에 +24가 더해져 있어서 식 전체는 곱이 아니라 합의 꼴이다", "식 전체가 곱으로 끝나는지, 더하기로 끝나는지 봐 볼래?"], ["A에 원래 식을 대입한 뒤 더 인수분해할 수 있는지 끝까지 확인한다", "x²+x−6은 더 인수분해할 수 있을까?"]], "teach": "+24 때문에 전체는 합이야. A 로 인수분해해 (x²+x−6)(x²+x−8) 을 얻은 뒤에도 x²+x−6=(x−2)(x+3) 으로 더 분해돼. 더 이상 안 될 때까지 확인해.", "again": "인수분해가 끝났는지 판단하는 기준 두 가지를 말해 봐.", "fig": false, "src": "108쪽", "miscon": "겉모양만 보고 인수분해가 끝났다고 봄", "record": "인수분해가 끝났는지(곱의 꼴인지·더 분해되는지) 판단하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|51. 항이 4개인 식은 어떻게 인수분해할까?": [{"kind": "방법", "q": "항이 4개이고 공통인수가 없는 식은 어떤 두 가지 방법으로 묶어 볼 수 있어?", "ideas": [["(항 2개)+(항 2개)로 묶어 공통인수를 만든다", "4xy−2x−2y+1을 두 항씩 묶으면 공통인수가 생길까?"], ["(항 3개)+(항 1개)로 묶어 ( )²−( )² 꼴로 만든다", "a²+2ab+b²−16에서 앞의 세 항은 어떤 식이지?"]], "teach": "두 항씩 묶어 공통인수가 생기면 (2+2), 세 항이 완전제곱식이 되고 나머지 한 항이 제곱이면 (3+1) 로 묶어 제곱의 차를 써: a²+2ab+b²−16=(a+b)²−4²=(a+b+4)(a+b−4).", "again": "x²y−x²−y+1을 어떻게 묶을지 말해 봐.", "fig": false, "src": "109~110쪽", "miscon": "전체 공통인수가 없으면 인수분해할 수 없다고 판단함", "record": "항이 4개인 식을 (2+2) 또는 (3+1)로 묶는 방법을 모름"}, {"kind": "전략", "q": "x²−y²+2x+1은 (2+2)와 (3+1) 중 어떤 방법으로 묶는 게 좋을까? 어떻게 알아봐?", "ideas": [["x², 2x, 1이 완전제곱식을 이루므로 (3+1)로 묶는다", "x², 2x, 1 세 항을 모으면 어떤 식이 되지?"], ["(x+1)²−y²이 되어 제곱의 차로 인수분해한다", "(x+1)²−y²에는 어떤 공식을 쓸 수 있지?"]], "teach": "−y² 를 따로 두고 x²+2x+1=(x+1)² 을 찾으면 (x+1)²−y²=(x+1+y)(x+1−y). 두 항씩 묶으면 공통인수가 생기지 않아.", "again": "a²−b²+2b−1은 어떤 세 항을 묶어야 할지 말해 봐.", "fig": false, "src": "110쪽 예제 23", "miscon": "공통인수가 생기지 않는 짝으로 묶음", "record": "완전제곱식이 되는 세 항을 찾아 묶는 판단을 하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|52. 항이 5개 이상인 식은 어떻게 인수분해할까?": [{"kind": "방법", "q": "x²−2xy+y²−7x+7y+12처럼 항이 5개 이상인 식은 어떻게 인수분해해?", "ideas": [["완전제곱식이나 공통인수가 생기도록 적당한 항끼리 묶는다", "x²−2xy+y²과 −7x+7y는 각각 어떻게 정리되지?"], ["생긴 공통부분 x−y를 치환해 인수분해한 뒤 다시 대입한다", "(x−y)²−7(x−y)+12에서 반복되는 부분은 무엇이지?"]], "teach": "x²−2xy+y²=(x−y)², −7x+7y=−7(x−y) 로 묶으면 (x−y)²−7(x−y)+12. x−y=A 로 두면 (A−3)(A−4)=(x−y−3)(x−y−4).", "again": "x²+2xy−x+y²−y−2를 어떻게 묶을지 말해 봐.", "fig": false, "src": "110쪽", "miscon": "묶는 기준 없이 전개하거나 포기함", "record": "공통부분이 생기도록 묶고 치환하는 방법을 모름"}, {"kind": "방법", "q": "문자가 여러 개인 복잡한 식은 한 문자에 대해 내림차순으로 정리해서 인수분해하기도 해. 어떤 문자에 대해 정리하면 편하고, 왜 그래?", "ideas": [["차수가 가장 낮은 문자에 대해 내림차순으로 정리한다", "x는 2차, y는 1차로만 들어 있다면 어느 문자로 정리할까?"], ["그러면 식이 간단한 꼴이 되어 공통인수나 인수분해 공식을 찾기 쉽다", "낮은 차수의 문자로 정리하면 식의 모양이 어떻게 보이지?"]], "teach": "내림차순은 한 문자에 대해 차수가 높은 항부터 쓰는 거야. 차수가 낮은 문자로 정리하면 일차식이나 간단한 이차식이 되어 공통인수·인수분해 공식이 잘 보여.", "again": "x와 y가 섞인 식을 내림차순으로 정리할 때 문자를 고르는 기준을 말해 봐.", "fig": false, "src": "111쪽 THINK Math", "miscon": "정리할 문자를 고르는 기준이 없음", "record": "내림차순 정리로 인수분해의 실마리를 찾는 방법을 모름"}], "m3-1|2. 다항식의 곱셈과 인수분해|53. 인수분해를 이용하여 수의 계산을 빠르게 할 수 있다?": [{"kind": "방법", "q": "65²−35²이나 18×101+18×99 같은 수의 계산을 인수분해 공식으로 빠르게 하려면 어떻게 해?", "ideas": [["공통인수로 묶거나 제곱의 차·완전제곱식 같은 공식 모양을 찾는다", "18×101과 18×99에 공통으로 있는 수는?"], ["묶거나 공식을 쓰면 200, 100 같은 계산하기 쉬운 수가 나온다", "65²−35²을 (65+35)(65−35)로 바꾸면 어떤 수가 나올까?"]], "teach": "18×101+18×99=18×(101+99)=18×200, 65²−35²=(65+35)(65−35)=100×30, 45²+2×45×35+35²=(45+35)². 공식 모양을 찾으면 딱 떨어지는 수가 나와.", "again": "103²−6×103+9를 빠르게 계산하는 방법을 말해 봐.", "fig": false, "src": "111~112쪽", "miscon": "수 계산에서 공식 모양을 볼 생각을 못함", "record": "수 계산에서 인수분해 공식의 모양을 찾지 못함"}, {"kind": "연결", "q": "곱셈 공식을 이용한 수의 계산(예: 1003²)과 인수분해 공식을 이용한 수의 계산(예: 65²−35²)은 방법이 어떻게 달라?", "ideas": [["곱셈 공식은 수 하나를 쉬운 수의 합이나 차로 쪼개 전개한다", "1003²은 1003을 어떻게 바꿔서 계산했지?"], ["인수분해 공식은 더하기·빼기로 된 계산을 곱의 꼴로 묶는다", "65²−35²은 빼기로 된 식을 무엇의 꼴로 바꿨지?"]], "teach": "곱셈 공식: 곱을 전개 (1003²=(1000+3)²). 인수분해 공식: 합·차를 곱으로 묶기 (65²−35²=100×30). 둘 다 계산을 쉽게 하지만 방향이 반대야.", "again": "48×52와 52²−48²을 계산할 때 각각 어떤 공식을 쓰는지 말해 봐.", "fig": false, "src": "86·111쪽", "miscon": "전개와 인수분해의 방향을 구분하지 못함", "record": "곱셈 공식과 인수분해 공식을 계산 목적에 맞게 구분하지 못함"}], "m3-1|2. 다항식의 곱셈과 인수분해|54. 인수분해하면 식의 값을 편리하게 구할 수 있다?": [{"kind": "전략", "q": "x=99일 때 x²+2x+1의 값을 구하려면 바로 대입하는 것보다 어떤 방법이 편하고, 왜 그래?", "ideas": [["먼저 (x+1)²으로 인수분해한다", "x²+2x+1은 어떤 식으로 인수분해되지?"], ["x+1이 100처럼 계산하기 쉬운 수가 되어 암산할 수 있다", "x=99일 때 x+1은 얼마야?"]], "teach": "바로 넣으면 99²+2×99+1 을 계산해야 해. (x+1)² 으로 바꾸면 (99+1)²=100² 이라 암산으로 끝나. 대입하기 전에 인수분해로 식을 간단히 해 봐.", "again": "x=51일 때 x²−2x+1의 값을 편하게 구하는 방법을 말해 봐.", "fig": false, "src": "112쪽", "miscon": "항상 바로 대입만 함", "record": "대입 전에 인수분해로 식을 간단히 하는 방법을 떠올리지 못함"}, {"kind": "적용", "q": "x=3−√3, y=3+√3일 때 x²−y²의 값을 구하는 편리한 방법을 말해 봐.", "ideas": [["x²−y²=(x+y)(x−y)로 인수분해한다", "x²−y²은 어떤 공식으로 인수분해하지?"], ["x+y와 x−y를 따로 구해 곱한다", "x+y를 구하면 근호가 남을까?"]], "teach": "x²−y²=(x+y)(x−y) 로 바꾸면 x+y=6, x−y=−2√3 을 곱하기만 하면 돼. 근호가 있는 수를 각각 제곱해서 빼는 것보다 훨씬 짧아.", "again": "x=√2+1, y=√2−1일 때 x²+2xy+y²을 구하는 방법을 말해 봐.", "fig": false, "src": "112쪽 예제 26", "miscon": "대입 전에 인수분해를 떠올리지 못함", "record": "제곱의 차로 인수분해한 뒤 합과 차를 대입하는 방법을 모름"}], "m3-1|3. 이차방정식|55. 이차방정식이란?": [{"kind": "뜻", "q": "x에 대한 이차방정식은 어떤 방정식이고, 일반적으로 어떤 꼴로 나타내?", "ideas": [["모든 항을 좌변으로 이항해 정리했을 때 (x에 대한 이차식)=0 꼴이 되는 방정식이다", "일차방정식은 정리하면 (일차식)=0 꼴이었지? 이차방정식은 어떤 꼴일까?"], ["ax²+bx+c=0 (a≠0) 꼴로 나타낸다", "이차방정식을 문자 a, b, c로 나타내면 어떻게 쓰고, a에는 어떤 조건이 붙지?"]], "teach": "등식의 모든 항을 좌변으로 옮겨 정리했을 때 좌변이 x에 대한 이차식이면 이차방정식이야. 일반형은 ax²+bx+c=0이고, x² 항이 있어야 하니까 a≠0이야.", "again": "−x²+12x−35=0이 이차방정식인 이유를 말해 봐.", "fig": false, "src": "136~137쪽", "miscon": "x²이 보이기만 하면 이차방정식이라고 생각함", "record": "이차방정식의 뜻(정리했을 때 이차식=0)을 설명하지 못함"}, {"kind": "연결", "q": "둘레가 24 m이고 넓이가 35 m²인 직사각형 화단의 세로를 x m라고 하면 왜 이차방정식이 만들어질까?", "ideas": [["가로는 둘레의 절반에서 세로를 뺀 12−x로 나타난다", "가로와 세로의 합은 둘레의 얼마일까?"], ["넓이는 가로×세로라서 x(12−x)=35가 되고, 정리하면 x²이 들어간 식이 된다", "x와 12−x를 곱하면 x의 몇 차식이 될까?"]], "teach": "가로+세로=12라서 가로는 12−x. 넓이는 x(12−x)=35이고, 정리하면 x²−12x+35=0이야. 넓이처럼 미지수끼리 곱해지는 상황에서 이차방정식이 생겨.", "again": "넓이 문제에서 이차방정식이 자주 나오는 이유를 말해 봐.", "fig": false, "src": "136쪽", "miscon": "둘레와 가로·세로의 관계를 잘못 세움", "record": "실생활 상황을 이차방정식으로 세우는 과정을 설명하지 못함"}], "m3-1|3. 이차방정식|56. 이차방정식이 되기 위한 조건은?": [{"kind": "함정", "q": "x²−4x=(x−1)²처럼 양변에 x²이 있는 등식은 이차방정식일까? 어떻게 판단해?", "ideas": [["모든 항을 좌변으로 이항해 정리한 뒤에 판단한다", "x² 항이 보인다고 바로 판단해도 될까, 먼저 무엇을 해야 할까?"], ["정리하면 x²이 없어져 −2x−1=0이 되므로 이차방정식이 아니다", "(x−1)²을 전개해서 좌변으로 옮기면 x² 항은 어떻게 돼?"]], "teach": "x²−4x−(x²−2x+1)=0으로 정리하면 x²끼리 지워져 −2x−1=0, 일차방정식이야. 겉으로 x²이 보여도 정리한 뒤 x² 항이 남아야 이차방정식이야.", "again": "(x+2)²=x²이 이차방정식인지 판단하는 방법을 말해 봐.", "fig": false, "src": "137쪽 예제 1", "miscon": "정리하지 않고 x²이 보이면 이차방정식이라고 판단함", "record": "정리한 뒤 x² 항이 남는지로 이차방정식을 판별하지 못함"}, {"kind": "성질", "q": "ax²+bx+c=0이 이차방정식이 되려면 a, b, c 중 어떤 계수에 어떤 조건이 필요하고, 왜 그래?", "ideas": [["x²의 계수 a가 0이 아니어야 한다", "a=0이면 식에서 어떤 항이 사라지지?"], ["b와 c는 0이어도 x² 항이 남으므로 이차방정식이다", "x²=0이나 x²−3x=0도 이차방정식일까?"]], "teach": "a=0이면 x² 항이 없어져 일차방정식 이하가 돼. b, c는 0이어도 ax²이 남으니 괜찮아. ax²+bx+c=3x²+2x+1이면 x²의 계수가 a−3이라 a≠3이 조건이야.", "again": "2ax²−x=4x²−8x+3이 이차방정식이 되기 위한 조건을 구하는 방법을 말해 봐.", "fig": false, "src": "137쪽 예제 2", "miscon": "b, c도 0이 아니어야 한다고 생각함", "record": "이차방정식의 조건이 x²의 계수만이라는 것을 설명하지 못함"}], "m3-1|3. 이차방정식|57. 이차방정식의 해란 무엇일까?": [{"kind": "뜻", "q": "이차방정식의 해(근)는 무엇이고, 이차방정식을 \"푼다\"는 건 무슨 뜻이야?", "ideas": [["이차방정식을 참이 되게 하는 미지수 x의 값이 해(근)이다", "x에 어떤 값을 넣었을 때 그 값이 방정식의 해라고 할 수 있지?"], ["해를 모두 구하는 것을 이차방정식을 푼다고 한다", "해를 하나만 찾으면 푼 걸까, 모두 찾아야 할까?"]], "teach": "x에 값을 넣어 좌변과 우변이 같아지면 그 값이 해(근)야. 해를 모두 구하는 걸 \"푼다\"고 해. 이차방정식은 해가 2개일 수도 있어서 하나만 찾으면 다 푼 게 아니야.", "again": "x=1이 x²−3x+2=0의 해인지 확인하는 방법을 말해 봐.", "fig": false, "src": "138쪽", "miscon": "해의 뜻을 계수와 혼동함", "record": "이차방정식의 해와 푼다는 뜻을 설명하지 못함"}, {"kind": "방법", "q": "x=2가 이차방정식 x²+ax+2=0의 해일 때 상수 a는 어떻게 구해?", "ideas": [["해는 방정식을 참이 되게 하므로 x=2를 대입한다", "x=2가 해라는 건 x에 2를 넣으면 어떻게 된다는 뜻이지?"], ["대입해서 생긴 a에 대한 식을 풀어 a를 구한다", "2²+2a+2=0은 무엇에 대한 방정식이 될까?"]], "teach": "해를 대입하면 등식이 성립해야 해. x=2를 넣으면 4+2a+2=0이라 a=−3. \"해가 주어지면 대입\"이 기본이야.", "again": "x=−1이 x²+kx−4=0의 해일 때 k를 구하는 방법을 말해 봐.", "fig": false, "src": "138쪽 예제 4", "miscon": "해가 주어졌을 때 대입할 생각을 못함", "record": "주어진 해를 대입해 미지의 계수를 구하는 방법을 모름"}], "m3-1|3. 이차방정식|58. AB=0이면 A, B는 어떤 값이 되어야 할까?": [{"kind": "성질", "q": "두 수 A, B에 대해 AB=0이면 A, B는 어떻게 되어야 하고, \"A=0 또는 B=0\"은 어떤 경우들을 합친 말이야?", "ideas": [["A=0 또는 B=0이다", "0이 아닌 두 수를 곱해서 0이 될 수 있을까?"], ["A=0, B=0인 경우와 A=0, B≠0인 경우와 A≠0, B=0인 경우를 모두 합친 말이다", "\"또는\"에는 둘 다 0인 경우도 들어갈까?"]], "teach": "0이 아닌 두 수의 곱은 0이 될 수 없어서 AB=0이면 둘 중 적어도 하나는 0이야. 세 경우(둘 다 0, A만 0, B만 0)를 통틀어 \"A=0 또는 B=0\"이라고 해.", "again": "AB=0일 때 A=0이면 B는 반드시 0이 아닐까? 이유를 말해 봐.", "fig": false, "src": "141쪽", "miscon": "AB=0이면 둘 다 0이어야 한다고 생각함", "record": "AB=0의 뜻(적어도 하나가 0)을 설명하지 못함"}, {"kind": "함정", "q": "(x+2)(x−3)=0의 해를 \"x=−2 그리고 x=3\"이 아니라 \"x=−2 또는 x=3\"이라고 쓰는 이유는?", "ideas": [["x+2=0 또는 x−3=0이므로 해는 x=−2 또는 x=3이다", "AB=0의 성질을 쓰면 두 괄호는 어떻게 돼야 해?"], ["x는 하나의 수라서 동시에 −2이면서 3일 수 없으므로 \"또는\"이다", "x가 −2와 3을 한꺼번에 가질 수 있을까?"]], "teach": "x+2=0 또는 x−3=0이라서 해는 x=−2 또는 x=3. x는 한 번에 한 값만 가질 수 있어서 둘이 동시에 성립할 수는 없어. 그래서 \"그리고\"가 아니라 \"또는\"이야.", "again": "x(x+5)=0의 해를 말하고, 왜 \"또는\"으로 쓰는지 말해 봐.", "fig": false, "src": "141쪽 THINK Math", "miscon": "두 해가 동시에 성립한다고 생각함", "record": "해를 \"또는\"으로 나타내는 이유를 설명하지 못함"}], "m3-1|3. 이차방정식|59. 인수분해를 이용하여 이차방정식의 해를 어떻게 구할까?": [{"kind": "방법", "q": "2x²+5x+2=0을 인수분해를 이용해 푸는 순서를 말해 봐.", "ideas": [["좌변을 두 일차식의 곱으로 인수분해한다", "2x²+5x+2는 어떤 두 일차식의 곱으로 나타낼 수 있을까?"], ["AB=0이면 A=0 또는 B=0인 성질을 이용해 각 일차식을 0으로 놓고 해를 구한다", "(x+2)(2x+1)=0에서 무엇이 0이 되어야 하지?"]], "teach": "ax²+bx+c=0 꼴로 정리 → 좌변 인수분해 → AB=0 성질 → 해. (x+2)(2x+1)=0이니까 x+2=0 또는 2x+1=0, 즉 x=−2 또는 x=−1/2.", "again": "x²−4x−12=0을 인수분해로 푸는 순서를 말해 봐.", "fig": false, "src": "142쪽", "miscon": "인수분해와 AB=0 성질을 연결하지 못함", "record": "인수분해로 이차방정식을 푸는 순서를 설명하지 못함"}, {"kind": "함정", "q": "(x+3)(x−1)=5를 보고 x+3=0 또는 x−1=0이라고 하면 왜 틀릴까?", "ideas": [["AB=0 성질은 우변이 0일 때만 쓸 수 있다", "AB=5일 때도 A나 B가 반드시 0이어야 할까?"], ["먼저 전개해 우변을 0으로 만든 뒤 다시 인수분해해야 한다", "(x+3)(x−1)=5를 ax²+bx+c=0 꼴로 정리하면 어떻게 될까?"]], "teach": "곱이 5라고 해서 한쪽이 0일 필요는 없어. 전개해서 x²+2x−8=0으로 정리한 다음 (x+4)(x−2)=0으로 인수분해해야 x=−4 또는 x=2가 나와.", "again": "x(x+8)=9를 풀 때 가장 먼저 해야 할 일을 말해 봐.", "fig": false, "src": "142쪽", "miscon": "우변이 0이 아닌데도 AB=0 성질을 씀", "record": "우변을 0으로 정리해야 AB=0 성질을 쓸 수 있다는 것을 모름"}], "m3-1|3. 이차방정식|60. 이차방정식의 중근이란?": [{"kind": "뜻", "q": "x²−6x+9=0을 풀면 해가 어떻게 되고, 이런 해를 뭐라고 불러?", "ideas": [["(x−3)²=0이라 두 근이 모두 3으로 같아진다", "x²−6x+9를 인수분해하면 어떤 식이 되지?"], ["두 근이 중복될 때 그 근을 중근이라고 한다", "서로 같은 두 근을 하나로 쓸 때 붙이는 이름이 뭐였지?"]], "teach": "x²−6x+9=(x−3)(x−3)=0이라 x=3 또는 x=3, 두 근이 같아. 이렇게 중복된 근을 중근이라 하고 x=3(중근)처럼 표시해.", "again": "(x+5)²=0의 해를 말하고 왜 중근이라고 하는지 말해 봐.", "fig": false, "src": "143쪽", "miscon": "완전제곱식=0의 해를 ±로 두 개라고 봄", "record": "중근의 뜻(두 근이 같음)을 설명하지 못함"}, {"kind": "함정", "q": "중근을 가진 이차방정식의 해를 \"x=3\"이라고만 쓰지 않고 \"x=3(중근)\"이라고 표시하는 이유는 뭘까?", "ideas": [["원래 두 근이 서로 같아서 하나로 쓴 것이다", "x²−6x+9=0은 원래 근이 몇 개였을까?"], ["해가 하나뿐인 다른 방정식과 구분하기 위해서이다", "일차방정식 x−3=0의 해 x=3과 무엇이 다를까?"]], "teach": "중근은 근이 사라진 게 아니라 두 근이 같은 자리에 겹친 거야. (중근)을 붙여 \"원래 두 근인데 같다\"는 걸 알려서, 해가 하나뿐인 경우와 구분해.", "again": "9x²=6x−1의 해를 쓸 때 (중근)을 붙이는 이유를 말해 봐.", "fig": false, "src": "143쪽 예제 6", "miscon": "중근을 해가 하나뿐인 것과 같다고 봄", "record": "중근 표시의 의미를 설명하지 못함"}], "m3-1|3. 이차방정식|61. 이차방정식은 어떤 경우에 중근을 가질까?": [{"kind": "성질", "q": "이차방정식이 중근을 가지려면 좌변이 어떻게 인수분해되어야 할까? x²+ax+b=0이면 조건은 뭐야?", "ideas": [["좌변이 완전제곱식으로 인수분해되어 (완전제곱식)=0 꼴이 되어야 한다", "중근이 생겼던 (x−3)²=0은 좌변이 어떤 식이었지?"], ["x²+ax+b=0이면 x의 계수의 절반의 제곱이 상수항과 같아야 한다(b=(a/2)²)", "x²−14x+49에서 −14의 절반을 제곱하면 얼마야?"]], "teach": "중근 ⇔ (완전제곱식)=0. x²+ax+b가 완전제곱식이려면 b=(a/2)²이어야 해. x²−14x+49는 (−7)²=49라 중근, x²−6x+10은 9≠10이라 중근이 아니야.", "again": "x²−8x+k=0이 중근을 갖는 k를 구하는 방법을 말해 봐.", "fig": false, "src": "143~144쪽", "miscon": "상수항이 제곱수이면 중근이라고 생각함", "record": "중근 조건(완전제곱식, b=(a/2)²)을 설명하지 못함"}, {"kind": "함정", "q": "3x²−12x+k=0이 중근을 가질 조건을 구할 때 x²+ax+b의 조건을 바로 쓰면 왜 틀릴까?", "ideas": [["x²의 계수가 1이 아니므로 먼저 양변을 3으로 나누거나 계수를 고려해야 한다", "x²+ax+b 꼴의 조건은 x²의 계수가 얼마일 때 쓴 거지?"], ["x의 계수의 절반의 제곱이 x²의 계수와 상수항의 곱과 같아야 한다", "(−12/2)²과 3×k를 비교해 볼래?"]], "teach": "x²의 계수가 3이면 (−12/2)²=3k, 즉 36=3k라 k=12. 3으로 나누면 x²−4x+k/3=0에서 (−2)²=k/3로도 같은 답이야. 계수 1인 조건을 그대로 쓰면 k=36으로 틀려.", "again": "x²의 계수가 1이 아닌 이차방정식의 중근 조건을 확인할 때 먼저 할 일을 말해 봐.", "fig": false, "src": "144쪽 예제 7", "miscon": "x²의 계수가 1이 아닌데 b=(a/2)²을 그대로 씀", "record": "x²의 계수가 1이 아닐 때 중근 조건을 적용하지 못함"}], "m3-1|3. 이차방정식|62. 제곱근을 이용하여 이차방정식을 어떻게 풀까?": [{"kind": "방법", "q": "x²=k (k≥0) 꼴이나 (x+p)²=k (k≥0) 꼴의 이차방정식은 제곱근을 이용해 어떻게 풀어?", "ideas": [["x²=k이면 x는 k의 제곱근이므로 x=±√k이다", "x²=5를 만족하는 x는 5의 무엇이지?"], ["(x+p)²=k이면 x+p=±√k로 놓고 x=−p±√k로 구한다", "(x−1)²=3에서 괄호 전체를 하나로 보면 x−1은 무엇일까?"]], "teach": "x²=k면 x는 k의 제곱근이라 ±√k. (x+p)²=k면 x+p=±√k라서 x=−p±√k. 예: (x−1)²=3 → x−1=±√3 → x=1±√3.", "again": "(x−2)²=7을 제곱근을 이용해 푸는 방법을 말해 봐.", "fig": false, "src": "144~145쪽", "miscon": "양의 제곱근만 해로 씀", "record": "제곱근을 이용한 풀이에서 ± 두 해를 구하지 못함"}, {"kind": "함정", "q": "4x²=64나 2x²−4=0처럼 x²의 계수가 1이 아니거나 상수항이 있으면 제곱근을 쓰기 전에 무엇을 해야 해?", "ideas": [["x²=k 꼴이 되도록 상수항을 옮기고 x²의 계수로 나눈다", "4x²=64에서 x²만 남기려면 어떻게 하지?"], ["그다음 x=±√k로 해를 구한다", "x²=16이 되면 x는 무엇이지?"]], "teach": "제곱근을 쓰려면 먼저 x²=k 꼴로 만들어야 해. 4x²=64 → x²=16 → x=±4, 2x²−4=0 → x²=2 → x=±√2. 계수를 안 나누고 √64로 하면 틀려.", "again": "4x²−3=0을 제곱근으로 풀 때 순서를 말해 봐.", "fig": false, "src": "145쪽 예제 8", "miscon": "x²의 계수를 나누지 않고 제곱근을 씀", "record": "x²=k 꼴로 정리한 뒤 제곱근을 쓰는 순서를 지키지 못함"}], "m3-1|3. 이차방정식|63. 완전제곱식을 이용하여 이차방정식을 어떻게 풀까?": [{"kind": "방법", "q": "인수분해가 안 되는 4x²−8x−3=0을 완전제곱식을 이용해 푸는 과정을 순서대로 말해 봐.", "ideas": [["양변을 x²의 계수로 나누고 상수항을 우변으로 옮긴다", "x²의 계수를 1로 만들고 x가 없는 항은 어디로 보내지?"], ["x의 계수의 절반의 제곱을 양변에 더해 좌변을 완전제곱식으로 만든다", "x²−2x에 무엇을 더하면 완전제곱식이 될까?"], ["(x+p)²=k 꼴에서 제곱근을 이용해 해를 구한다", "(x−1)²=7/4이 되면 어떤 방법으로 풀지?"]], "teach": "4로 나눠 x²−2x−3/4=0 → x²−2x=3/4 → 양변에 (−2/2)²=1을 더해 (x−1)²=7/4 → x−1=±√7/2 → x=1±√7/2.", "again": "x²+8x+4=0을 완전제곱식으로 풀 때 양변에 더하는 수와 이유를 말해 봐.", "fig": false, "src": "145~146쪽", "miscon": "인수분해가 안 되면 풀 수 없다고 생각함", "record": "완전제곱식으로 고쳐 푸는 순서를 설명하지 못함"}, {"kind": "함정", "q": "완전제곱식을 만들 때 x의 계수의 절반의 제곱을 좌변에만 더하면 왜 틀릴까?", "ideas": [["등식은 양변에 같은 수를 더해야 성립하므로 우변에도 더해야 한다", "좌변에만 수를 더하면 좌변과 우변이 여전히 같을까?"]], "teach": "x²−2x=3/4에서 좌변에만 1을 더하면 등식이 깨져. 양변에 똑같이 더해야 x²−2x+1=3/4+1, 곧 (x−1)²=7/4로 올바른 식이 돼.", "again": "x²+6x=−4에서 완전제곱식을 만들 때 9를 어디에 더해야 하는지 말해 봐.", "fig": false, "src": "145쪽", "miscon": "등식의 한쪽에만 수를 더함", "record": "등식의 성질(양변에 같은 수를 더함)을 완전제곱식 풀이에 적용하지 못함"}], "m3-1|3. 이차방정식|64. 이차방정식이 근을 가질 조건은 무엇일까?": [{"kind": "성질", "q": "이차방정식을 (x+p)²=k 꼴로 고쳤을 때, k의 값에 따라 근이 어떻게 달라져?", "ideas": [["k>0이면 서로 다른 두 근을 갖는다", "(x+2)²=3이면 x+2는 몇 개의 값이 될 수 있을까?"], ["k=0이면 중근을 갖는다", "(x+2)²=0이면 x+2는 무엇이어야 하지?"], ["k<0이면 제곱해서 음수가 되는 수가 없어 근이 없다", "(x+2)²=−2를 만족하는 실수가 있을까?"]], "teach": "(x+p)²=k에서 k>0이면 x+p=±√k로 근 2개, k=0이면 x+p=0으로 중근 1개, k<0이면 제곱해서 음수가 되는 실수가 없어 근이 없어. 그래서 근을 가질 조건은 k≥0.", "again": "(x+1/2)²=k−2가 근을 갖기 위한 k의 범위를 구하는 방법을 말해 봐.", "fig": false, "src": "146~147쪽", "miscon": "k<0이어도 근이 있다고 생각함", "record": "(x+p)²=k에서 k의 부호에 따른 근의 개수를 설명하지 못함"}, {"kind": "이유", "q": "x²+4x+6=0의 해가 없는 이유를 완전제곱식으로 설명해 봐.", "ideas": [["완전제곱식으로 고치면 (x+2)²=−2가 된다", "x²+4x에 4를 더해 완전제곱식을 만들면 우변은 얼마가 되지?"], ["어떤 실수를 제곱해도 음수가 될 수 없으므로 해가 없다", "제곱해서 −2가 되는 실수가 있을까?"]], "teach": "x²+4x=−6 → 양변에 4를 더해 (x+2)²=−2. 제곱은 항상 0 이상이라 −2가 될 수 없으니 실수 해가 없어.", "again": "(x−1)²=−5의 해가 없는 이유를 한 문장으로 말해 봐.", "fig": false, "src": "146쪽", "miscon": "해가 없는 것을 계산이 어려운 것으로 착각함", "record": "제곱이 음수가 될 수 없어 해가 없다는 것을 설명하지 못함"}], "m3-1|3. 이차방정식|65. 이차방정식의 근의 공식이란?": [{"kind": "뜻", "q": "이차방정식 ax²+bx+c=0 (a≠0)의 근의 공식은 무엇이고, 어떤 방법으로 만들어졌어?", "ideas": [["x=(−b±√(b²−4ac))/2a (단, b²−4ac≥0)이다", "근의 공식은 a, b, c로 어떻게 나타냈지?"], ["ax²+bx+c=0을 완전제곱식으로 고쳐 제곱근을 구하는 과정으로 만들었다", "인수분해가 안 될 때 썼던 풀이 방법을 문자로 하면 어떻게 될까?"]], "teach": "양변을 a로 나누고 상수항을 옮긴 뒤 (b/2a)²을 더하면 (x+b/2a)²=(b²−4ac)/4a². 제곱근을 구하면 x=(−b±√(b²−4ac))/2a. 완전제곱식 풀이를 문자로 한 번에 해 둔 것이 근의 공식이야.", "again": "근의 공식이 완전제곱식 풀이와 어떤 관계인지 말해 봐.", "fig": false, "src": "156쪽", "miscon": "근의 공식을 유도 과정과 연결하지 못함", "record": "근의 공식이 완전제곱식 풀이에서 나왔다는 것을 설명하지 못함"}, {"kind": "함정", "q": "2x²−3x−6=0을 근의 공식으로 풀 때 a, b, c를 정하면서 조심할 점은?", "ideas": [["ax²+bx+c=0 꼴로 정리한 뒤 계수를 읽는다", "우변이 0인지 먼저 확인했어?"], ["b와 c는 부호까지 포함해 b=−3, c=−6으로 대입한다", "−3x에서 b는 3일까, −3일까?"]], "teach": "정리된 식에서 a=2, b=−3, c=−6이야. −b는 −(−3)=3, b²=(−3)²=9, −4ac=−4×2×(−6)=48. 부호를 빼고 넣으면 해가 달라져.", "again": "x²+6x−5=0에서 a, b, c를 읽고 대입할 때 조심할 점을 말해 봐.", "fig": false, "src": "156쪽 예제 11", "miscon": "계수의 부호를 빼고 대입함", "record": "근의 공식에 계수를 부호까지 정확히 대입하지 못함"}], "m3-1|3. 이차방정식|66. 일차항의 계수가 짝수일 때 쓰는 근의 공식이 따로 있다?": [{"kind": "방법", "q": "x의 계수가 짝수인 ax²+2b′x+c=0에서 쓰는 짝수 근의 공식은 무엇이고, 어떻게 나왔어?", "ideas": [["x=(−b′±√(b′²−ac))/a 이다", "b=2b′일 때 짝수 근의 공식에서 분모는 무엇이 되지?"], ["근의 공식에 b=2b′를 넣으면 분자와 분모가 2로 약분되어 나온 식이다", "(−2b′±√(4b′²−4ac))/2a를 약분하면 어떻게 될까?"]], "teach": "b=2b′를 넣으면 (−2b′±2√(b′²−ac))/2a가 되고, 2로 약분하면 (−b′±√(b′²−ac))/a야. 새 공식이 아니라 근의 공식을 약분해 둔 거라 계산이 짧아.", "again": "x²+6x−5=0을 짝수 근의 공식으로 풀 때 b′가 무엇인지 말해 봐.", "fig": false, "src": "157쪽", "miscon": "짝수 근의 공식을 근의 공식과 무관한 새 공식으로 봄", "record": "짝수 근의 공식이 근의 공식을 약분한 것임을 설명하지 못함"}, {"kind": "함정", "q": "5x²+6x−2=0을 짝수 근의 공식으로 풀 때 틀리기 쉬운 곳은?", "ideas": [["b′에는 x의 계수의 절반인 3을 넣는다", "x의 계수 6을 그대로 넣으면 될까?"], ["분모에는 2a가 아니라 a가 온다", "짝수 근의 공식의 분모는 무엇이었지?"]], "teach": "b′=3, a=5, c=−2라서 x=(−3±√(9+10))/5=(−3±√19)/5. b′ 자리에 6을 넣거나 분모를 2a=10으로 쓰면 틀려.", "again": "짝수 근의 공식을 쓸 때 근의 공식과 달라지는 두 곳을 말해 봐.", "fig": false, "src": "157쪽 예제 12", "miscon": "짝수 근의 공식에서 b′나 분모를 근의 공식과 섞어 씀", "record": "짝수 근의 공식의 b′와 분모를 정확히 적용하지 못함"}], "m3-1|3. 이차방정식|67. 계수가 소수 또는 분수인 이차방정식은 어떻게 풀까?": [{"kind": "방법", "q": "(1/6)x²+(1/4)x−1/3=0이나 0.7x²−x+0.2=0처럼 계수가 분수나 소수인 이차방정식은 풀기 전에 무엇을 해?", "ideas": [["계수가 모두 정수가 되도록 양변에 같은 수를 곱한다", "분수나 소수를 없애려면 양변에 무엇을 할 수 있지?"], ["분수는 분모의 최소공배수를, 소수는 10의 거듭제곱을 곱한다", "분모 6, 4, 3을 모두 없애려면 몇을 곱하면 될까?"]], "teach": "분수는 분모의 최소공배수 12를 곱해 2x²+3x−4=0, 소수는 10을 곱해 7x²−10x+2=0. 정수로 바꾼 뒤 인수분해나 근의 공식을 쓰면 계산이 쉬워.", "again": "(1/2)x²−(5/6)x−1/3=0을 정수 계수로 바꾸려면 몇을 곱하는지 말해 봐.", "fig": false, "src": "158쪽", "miscon": "분수·소수 계수를 그대로 근의 공식에 넣음", "record": "계수를 정수로 고친 뒤 푸는 방법을 모름"}, {"kind": "함정", "q": "계수가 분수인 이차방정식에서 양변에 12를 곱할 때 틀리기 쉬운 점은?", "ideas": [["모든 항에 빠짐없이 12를 곱해야 한다", "상수항 −1/3에도 12를 곱했어?"], ["우변이 0이면 곱해도 0이라 등식은 그대로 유지된다", "0에 12를 곱하면 얼마야?"]], "teach": "양변에 곱할 때는 좌변의 모든 항과 우변에 똑같이 곱해. 한 항이라도 빼먹으면 다른 방정식이 돼. 우변 0은 곱해도 0이라 그대로야.", "again": "0.3x²+x−0.2=0에 10을 곱할 때 확인할 점을 말해 봐.", "fig": false, "src": "158쪽", "miscon": "일부 항에만 수를 곱함", "record": "양변에 같은 수를 곱할 때 모든 항에 곱해야 한다는 것을 적용하지 못함"}], "m3-1|3. 이차방정식|68. 괄호가 있는 이차방정식은 어떻게 풀까?": [{"kind": "방법", "q": "(2x+1)²=x²+2처럼 괄호가 있는 이차방정식은 어떤 순서로 풀어?", "ideas": [["분배법칙이나 곱셈 공식으로 괄호를 푼다", "(2x+1)²을 전개하면 어떻게 되지?"], ["동류항끼리 모아 ax²+bx+c=0 꼴로 정리한 뒤 인수분해나 근의 공식으로 푼다", "괄호를 푼 뒤 모든 항을 좌변으로 옮기면 어떤 꼴이 되어야 할까?"]], "teach": "(2x+1)²=4x²+4x+1이라 4x²+4x+1=x²+2 → 3x²+4x−1=0. 인수분해가 안 되면 짝수 근의 공식으로 x=(−2±√7)/3.", "again": "x(x−3)=2(x+1)을 푸는 순서를 말해 봐.", "fig": false, "src": "158~159쪽", "miscon": "우변이 0이 아닌데 괄호마다 0으로 놓음", "record": "괄호를 풀고 일반형으로 정리한 뒤 푸는 순서를 모름"}, {"kind": "함정", "q": "(x+4)(x+3)=2(x+3)의 양변을 x+3으로 나누면 x+4=2라서 x=−2만 나와. 왜 틀릴까?", "ideas": [["x+3이 0일 수도 있어서 x+3으로 나누면 해 x=−3을 잃는다", "x=−3을 넣으면 x+3은 얼마가 되지? 0으로 나눌 수 있을까?"], ["나누지 말고 이항해서 정리하거나 공통인수로 묶어 인수분해한다", "(x+4)(x+3)−2(x+3)=0에서 공통으로 있는 식은 무엇이지?"]], "teach": "x+3=0일 수 있어서 나누면 x=−3을 놓쳐. (x+3)(x+4)−2(x+3)=0 → (x+3)(x+2)=0 → x=−3 또는 x=−2. 미지수가 들어 있는 식으로는 나누지 말고 묶어.", "again": "x(x−5)=3x처럼 양변에 x가 있을 때 x로 나누면 안 되는 이유를 말해 봐.", "fig": false, "src": "142쪽 예제 5", "miscon": "미지수가 들어 있는 식으로 양변을 나눔", "record": "0이 될 수 있는 식으로 나누면 해를 잃는다는 것을 모름"}], "m3-1|3. 이차방정식|69. 공통부분이 있는 이차방정식은 어떻게 풀까?": [{"kind": "방법", "q": "(x+2)²+4(x+2)−5=0처럼 공통부분이 있는 이차방정식은 어떻게 풀어?", "ideas": [["공통부분 x+2를 A로 치환한다", "식에서 반복해서 나오는 부분은 무엇이지?"], ["A에 대한 방정식을 풀고, A에 원래 식을 넣어 x의 값을 구한다", "A=1이 나왔다면 x는 어떻게 구할까?"]], "teach": "x+2=A로 두면 A²+4A−5=0 → (A+5)(A−1)=0 → A=−5 또는 A=1. 여기서 끝이 아니라 x+2=−5 또는 x+2=1이라 x=−7 또는 x=−1.", "again": "(x−1)²−3(x−1)+2=0을 치환으로 푸는 순서를 말해 봐.", "fig": false, "src": "159쪽", "miscon": "공통부분을 보지 못하고 전개만 함", "record": "공통부분을 치환해 이차방정식을 푸는 방법을 모름"}, {"kind": "함정", "q": "(x+2)²+4(x+2)−5=0을 A로 치환해 A=−5 또는 A=1을 구한 뒤 이것을 답으로 쓰면 왜 틀릴까?", "ideas": [["구한 것은 A의 값이지 x의 값이 아니다", "문제가 구하라고 한 것은 A일까, x일까?"], ["A=x+2를 대입해 x에 대한 방정식을 한 번 더 풀어야 한다", "x+2=1이면 x는 얼마지?"]], "teach": "A는 잠깐 바꿔 쓴 문자라서 A=−5, A=1은 x의 해가 아니야. x+2=−5, x+2=1로 되돌려 x=−7 또는 x=−1까지 구해야 끝나.", "again": "치환으로 이차방정식을 풀 때 마지막에 꼭 하는 일을 말해 봐.", "fig": false, "src": "159쪽 예제 15", "miscon": "치환한 문자의 값을 해로 씀", "record": "치환 후 원래 미지수의 값으로 되돌리지 못함"}], "m3-1|3. 이차방정식|70. 이차방정식의 해를 구하지 않고 근의 개수를 알 수 있다?": [{"kind": "성질", "q": "이차방정식 ax²+bx+c=0의 근을 구하지 않고 근의 개수를 알려면 무엇을 보고, 어떻게 판단해?", "ideas": [["근의 공식의 근호 안 식 b²−4ac의 부호를 본다", "근의 공식에서 근의 개수를 정하는 부분은 어디일까?"], ["양수이면 2개, 0이면 1개(중근), 음수이면 근이 없다", "√ 안이 음수이면 근이 존재할 수 있을까?"]], "teach": "근의 공식에서 √(b²−4ac)가 근의 개수를 정해. 양수면 ±로 서로 다른 두 근, 0이면 중근, 음수면 제곱근이 없어 근이 없어. x의 계수가 짝수면 b′²−ac로 봐도 돼.", "again": "x²−6x+9=0의 근의 개수를 계산 없이 판단하는 방법을 말해 봐.", "fig": false, "src": "160쪽", "miscon": "근의 개수를 계수 하나의 부호로 판단함", "record": "b²−4ac의 부호로 근의 개수를 판단하는 방법을 설명하지 못함"}, {"kind": "적용", "q": "4x²+(m+1)x+1=0이 중근을 가질 때 상수 m은 어떤 식을 세워서 구해? x²+ax+b의 조건 대신 이 방법을 쓰는 이유는?", "ideas": [["b²−4ac=0이라는 식을 세워 m에 대한 방정식을 푼다", "중근을 가질 때 b²−4ac는 얼마여야 하지?"], ["x²의 계수가 1이 아니거나 계수에 문자가 있어도 바로 쓸 수 있기 때문이다", "x²의 계수가 4일 때 b=(a/2)² 조건을 바로 쓸 수 있을까?"]], "teach": "중근 ⇔ b²−4ac=0. (m+1)²−4×4×1=0 → (m+5)(m−3)=0 → m=−5 또는 3. x²의 계수가 1이 아니어도 계수에 문자가 있어도 그대로 쓸 수 있어 편해.", "again": "x²−8x+k=0이 서로 다른 두 근을 갖는 k의 조건을 세우는 방법을 말해 봐.", "fig": false, "src": "161쪽 예제 17", "miscon": "중근 조건을 판별식으로 세우지 못함", "record": "계수에 문자가 있을 때 b²−4ac=0으로 조건을 세우지 못함"}], "m3-1|3. 이차방정식|71. 이차방정식의 근과 계수 사이에는 어떤 관계가 있을까?": [{"kind": "성질", "q": "ax²+bx+c=0의 두 근을 α, β라 하면 두 근의 합과 곱은 계수로 어떻게 나타나고, 왜 그런 관계가 생겨?", "ideas": [["두 근의 합은 −b/a, 곱은 c/a이다", "x²−5x+6=0의 두 근 2, 3의 합과 곱이 계수와 어떤 관계인지 볼래?"], ["근의 공식으로 구한 두 근을 더하면 근호 부분이 지워지고, 곱하면 합차 공식으로 근호가 없어진다", "(−b+√D)/2a와 (−b−√D)/2a를 더하면 √D는 어떻게 되지?"]], "teach": "두 근은 √(b²−4ac) 앞 부호만 달라. 더하면 근호가 지워져 −b/a, 곱하면 합차 공식으로 (b²−(b²−4ac))/4a²=c/a. 근을 구하지 않고 계수만으로 합과 곱을 알 수 있어.", "again": "2x²−4x−1=0의 두 근의 합과 곱을 구하는 방법을 말해 봐.", "fig": false, "src": "161~162쪽", "miscon": "두 근의 합의 부호를 틀림", "record": "근과 계수의 관계와 그 이유를 설명하지 못함"}, {"kind": "함정", "q": "계수가 유리수인 이차방정식 x²−6x+k=0의 한 근이 3+√2일 때, 다른 한 근은 무엇이고 왜 그래?", "ideas": [["다른 한 근은 3−√2이다", "3+√2에서 근호 앞 부호를 바꾸면 어떤 수가 되지?"], ["근의 공식에서 두 근은 근호 앞 부호만 다르므로 계수가 유리수이면 p+q√m의 짝은 p−q√m이다", "근의 공식의 두 근을 떠올려 봐. 두 근은 어디만 다르지?"]], "teach": "계수가 유리수이면 두 근은 (유리수)±(근호 부분) 꼴이라 한 근이 3+√2면 다른 근은 3−√2야. 그래서 k=(3+√2)(3−√2)=7. 계수가 유리수라는 조건이 없으면 이 성질을 쓸 수 없어.", "again": "계수가 유리수인 이차방정식의 한 근이 2−√5일 때 다른 근을 말하고 이유를 말해 봐.", "fig": false, "src": "162쪽 예제 19", "miscon": "무리수 근의 짝을 부호 전체를 바꿔서 구함", "record": "계수가 유리수일 때 무리수 근이 짝으로 나오는 이유를 설명하지 못함"}], "m3-1|3. 이차방정식|72. 두 근이 α, β이고, x²의 계수가 a인 이차방정식은 어떻게 나타낼까?": [{"kind": "방법", "q": "두 근이 α, β이고 x²의 계수가 a인 이차방정식은 어떻게 나타내? 두 가지 방법을 말해 봐.", "ideas": [["a(x−α)(x−β)=0으로 나타낸다", "x=α일 때 0이 되는 일차식은 무엇이지?"], ["두 근의 합과 곱을 이용해 a{x²−(α+β)x+αβ}=0으로 나타낸다", "(x−α)(x−β)를 전개하면 x의 계수와 상수항 자리에 무엇이 오지?"]], "teach": "α, β를 해로 가지려면 (x−α)(x−β)=0. x²의 계수를 a로 맞추려면 a를 곱해. 전개하면 a{x²−(α+β)x+αβ}=0이라 합과 곱만 알아도 만들 수 있어.", "again": "두 근이 −3, 5이고 x²의 계수가 2인 이차방정식을 만드는 방법을 말해 봐.", "fig": false, "src": "163쪽", "miscon": "근의 부호를 바꾸지 않고 (x+α)(x+β)로 씀", "record": "두 근으로 이차방정식을 만드는 방법(부호·계수)을 모름"}, {"kind": "함정", "q": "중근이 −2이고 x²의 계수가 1인 이차방정식을 만들 때와, 두 근의 합이 4, 곱이 −2이고 x²의 계수가 3인 이차방정식을 만들 때 각각 조심할 점은?", "ideas": [["중근이 −2이면 (x+2)²=0으로 같은 일차식을 두 번 곱한다", "중근은 두 근이 어떻다는 뜻이었지?"], ["x²의 계수가 3이면 x²−4x−2 전체에 3을 곱해 3x²−12x−6=0으로 만든다", "x²의 계수를 3으로 만들려면 어느 항에 3을 곱해야 하지?"]], "teach": "중근 α는 두 근이 모두 α라서 a(x−α)²=0. 합·곱으로 만들 때는 x²−(합)x+(곱)=0 전체에 a를 곱해: 3(x²−4x−2)=0. x²에만 3을 붙이면 틀려.", "again": "두 근의 합이 −1, 곱이 −6이고 x²의 계수가 2인 이차방정식을 만들 때 조심할 점을 말해 봐.", "fig": false, "src": "163쪽 예제 20", "miscon": "x²의 계수를 맞출 때 x² 항에만 곱함", "record": "중근과 x²의 계수를 반영해 이차방정식을 만들지 못함"}], "m3-1|3. 이차방정식|73. 이차방정식의 활용 문제에 접근하는 노하우는?": [{"kind": "방법", "q": "이차방정식의 활용 문제는 어떤 순서로 풀어?", "ideas": [["구하려는 것을 미지수 x로 놓는다", "문제에서 모르는 것 중 무엇을 x로 정하면 좋을까?"], ["주어진 조건으로 이차방정식을 세워 푼다", "문제 속 수량 사이의 관계를 식으로 나타내면?"], ["구한 해 중 문제의 뜻에 맞는 것만 답으로 고른다", "길이가 음수로 나오면 답이 될 수 있을까?"]], "teach": "① 미지수 정하기 ② 이차방정식 세우기 ③ 풀기 ④ 문제 뜻에 맞는 답 고르기. 이차방정식은 해가 두 개라 ④가 특히 중요해: 길이·개수는 양수, 자연수 조건을 확인해.", "again": "정사각형의 가로를 7 cm 늘리고 세로를 1 cm 줄였더니 넓이가 20 cm²가 된 문제를 푸는 순서를 말해 봐.", "fig": false, "src": "165쪽", "miscon": "구한 해를 모두 답으로 씀", "record": "활용 문제에서 해가 문제의 뜻에 맞는지 확인하는 단계를 빠뜨림"}, {"kind": "함정", "q": "처음 정사각형의 한 변의 길이를 x cm로 놓고 (x+7)(x−1)=20을 풀었더니 x=−9 또는 x=3이 나왔어. 답은 무엇이고 왜 그래?", "ideas": [["길이는 양수여야 하므로 x=−9는 버린다", "한 변의 길이가 −9 cm일 수 있을까?"], ["따라서 문제의 뜻에 맞는 x=3이 답이다", "남은 해 중 조건에 맞는 것은?"]], "teach": "방정식의 해는 두 개지만 한 변의 길이는 양수여야 해. x=−9는 버리고 x=3, 곧 3 cm가 답이야. 줄인 세로 x−1=2도 양수라 조건에 맞아.", "again": "연속하는 자연수 문제에서 음수 해가 나왔을 때 어떻게 하는지 말해 봐.", "fig": false, "src": "165쪽", "miscon": "음수 해를 그대로 답으로 씀", "record": "문제의 조건(길이는 양수)으로 해를 고르지 못함"}], "m3-1|3. 이차방정식|74. 연속하는 수에 관한 문제는 어떻게 해결할까?": [{"kind": "방법", "q": "연속하는 세 자연수나 연속하는 두 홀수는 미지수 x로 어떻게 나타내?", "ideas": [["연속하는 세 자연수는 x−1, x, x+1 또는 x, x+1, x+2로 놓는다", "연속하는 수는 얼마씩 커지지?"], ["연속하는 두 홀수(짝수)는 x, x+2로 놓는다", "연속하는 홀수끼리는 얼마만큼 차이 나지?"]], "teach": "연속하는 정수는 1씩 커지니까 x−1, x, x+1(가운데를 x로) 또는 x, x+1, x+2(가장 작은 수를 x로). 연속하는 홀수나 짝수는 2씩 차이 나서 x, x+2.", "again": "연속하는 두 짝수를 x로 나타내는 방법을 말해 봐.", "fig": false, "src": "166쪽", "miscon": "연속하는 홀수를 1씩 차이 나게 놓음", "record": "연속하는 수를 미지수로 나타내는 방법을 모름"}, {"kind": "함정", "q": "연속하는 세 자연수 문제에서 가운데 수를 x로 놓을 때와 가장 작은 수를 x로 놓을 때, x의 값과 최종 답은 어떻게 달라?", "ideas": [["x로 놓은 수가 달라서 x의 값은 다르게 나온다", "가운데 수를 x로 놓았을 때와 가장 작은 수를 x로 놓았을 때 x는 같은 수를 뜻할까?"], ["하지만 구하는 세 수나 그 합은 같다", "결국 구하는 세 자연수가 달라질까?"]], "teach": "가운데를 x로 놓으면 x=4, 가장 작은 수를 x로 놓으면 x=3이 나와. x가 가리키는 수만 다를 뿐 세 수 3, 4, 5와 합 12는 같아. 답을 쓸 때 x가 무엇이었는지 꼭 확인해.", "again": "미지수를 다르게 놓았는데 x의 값이 달라졌을 때 답이 틀린 건지 판단하는 방법을 말해 봐.", "fig": false, "src": "166쪽", "miscon": "x의 값이 다르면 틀린 풀이라고 생각함", "record": "미지수를 무엇으로 놓았는지와 최종 답의 관계를 설명하지 못함"}], "m3-1|3. 이차방정식|75. 간단한 공식을 적용하는 문제는 어떻게 해결할까?": [{"kind": "방법", "q": "n번째 삼각형 모양에 쓰인 점의 개수가 n(n+1)/2일 때, 점이 55개인 삼각형이 몇 번째인지 어떻게 구해?", "ideas": [["주어진 공식을 55와 같다고 놓아 n(n+1)/2=55라는 이차방정식을 세운다", "공식 값이 55가 된다는 걸 식으로 쓰면?"], ["이차방정식을 풀고 n은 자연수이므로 양수인 해만 답으로 고른다", "n=−11도 \"몇 번째\"의 답이 될 수 있을까?"]], "teach": "n(n+1)/2=55 → n²+n−110=0 → (n+11)(n−10)=0 → n=−11 또는 10. 몇 번째인지는 자연수라 n=10이야.", "again": "n각형의 대각선 개수 n(n−3)/2가 20일 때 n을 구하는 방법을 말해 봐.", "fig": false, "src": "167쪽", "miscon": "자연수 조건을 확인하지 않음", "record": "공식으로 이차방정식을 세우고 자연수 조건으로 답을 고르지 못함"}, {"kind": "연결", "q": "n(n+1)/2 같은 공식에서 \"n=10일 때 점의 개수\"를 구하는 문제와 \"점이 55개일 때 n\"을 구하는 문제는 푸는 방법이 어떻게 달라?", "ideas": [["n이 주어지면 공식에 대입해 계산만 하면 된다", "n=10을 알 때는 공식에 무엇을 하면 값이 나오지?"], ["값이 주어지고 n을 구할 때는 공식=값으로 놓은 방정식을 풀어야 하고, n²이 생겨 이차방정식이 된다", "n(n+1)/2=55를 정리하면 n의 몇 차방정식이 될까?"]], "teach": "n을 알면 대입해서 계산하면 끝(10×11÷2=55). 거꾸로 값을 알고 n을 찾으려면 n(n+1)/2=55를 풀어야 하는데, n×n이 생겨서 이차방정식이 돼. 같은 공식이라도 무엇을 구하느냐에 따라 방법이 달라.", "again": "1부터 n까지의 합이 78일 때 n을 구하는 문제가 이차방정식이 되는 이유를 말해 봐.", "fig": false, "src": "167쪽 참고", "miscon": "거꾸로 구하는 문제도 대입으로 해결된다고 생각함", "record": "공식에서 값을 구하는 것과 미지수를 구하는 것(방정식)을 구분하지 못함"}], "m3-1|3. 이차방정식|76. 쏘아 올린 물체에 관한 문제는 어떻게 해결할까?": [{"kind": "함정", "q": "초속 40 m로 위로 던진 공의 t초 후 높이가 (40t−5t²) m일 때, 높이가 60 m인 지점을 지나는 시각이 두 개 나오는 이유는?", "ideas": [["40t−5t²=60을 풀면 t=2 또는 t=6이 나온다", "높이가 60 m가 되는 순간을 식으로 세우면?"], ["공은 올라갈 때 한 번, 내려올 때 한 번 같은 높이를 지나므로 두 해가 모두 답이다", "공이 올라갔다 내려오는 동안 60 m 높이를 몇 번 지날까?"]], "teach": "40t−5t²=60 → t²−8t+12=0 → t=2 또는 6. 올라가면서 2초에, 내려오면서 6초에 60 m를 지나서 두 해가 모두 문제의 뜻에 맞아. 음수 해를 버리는 문제와 달라.", "again": "같은 공이 지면에 떨어지는 시각을 구할 때 t=0은 답이 되는지 이유와 함께 말해 봐.", "fig": false, "src": "167~168쪽", "miscon": "두 해 중 하나를 무조건 버림", "record": "물체가 같은 높이를 두 번 지나는 상황을 해와 연결하지 못함"}, {"kind": "적용", "q": "같은 공이 지면에 떨어지는 것은 던진 지 몇 초 후인지 구하려면 어떤 식을 세우고, 해 중 무엇을 고르지?", "ideas": [["지면에 떨어질 때 높이가 0이므로 40t−5t²=0을 세운다", "공이 땅에 닿는 순간의 높이는 얼마지?"], ["t=0은 던지는 순간이므로 t=8을 답으로 고른다", "t=0은 공이 떨어지는 순간일까, 던지는 순간일까?"]], "teach": "높이 0 → 40t−5t²=0 → t(t−8)=0 → t=0 또는 8. t=0은 던진 순간(땅에서 출발)이라 떨어지는 시각은 8초 후야.", "again": "떨어지는 시각을 구할 때 t=0을 답에서 빼는 이유를 한 문장으로 말해 봐.", "fig": false, "src": "168쪽", "miscon": "지면에 떨어짐을 높이 0으로 나타내지 못함", "record": "떨어지는 시각을 높이 0으로 세우고 t=0을 구분하지 못함"}], "m3-1|3. 이차방정식|77. 도형의 넓이에 관한 문제는 어떻게 해결할까?": [{"kind": "방법", "q": "정사각형 종이의 네 귀퉁이를 2 cm씩 잘라 밑면이 정사각형인 상자를 만들었고 전개도의 넓이가 105 cm²일 때, 밑면의 한 변을 x cm로 놓고 어떤 식을 세워?", "ideas": [["처음 정사각형의 한 변은 x+4 cm이다", "밑면의 한 변 양쪽에 2 cm씩 붙어 있으면 처음 한 변은 얼마지?"], ["처음 넓이에서 잘라 낸 네 귀퉁이의 넓이를 빼 (x+4)²−16=105를 세운다", "잘라 낸 네 정사각형의 넓이는 모두 얼마지?"]], "teach": "처음 종이의 한 변은 x+2+2=x+4, 잘라 낸 넓이는 2²×4=16. 전개도 넓이는 (x+4)²−16=105 → x²+8x−105=0 → (x+15)(x−7)=0 → 길이는 양수라 x=7.", "again": "가로가 세로보다 3 cm 긴 직사각형의 넓이가 40 cm²일 때 세울 식을 말해 봐.", "fig": false, "src": "168쪽", "miscon": "잘라 낸 부분을 한쪽만 더함", "record": "도형 문제에서 길이 관계를 식으로 세우지 못함"}, {"kind": "함정", "q": "도형의 넓이 문제에서 이차방정식의 해가 x=−15 또는 x=7로 나왔어. 답을 고를 때 무엇을 확인해야 해?", "ideas": [["변의 길이는 항상 양수이므로 음수 해는 버린다", "한 변의 길이가 −15 cm인 도형이 있을까?"], ["남은 해를 넣었을 때 다른 변의 길이도 양수인지 확인한다", "x=7일 때 다른 변의 길이는 양수일까?"]], "teach": "길이는 양수라 x=−15는 버려. x=7이면 처음 한 변 11 cm도 양수라 조건에 맞아. 다른 변이 x−5 같은 꼴이면 그 값도 양수인지 꼭 확인해.", "again": "직사각형의 세로가 x−4로 나타날 때 해를 고르는 기준을 말해 봐.", "fig": false, "src": "168쪽", "miscon": "조건 확인 없이 큰 값을 답으로 고름", "record": "도형 문제에서 모든 변의 길이가 양수인지로 해를 고르지 못함"}], "m3-1|4. 이차함수|78. 이차함수란 무엇일까?": [{"kind": "뜻", "q": "이차함수는 어떤 함수이고, y=ax²+bx+c가 이차함수가 되려면 어떤 조건이 필요해?", "ideas": [["함수 y=f(x)에서 y가 x에 대한 이차식으로 나타내어지는 함수이다", "일차함수는 y가 x에 대한 일차식이었지? 이차함수는?"], ["x²의 계수 a가 0이 아니어야 하고, b나 c는 0이어도 된다", "a=0이면 y=bx+c는 어떤 함수가 되지?"]], "teach": "y가 x에 대한 이차식 ax²+bx+c (a≠0)로 나타내어지면 이차함수야. a=0이면 y=bx+c로 일차함수가 되니까 a≠0이 꼭 필요하고, b·c는 0이어도 x²이 남아 이차함수야.", "again": "y=3x²이 이차함수인 이유를 조건을 써서 말해 봐.", "fig": false, "src": "190~191쪽", "miscon": "식을 정리하지 않고 x²이 보이면 이차함수라고 봄", "record": "이차함수의 뜻과 a≠0 조건을 설명하지 못함"}, {"kind": "함정", "q": "y=x²−(x−1)²이나 y=3/(x²+1)은 겉보기에 x²이 있는데도 이차함수가 아니야. 각각 왜 그럴까?", "ideas": [["y=x²−(x−1)²은 전개해 정리하면 x²이 없어져 y=2x−1인 일차함수가 된다", "(x−1)²을 전개해서 빼면 x² 항은 어떻게 돼?"], ["y=3/(x²+1)은 분모에 x가 있어 x에 대한 이차식(다항식)이 아니다", "분모에 x가 있는 식도 이차식이라고 할 수 있을까?"]], "teach": "이차함수인지는 우변을 정리한 뒤 판단해. x²−(x²−2x+1)=2x−1이라 일차함수야. 3/(x²+1)은 분수 꼴이라 다항식이 아니어서 이차함수가 아니야.", "again": "y=x(x+3)/2가 이차함수인지 판단하는 방법을 말해 봐.", "fig": false, "src": "191쪽 예제 1", "miscon": "정리 전 겉모양이나 분모의 x²을 보고 판단함", "record": "우변을 정리하고 다항식인지 확인해 이차함수를 판별하지 못함"}], "m3-1|4. 이차함수|79. 이차함수 f(x)=x²-5x에 대하여 f(2)의 값은?": [{"kind": "뜻", "q": "f(2)는 무엇을 뜻하고, 이차함수 f(x)=x²−5x에서 f(2)는 어떻게 구해?", "ideas": [["f(2)는 x=2일 때의 함숫값이다", "f(2)의 괄호 안 2는 x에 넣는 수일까, y의 값일까?"], ["식의 x 자리에 2를 대입해 계산한다", "x²−5x에서 x를 모두 2로 바꾸면 어떻게 되지?"]], "teach": "f(2)는 \"x=2를 넣었을 때 나오는 y의 값\"이야. x 자리에 모두 2를 넣어 2²−5×2=−6. 입력에 2를 넣으면 −6이 나오는 기계라고 생각하면 돼.", "again": "f(x)=−x²+2x−3에서 f(−1)을 구하는 방법을 말해 봐.", "fig": false, "src": "192쪽", "miscon": "f(2)를 f×2로 봄", "record": "함숫값 f(a)의 뜻(x=a일 때의 y값)을 설명하지 못함"}, {"kind": "함정", "q": "f(x)=−x²+2x−3에서 f(−1)을 구할 때 −1²으로 계산하면 왜 틀릴까?", "ideas": [["음수를 대입할 때는 괄호를 씌워 (−1)²으로 계산해야 한다", "−1²과 (−1)²은 같은 값일까?"], ["식의 앞에 있는 −는 제곱을 한 뒤에 붙이므로 −(−1)²=−1이다", "−x²에서 x=−1이면 먼저 제곱하고 −를 붙일까, −를 먼저 붙일까?"]], "teach": "x=−1을 넣을 때는 괄호가 필요해: −(−1)²+2×(−1)−3=−1−2−3=−6. 괄호 없이 넣으면 부호를 틀리기 쉬워.", "again": "f(x)=x²−4에서 f(−3)을 구할 때 조심할 점을 말해 봐.", "fig": false, "src": "193쪽 예제 3", "miscon": "음수를 괄호 없이 대입함", "record": "음수를 대입할 때 괄호와 부호를 정확히 처리하지 못함"}], "m3-1|4. 이차함수|80. 이차함수 f(x)=x²-5x에 대하여 f(a)=-6일 때, a의 값은?": [{"kind": "방법", "q": "f(x)=x²−5x에서 f(a)=−6일 때 a는 어떻게 구하고, f(2)를 구하는 문제와 무엇이 달라?", "ideas": [["f(a)=−6은 x=a일 때 함숫값이 −6이라는 뜻이라 a²−5a=−6을 세운다", "f(a)=−6을 식으로 쓰면 어떻게 될까?"], ["출력값을 주고 입력값을 묻는 것이라 a에 대한 이차방정식을 풀어야 한다", "f(2)는 입력을 주고 출력을 묻는 거였지? 이번엔 반대일까?"]], "teach": "f(2)는 입력 2를 넣어 출력을 구하지만, f(a)=−6은 출력 −6을 알려 주고 입력 a를 묻는 거야. a²−5a+6=0 → (a−2)(a−3)=0 → a=2 또는 3.", "again": "f(x)=3x²+5x−1에서 f(k)=1일 때 k를 구하는 방법을 말해 봐.", "fig": false, "src": "193쪽", "miscon": "함숫값 조건을 대입 계산으로 착각함", "record": "함숫값이 주어졌을 때 방정식을 세워 입력값을 구하지 못함"}, {"kind": "함정", "q": "f(k)=1을 풀었더니 k=−2 또는 k=1/3이 나왔는데 문제에 \"양수 k\"라고 쓰여 있어. 답은 무엇이고, 이런 조건을 왜 확인해야 해?", "ideas": [["양수 조건 때문에 k=1/3만 답이다", "−2와 1/3 중 양수는 무엇이지?"], ["이차방정식은 해가 두 개 나올 수 있어서 문제의 조건에 맞는 것을 골라야 한다", "방정식을 풀면 해가 몇 개까지 나올 수 있지?"]], "teach": "이차방정식이라 해가 두 개 나와도 문제의 조건(양수)에 맞는 것만 답이야. 그래서 k=1/3. 조건을 안 보면 −2까지 답으로 써서 틀려.", "again": "f(x)=x²−2x에서 f(k)=3을 풀어 k=−1 또는 3이 나왔는데 문제에 \"양수 k\"라고 쓰여 있다면, 답으로 무엇을 고르고 왜 그런지 말해 봐.", "fig": false, "src": "193쪽 예제 4", "miscon": "문제의 조건을 확인하지 않고 해를 모두 답으로 씀", "record": "문제 조건으로 이차방정식의 해를 고르지 못함"}], "m3-1|4. 이차함수|81. 이차함수 y=x²의 그래프는 어떤 모양일까?": [{"kind": "성질", "q": "y=x²의 그래프는 어떤 모양이고, 어떤 성질이 있어?", "ideas": [["원점을 지나고 아래로 볼록한 곡선이다", "x=0일 때 y는 얼마이고, 그래프는 위와 아래 중 어느 쪽으로 볼록할까?"], ["y축에 대칭이고, x<0에서는 x가 커지면 y가 작아지고 x>0에서는 y도 커진다", "x=2와 x=−2일 때 y의 값은 같을까?"]], "teach": "x와 −x를 넣으면 y 값이 같아서 y축에 대칭이고, x²≥0이라 x축 아래로는 안 내려가. 원점이 가장 낮은 점이고 아래로 볼록한 매끄러운 곡선이야.", "again": "y=x²의 그래프가 x축 아래에 그려지지 않는 이유를 말해 봐.", "fig": true, "src": "196~197쪽", "miscon": "이차함수 그래프를 직선이나 뾰족한 모양으로 봄", "record": "y=x² 그래프의 모양과 대칭·증감을 설명하지 못함", "figScene": {"title": "y=x²의 그래프", "axes": {"xMin": -3.5, "xMax": 3.5, "yMin": -1, "yMax": 9.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "x^2", "color": "#185FA5", "label": "y=x²", "labelAt": 2.6}]}}, {"kind": "뜻", "q": "포물선의 축과 꼭짓점은 무엇이고, y=x²의 그래프에서는 각각 무엇이야?", "ideas": [["포물선의 대칭축을 축, 축과 포물선이 만나는 점을 꼭짓점이라고 한다", "포물선을 반으로 접는 선과 그 선이 포물선과 만나는 점을 각각 뭐라고 부르지?"], ["y=x²에서는 축이 y축(x=0), 꼭짓점이 원점(0, 0)이다", "y=x²의 그래프는 어떤 선에 대칭이었지?"]], "teach": "y=x² 모양의 곡선을 포물선이라고 해. 좌우를 똑같이 나누는 대칭축이 축, 축과 포물선이 만나는 점이 꼭짓점이야. y=x²은 y축이 축, 원점이 꼭짓점이야.", "again": "y=x² 그래프에서 꼭짓점이 가장 낮은 점이 되는 이유를 말해 봐.", "fig": true, "src": "196쪽", "miscon": "꼭짓점을 x축과의 교점으로 봄", "record": "포물선의 축과 꼭짓점의 뜻을 설명하지 못함", "figScene": {"title": "y=x²의 그래프와 대칭인 선", "axes": {"xMin": -3.5, "xMax": 3.5, "yMin": -1, "yMax": 9.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "x^2", "color": "#185FA5", "label": "y=x²", "labelAt": 2.6}], "points": {"V": [0, 0]}, "labels": [{"text": "", "dx": 0, "dy": 0, "point": "V"}], "lines": [{"x": 0, "color": "#D85A30", "style": "dashed"}]}}], "m3-1|4. 이차함수|82. 이차함수 y=-x²의 그래프는 어떤 모양일까?": [{"kind": "성질", "q": "y=−x²의 그래프는 y=x²의 그래프와 어떤 관계이고, 모양은 어떻게 돼?", "ideas": [["같은 x에서 함숫값의 절댓값은 같고 부호가 반대라 x축에 대칭이다", "x=2일 때 y=x²과 y=−x²의 값은 각각 얼마지?"], ["원점을 지나고 위로 볼록한 포물선이다", "x축에 대칭으로 뒤집으면 볼록한 방향은 어떻게 바뀔까?"]], "teach": "x=2일 때 x²=4, −x²=−4처럼 부호만 반대야. 그래서 y=x²의 그래프를 x축에 대해 뒤집은 모양, 곧 원점을 꼭짓점으로 하는 위로 볼록한 포물선이야. 증가·감소도 반대가 돼.", "again": "y=−x²에서 x>0일 때 x가 커지면 y는 어떻게 되는지 이유와 함께 말해 봐.", "fig": true, "src": "197쪽", "miscon": "y=−x²을 y축 대칭으로 봄", "record": "y=x²과 y=−x²이 x축에 대칭인 이유를 설명하지 못함", "figScene": {"title": "y=x²과 y=−x²", "axes": {"xMin": -3.5, "xMax": 3.5, "yMin": -9.5, "yMax": 9.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "x^2", "color": "#9A9890", "label": "y=x²", "labelAt": 2.7, "style": "dashed"}, {"fn": "-x^2", "color": "#185FA5", "label": "y=−x²", "labelAt": 2.7}]}}, {"kind": "함정", "q": "y=−x²의 그래프에는 y좌표가 양수인 점이 있을까? 이유와 함께 가장 높은 점을 말해 봐.", "ideas": [["모든 x에 대해 x²≥0이라 −x²≤0이므로 y좌표가 양수인 점은 없다", "x²은 음수가 될 수 있을까? 그러면 −x²은?"], ["x=0일 때 y=0이 가장 크므로 꼭짓점 (0, 0)이 가장 높은 점이다", "−x²이 가장 커지는 x는 얼마지?"]], "teach": "x²은 항상 0 이상이라 −x²은 항상 0 이하야. 그래서 그래프는 x축 위로 올라가지 않고, x=0일 때 y=0인 꼭짓점이 가장 높은 점이야. y=x²과 반대로 꼭짓점이 최고점이 돼.", "again": "y=x²과 y=−x²에서 꼭짓점이 각각 가장 낮은 점, 가장 높은 점이 되는 이유를 말해 봐.", "fig": true, "src": "197쪽", "miscon": "−x²에 음수를 넣으면 양수가 된다고 생각함", "record": "y=−x²의 값이 항상 0 이하인 이유와 꼭짓점이 최고점임을 설명하지 못함", "figScene": {"title": "y=−x²의 그래프", "axes": {"xMin": -3.5, "xMax": 3.5, "yMin": -9.5, "yMax": 2, "ticks": true, "yStep": 2}, "curves": [{"fn": "-x^2", "color": "#185FA5", "label": "y=−x²", "labelAt": 2.6}]}}], "m3-1|4. 이차함수|83. 이차함수 y=ax²의 그래프는 어떤 모양일까?": [{"kind": "방법", "q": "y=2x²의 그래프는 y=x²의 그래프를 이용해 어떻게 그릴 수 있고, 모양의 공통점은 뭐야?", "ideas": [["같은 x에서 y=x²의 각 점의 y좌표를 2배 한 점들을 잡아 그린다", "x=1일 때 y=x²과 y=2x²의 값은 어떤 관계지?"], ["a의 값에 관계없이 원점을 꼭짓점, y축을 축으로 하는 포물선이다", "y=ax²에서 x=0이면 y는 항상 얼마지?"]], "teach": "y=2x²은 같은 x에서 y=x²보다 y좌표가 2배라 각 점을 위로 2배씩 늘려 그려. a가 무엇이든 x=0이면 y=0이고 y축에 대칭이라, y=ax²은 항상 원점이 꼭짓점이고 y축이 축인 포물선이야.", "again": "y=−(1/2)x²의 그래프를 y=(1/2)x²을 이용해 그리는 방법을 말해 봐.", "fig": true, "src": "199쪽", "miscon": "a배를 x좌표에 적용함", "record": "y=ax² 그래프를 y=x²에서 y좌표를 a배 해 그리는 방법을 모름", "figScene": {"title": "y=x²과 y=2x²", "axes": {"xMin": -3, "xMax": 3, "yMin": -1, "yMax": 9.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "x^2", "color": "#9A9890", "label": "y=x²", "labelAt": 2.8, "style": "dashed"}, {"fn": "2*x^2", "color": "#185FA5", "label": "y=2x²", "labelAt": -1.9}], "points": {"P": [1, 1], "Q": [1, 2]}, "labels": [{"text": "", "dx": 0, "dy": 0, "point": "P"}, {"text": "", "dx": 0, "dy": 0, "point": "Q"}]}}, {"kind": "연결", "q": "y=(1/2)x²과 y=−(1/2)x²의 그래프는 어떤 관계이고, 일반적으로 y=ax²과 y=−ax²은 어떤 관계야?", "ideas": [["같은 x에서 함숫값의 부호만 반대라 x축에 서로 대칭이다", "x=2일 때 두 함수의 값은 각각 얼마지?"], ["일반적으로 y=ax²과 y=−ax²의 그래프도 x축에 대칭이다", "y=x²과 y=−x²이 어떤 관계였는지 떠올려 볼래?"]], "teach": "x=2이면 (1/2)x²=2, −(1/2)x²=−2로 부호만 반대야. 그래서 두 그래프는 x축에 대칭이고, 이것은 모든 a에서 성립해: y=ax²과 y=−ax²은 x축 대칭, 폭은 같아.", "again": "y=3x²의 그래프를 이용해 y=−3x²의 그래프를 그리는 방법을 말해 봐.", "fig": true, "src": "199~200쪽", "miscon": "y=ax²과 y=−ax²을 y축 대칭으로 봄", "record": "y=ax²과 y=−ax²이 x축에 대칭인 이유를 설명하지 못함", "figScene": {"title": "y=½x²과 y=−½x²", "axes": {"xMin": -4, "xMax": 4, "yMin": -8.5, "yMax": 8.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "0.5*x^2", "color": "#185FA5", "label": "y=½x²", "labelAt": 3.3}, {"fn": "-0.5*x^2", "color": "#D85A30", "label": "y=−½x²", "labelAt": 3.3}]}}], "m3-1|4. 이차함수|84. 이차함수 y=ax²의 그래프는 a의 값에 따라 어떻게 달라질까?": [{"kind": "성질", "q": "y=ax²의 그래프에서 a의 부호와 a의 절댓값은 각각 무엇을 결정해?", "ideas": [["a>0이면 아래로 볼록, a<0이면 위로 볼록하다", "a가 음수이면 그래프는 어느 쪽으로 볼록할까?"], ["a의 절댓값이 클수록 그래프의 폭이 좁아진다", "y=2x²과 y=(1/2)x² 중 폭이 좁은 것은?"]], "teach": "a의 부호는 볼록한 방향, a의 절댓값은 폭을 정해. |a|가 크면 y가 빨리 커져서 y축에 가까운 좁은 포물선이 되고, |a|가 작으면 넓어져. y=ax²과 y=−ax²은 x축에 대칭이야.", "again": "y=−3x²과 y=(1/3)x² 중 폭이 좁은 것과 그 이유를 말해 봐.", "fig": true, "src": "200쪽", "miscon": "|a|가 클수록 폭이 넓어진다고 거꾸로 앎", "record": "a의 부호(방향)와 절댓값(폭)의 역할을 구분하지 못함", "figScene": {"title": "a의 값이 다른 y=ax²", "axes": {"xMin": -3.5, "xMax": 3.5, "yMin": -9, "yMax": 9, "ticks": true, "yStep": 2}, "curves": [{"fn": "2*x^2", "color": "#185FA5", "label": "a=2", "labelAt": -2}, {"fn": "x^2", "color": "#3FB98C", "label": "a=1", "labelAt": 2.8}, {"fn": "0.5*x^2", "color": "#534AB7", "label": "a=½", "labelAt": 3.3}, {"fn": "-x^2", "color": "#D85A30", "label": "a=−1", "labelAt": -2.8}]}}, {"kind": "함정", "q": "y=−3x²과 y=2x²의 그래프 중 폭이 더 좁은 것은? −3이 2보다 작으니까 폭이 넓다고 하면 왜 틀릴까?", "ideas": [["폭은 a 자체가 아니라 a의 절댓값으로 비교한다", "−3과 2의 절댓값은 각각 얼마지?"], ["|−3|=3>|2|=2이므로 y=−3x²의 폭이 더 좁다", "절댓값이 큰 쪽의 폭은 좁을까, 넓을까?"]], "teach": "부호는 방향만 정하고, 폭은 절댓값으로 봐. |−3|=3이 |2|=2보다 크니까 y=−3x²이 더 좁아. 부호까지 넣어 크기를 비교하면 틀려.", "again": "y=−(1/2)x²과 y=x² 중 폭이 좁은 것을 판단하는 방법을 말해 봐.", "fig": true, "src": "200쪽", "miscon": "폭을 a의 부호까지 포함한 크기로 비교함", "record": "폭을 a의 절댓값으로 비교해야 한다는 것을 적용하지 못함", "figScene": {"title": "y=−3x²과 y=2x²", "axes": {"xMin": -3, "xMax": 3, "yMin": -9.5, "yMax": 9.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "-3*x^2", "color": "#D85A30", "label": "y=−3x²", "labelAt": 1.6}, {"fn": "2*x^2", "color": "#185FA5", "label": "y=2x²", "labelAt": 2}]}}], "m3-1|4. 이차함수|85. 이차함수 y=ax²의 그래프를 y축의 방향으로 q만큼 평행이동한 그래프는?": [{"kind": "성질", "q": "y=ax²의 그래프를 y축의 방향으로 q만큼 평행이동하면 식, 꼭짓점, 축은 어떻게 돼?", "ideas": [["식은 y=ax²+q이고 꼭짓점은 (0, q)가 된다", "같은 x에서 y=x²+3의 값은 y=x²보다 얼마만큼 크지?"], ["위아래로만 움직이므로 축은 그대로 x=0(y축)이다", "그래프를 위로 옮기면 좌우 대칭축도 움직일까?"]], "teach": "모든 점의 y좌표가 q만큼 커지니까 식은 y=ax²+q. 꼭짓점은 (0,0)에서 (0,q)로, 위아래로만 움직여서 축은 y축(x=0) 그대로야. q>0이면 위로, q<0이면 아래로.", "again": "y=−3x²을 y축의 방향으로 −2만큼 평행이동한 그래프의 꼭짓점과 축을 구하는 방법을 말해 봐.", "fig": true, "src": "204쪽", "miscon": "y축 방향 이동을 꼭짓점의 x좌표 변화로 봄", "record": "y축 방향 평행이동이 꼭짓점의 y좌표만 바꾼다는 것을 설명하지 못함", "figScene": {"title": "y=x²과 y=x²+3", "axes": {"xMin": -3.5, "xMax": 3.5, "yMin": -1, "yMax": 10, "ticks": true, "yStep": 2}, "curves": [{"fn": "x^2", "color": "#9A9890", "label": "y=x²", "labelAt": 2.9, "style": "dashed"}, {"fn": "x^2+3", "color": "#185FA5", "label": "y=x²+3", "labelAt": -2.4}]}}, {"kind": "적용", "q": "y=ax²+q의 그래프를 보고 a와 q의 부호를 알아내려면 그래프의 어디를 봐야 해?", "ideas": [["볼록한 방향으로 a의 부호를 정한다", "아래로 볼록하면 a는 양수일까, 음수일까?"], ["꼭짓점이 x축보다 위에 있는지 아래에 있는지로 q의 부호를 정한다", "꼭짓점 (0, q)가 x축 아래에 있으면 q는?"]], "teach": "아래로 볼록 → a>0, 위로 볼록 → a<0. 꼭짓점 (0,q)가 x축 위면 q>0, 아래면 q<0. 모양과 꼭짓점 위치 두 가지만 보면 돼.", "again": "위로 볼록하고 꼭짓점이 x축 위에 있는 y=ax²+q의 a, q 부호를 말해 봐.", "fig": true, "src": "205쪽 예제 7", "miscon": "q의 부호를 꼭짓점의 좌우 위치로 판단함", "record": "그래프에서 a(볼록 방향)와 q(꼭짓점 높이)의 부호를 읽지 못함", "figScene": {"title": "어떤 y=ax²+q의 그래프", "axes": {"xMin": -3, "xMax": 3, "yMin": -3, "yMax": 4, "ticks": false}, "curves": [{"fn": "-x^2+2", "color": "#185FA5"}]}}], "m3-1|4. 이차함수|86. 이차함수 y=ax²의 그래프를 x축의 방향으로 p만큼 평행이동한 그래프는?": [{"kind": "성질", "q": "y=ax²의 그래프를 x축의 방향으로 p만큼 평행이동하면 식, 꼭짓점, 축은 어떻게 돼?", "ideas": [["식은 y=a(x−p)²이고 꼭짓점은 (p, 0)이다", "y=(x−2)²에서 y가 0이 되는 x는 얼마지?"], ["좌우로 움직이므로 축도 함께 옮겨져 x=p가 된다", "그래프를 오른쪽으로 옮기면 대칭축도 같이 움직일까?"]], "teach": "y=(x−2)²은 x=2일 때 0이 되어 꼭짓점이 (2,0)이고, y=x²을 오른쪽으로 2만큼 옮긴 모양이야. 일반적으로 y=a(x−p)², 꼭짓점 (p,0), 축 x=p.", "again": "y=−(1/3)x²을 x축의 방향으로 −2만큼 평행이동한 그래프의 식과 꼭짓점을 구하는 방법을 말해 봐.", "fig": true, "src": "205~206쪽", "miscon": "x축 방향 이동을 꼭짓점의 y좌표 변화로 봄", "record": "x축 방향 평행이동이 꼭짓점과 축의 x좌표를 바꾼다는 것을 설명하지 못함", "figScene": {"title": "y=x²과 y=(x−2)²", "axes": {"xMin": -3, "xMax": 5, "yMin": -1, "yMax": 9.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "x^2", "color": "#9A9890", "label": "y=x²", "labelAt": -2.6, "style": "dashed"}, {"fn": "(x-2)^2", "color": "#185FA5", "label": "y=(x−2)²", "labelAt": 4.6}]}}, {"kind": "함정", "q": "y=x²을 x축의 방향으로 2만큼 평행이동하면 y=(x+2)²이 아니라 y=(x−2)²이 되는 이유는?", "ideas": [["옮긴 그래프의 꼭짓점은 x=2일 때 y=0이 되어야 한다", "오른쪽으로 2만큼 옮기면 꼭짓점은 어디로 가지?"], ["x=2를 넣었을 때 0이 되는 식은 (x−2)²이다", "(x+2)²과 (x−2)² 중 x=2를 넣어 0이 되는 것은?"]], "teach": "오른쪽으로 2만큼 옮기면 꼭짓점이 (2,0)이야. x=2를 넣어 0이 되려면 (x−2)²이어야 해. 그래서 x 대신 x−p를 넣는 거고, 부호가 반대로 보여도 이동 방향과 맞아.", "again": "y=(x+3)²의 꼭짓점이 (3,0)이 아닌 이유를 말해 봐.", "fig": true, "src": "206쪽 THINK Math", "miscon": "이동 방향과 괄호 안 부호를 같게 봄", "record": "x축 방향 이동에서 식의 부호가 반대로 되는 이유를 설명하지 못함", "figScene": {"title": "y=x²을 x축 방향으로 2만큼 옮긴 그래프", "axes": {"xMin": -3, "xMax": 5, "yMin": -1, "yMax": 9.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "x^2", "color": "#9A9890", "label": "y=x²", "labelAt": -2.6, "style": "dashed"}, {"fn": "(x-2)^2", "color": "#185FA5"}], "points": {"V": [2, 0]}, "labels": [{"text": "(2, 0)", "dx": 6, "dy": 16, "point": "V"}]}}], "m3-1|4. 이차함수|87. y=ax²을 x축으로 p, y축으로 q만큼 평행이동한 그래프는?": [{"kind": "성질", "q": "y=ax²의 그래프를 x축으로 p만큼, y축으로 q만큼 평행이동한 그래프의 식, 꼭짓점, 축은?", "ideas": [["식은 y=a(x−p)²+q이다", "x축 방향 이동과 y축 방향 이동을 식에 각각 어떻게 반영했지?"], ["꼭짓점은 (p, q), 축은 x=p이다", "y=(x−3)²+2의 꼭짓점은 어디일까?"]], "teach": "x축으로 p → x 대신 x−p, y축으로 q → +q. 합치면 y=a(x−p)²+q, 꼭짓점 (p,q), 축 x=p야. 이동 순서를 바꿔도 같은 그래프가 돼.", "again": "y=(x−3)²+2가 y=x²을 어떻게 옮긴 그래프인지 말해 봐.", "fig": true, "src": "207쪽", "miscon": "꼭짓점의 x좌표 부호를 반대로 읽음", "record": "y=a(x−p)²+q에서 꼭짓점과 축을 정확히 읽지 못함", "figScene": {"title": "y=x²과 y=(x−3)²+2", "axes": {"xMin": -3, "xMax": 6.5, "yMin": -1, "yMax": 9.5, "ticks": true, "yStep": 2}, "curves": [{"fn": "x^2", "color": "#9A9890", "label": "y=x²", "labelAt": -2.6, "style": "dashed"}, {"fn": "(x-3)^2+2", "color": "#185FA5", "label": "y=(x−3)²+2", "labelAt": 5.4}], "points": {"V": [3, 2]}, "labels": [{"text": "", "dx": 0, "dy": 0, "point": "V"}]}}, {"kind": "함정", "q": "y=−2(x+1)²−3의 꼭짓점과 축을 읽을 때 틀리기 쉬운 점은?", "ideas": [["(x+1)은 (x−(−1))이므로 꼭짓점의 x좌표는 −1이다", "x+1=0이 되는 x는 얼마지?"], ["꼭짓점은 (−1, −3), 축은 x=−1이고 a=−2라 위로 볼록하다", "뒤의 −3은 꼭짓점의 어느 좌표지?"]], "teach": "y=a(x−p)²+q 꼴로 맞추면 −2(x−(−1))²+(−3)이라 p=−1, q=−3. 꼭짓점 (−1,−3), 축 x=−1. 괄호 안 +1을 보고 p=1로 읽으면 틀려.", "again": "y=(1/2)(x+4)²+5의 꼭짓점을 읽는 방법을 말해 봐.", "fig": true, "src": "208쪽", "miscon": "괄호 안 부호를 그대로 꼭짓점 좌표로 씀", "record": "a(x−p)²+q 꼴에서 p의 부호를 정확히 읽지 못함", "figScene": {"title": "y=−2(x+1)²−3의 그래프", "axes": {"xMin": -4, "xMax": 2, "yMin": -10, "yMax": 2, "ticks": true, "yStep": 2}, "curves": [{"fn": "-2*(x+1)^2-3", "color": "#185FA5", "label": "y=−2(x+1)²−3", "labelAt": 0.4}], "points": {"V": [-1, -3]}, "labels": [{"text": "", "dx": 0, "dy": 0, "point": "V"}]}}], "m3-1|4. 이차함수|88. y=a(x-p)²+q를 x축으로 m, y축으로 n만큼 평행이동한 그래프의 식은?": [{"kind": "방법", "q": "y=a(x−p)²+q의 그래프를 x축으로 m만큼, y축으로 n만큼 평행이동한 식을 쉽게 구하는 방법은?", "ideas": [["꼭짓점 (p, q)를 x축으로 m, y축으로 n만큼 옮겨 새 꼭짓점 (p+m, q+n)을 구한다", "그래프 전체를 옮기면 꼭짓점은 어디로 가지?"], ["모양(a)은 그대로 두고 y=a(x−(p+m))²+q+n으로 쓴다", "평행이동하면 폭과 볼록한 방향이 바뀔까?"]], "teach": "평행이동은 모양이 안 바뀌어서 a는 그대로, 꼭짓점만 옮기면 돼. (p,q) → (p+m, q+n)이라 y=a(x−p−m)²+q+n.", "again": "y=−3(x+3)²+2를 x축으로 −4, y축으로 3만큼 옮긴 식을 구하는 방법을 말해 봐.", "fig": true, "src": "209쪽 예제 12", "miscon": "평행이동으로 a가 바뀐다고 생각함", "record": "평행이동을 꼭짓점의 이동으로 보고 식을 구하지 못함", "figScene": {"title": "그래프를 평행이동", "axes": {"xMin": -1.5, "xMax": 6, "yMin": -1, "yMax": 9, "ticks": true, "yStep": 2}, "curves": [{"fn": "(x-1)^2+1", "color": "#9A9890", "style": "dashed"}, {"fn": "(x-3)^2+3", "color": "#185FA5"}], "points": {"V": [1, 1], "W": [3, 3]}, "labels": [{"text": "(p, q)", "dx": -40, "dy": 14, "point": "V"}, {"text": "?", "dx": 8, "dy": 14, "point": "W"}]}}, {"kind": "함정", "q": "y=3x²+1의 그래프를 y축의 방향으로 4만큼 평행이동한 식을 y=3(x−4)²+1로 쓰면 왜 틀릴까?", "ideas": [["y축 방향 이동은 꼭짓점의 y좌표를 바꾸므로 식의 뒤에 더한다", "y축 방향으로 옮기면 꼭짓점의 어느 좌표가 바뀌지?"], ["따라서 꼭짓점 (0, 1)이 (0, 5)가 되어 y=3x²+5이다", "꼭짓점 (0, 1)을 위로 4만큼 옮기면 어디로 가지?"]], "teach": "x−4는 x축 방향(좌우) 이동이야. y축 방향(위아래)으로 4만큼은 꼭짓점 (0,1)이 (0,5)로 가는 거라 y=3x²+5. 방향에 따라 괄호 안과 뒤의 상수 중 어디를 바꿀지 구분해.", "again": "y=a(x−p)²+q에서 x축 방향 이동과 y축 방향 이동이 식의 어디를 바꾸는지 말해 봐.", "fig": true, "src": "209쪽 예제 12", "miscon": "x축 방향과 y축 방향 이동을 식에 반대로 반영함", "record": "평행이동 방향에 따라 식의 어느 부분이 바뀌는지 구분하지 못함", "figScene": {"title": "y=3x²+1을 y축 방향으로 4만큼 옮긴 그래프", "axes": {"xMin": -2.5, "xMax": 2.5, "yMin": -1, "yMax": 10, "ticks": true, "yStep": 2}, "curves": [{"fn": "3*x^2+1", "color": "#9A9890", "label": "y=3x²+1", "labelAt": -1.6, "style": "dashed"}, {"fn": "3*x^2+5", "color": "#185FA5"}]}}], "m3-1|4. 이차함수|89. y=a(x-p)²+q를 x축에 대하여 대칭이동한 그래프의 식은?": [{"kind": "성질", "q": "y=a(x−p)²+q의 그래프를 x축에 대하여 대칭이동하면 식이 어떻게 되고, 무엇이 바뀌어?", "ideas": [["y 대신 −y를 넣어 y=−a(x−p)²−q가 된다", "x축에 대칭인 점은 x좌표와 y좌표 중 무엇의 부호가 바뀌지?"], ["꼭짓점이 (p, −q)가 되고 볼록한 방향이 뒤집혀 a의 부호도 바뀐다", "그래프를 뒤집으면 아래로 볼록하던 것이 어떻게 될까?"]], "teach": "x축 대칭은 y좌표의 부호가 바뀌어서 y 대신 −y: −y=a(x−p)²+q → y=−a(x−p)²−q. 꼭짓점 (p,−q), 모양이 뒤집혀 a도 부호가 바뀌어. q의 부호만 바꾸면 틀려.", "again": "y=(1/2)(x−3)²+1을 x축에 대칭이동한 식에서 부호가 바뀌는 곳을 모두 말해 봐.", "fig": true, "src": "209~210쪽", "miscon": "x축 대칭에서 q만 바꾸고 a의 부호를 그대로 둠", "record": "x축 대칭이동에서 a와 q의 부호가 모두 바뀌는 이유를 설명하지 못함", "figScene": {"title": "x축에 대칭인 두 그래프", "axes": {"xMin": -1, "xMax": 7, "yMin": -7, "yMax": 7, "ticks": true, "yStep": 2}, "curves": [{"fn": "0.5*(x-3)^2+1", "color": "#185FA5", "label": "y=½(x−3)²+1", "labelAt": 6.3}, {"fn": "-0.5*(x-3)^2-1", "color": "#D85A30", "label": "?", "labelAt": 6.3}]}}, {"kind": "연결", "q": "같은 그래프를 y축에 대하여 대칭이동하면 x축 대칭과 무엇이 달라?", "ideas": [["y축 대칭은 x 대신 −x를 넣어 y=a(x+p)²+q가 된다", "y축에 대칭인 점은 어느 좌표의 부호가 바뀌지?"], ["꼭짓점의 x좌표만 바뀌고 모양(볼록 방향)은 그대로다", "y축에 대해 좌우로 뒤집으면 볼록한 방향이 바뀔까?"]], "teach": "y축 대칭은 좌우만 뒤집어서 x 대신 −x: y=a(−x−p)²+q=a(x+p)²+q. 꼭짓점 (−p,q), a는 그대로. x축 대칭은 위아래가 뒤집혀 a가 바뀌는 것과 달라.", "again": "y=−(x+2)²+5를 y축에 대칭이동한 식을 구하는 방법을 말해 봐.", "fig": true, "src": "210쪽 예제 13", "miscon": "y축 대칭에서도 a의 부호가 바뀐다고 생각함", "record": "x축 대칭과 y축 대칭의 차이를 설명하지 못함", "figScene": {"title": "y축에 대칭인 두 그래프", "axes": {"xMin": -7, "xMax": 7, "yMin": -2, "yMax": 7, "ticks": true, "yStep": 2}, "curves": [{"fn": "0.5*(x-3)^2+1", "color": "#185FA5", "label": "y=½(x−3)²+1", "labelAt": 6.2}, {"fn": "0.5*(x+3)^2+1", "color": "#D85A30", "label": "?", "labelAt": -6.2}]}}], "m3-1|4. 이차함수|90. 이차함수 y=ax²+bx+c를 y=a(x-p)²+q 꼴로 어떻게 고칠까?": [{"kind": "방법", "q": "y=2x²−4x+1을 y=a(x−p)²+q 꼴로 고치는 순서를 말해 봐.", "ideas": [["상수항을 제외한 항을 x²의 계수 2로 묶는다", "2x²−4x에서 2로 묶으면 괄호 안은 어떻게 되지?"], ["괄호 안에서 x의 계수의 절반의 제곱을 더하고 빼서 완전제곱식을 만든다", "x²−2x에 무엇을 더하면 완전제곱식이 될까?"], ["괄호 밖으로 꺼내는 수에는 괄호 앞의 계수를 곱해 정리한다", "괄호 안의 −1을 밖으로 꺼내면 2와 곱해서 얼마가 되지?"]], "teach": "y=2(x²−2x)+1 → 괄호 안에 (−2/2)²=1을 더하고 빼서 2(x²−2x+1−1)+1 → 2(x−1)²−2+1=2(x−1)²−1. 방정식처럼 양변에 더하는 게 아니라 식 안에서 더하고 빼는 거야.", "again": "y=x²+6x+8을 표준형으로 고치는 순서를 말해 봐.", "fig": false, "src": "221쪽", "miscon": "이차함수 식을 방정식처럼 양변을 나눔", "record": "일반형을 표준형으로 고치는 순서(묶기·더하고 빼기·꺼내기)를 모름"}, {"kind": "함정", "q": "y=−3x²−12x+6을 −3(x²+4x+4)+6으로 고치면 왜 틀릴까?", "ideas": [["완전제곱식을 만들려고 괄호 안에 4를 더했으면 4도 빼야 한다", "괄호 안에 4만 더하면 원래 식과 값이 같을까?"], ["빼는 4를 괄호 밖으로 꺼낼 때는 −3을 곱해 +12가 된다", "−3(x²+4x+4−4)에서 −4를 밖으로 꺼내면 얼마가 되지?"]], "teach": "−3(x²+4x+4−4)+6=−3(x+2)²+12+6=−3(x+2)²+18. 4를 더하기만 하거나, 꺼낼 때 −3을 안 곱하면 값이 달라져.", "again": "이차함수 식을 표준형으로 고칠 때 틀리기 쉬운 두 곳을 말해 봐.", "fig": false, "src": "221쪽", "miscon": "더한 수를 빼지 않거나 꺼낼 때 계수를 곱하지 않음", "record": "표준형으로 고칠 때 식의 값을 유지하는 처리를 하지 못함"}], "m3-1|4. 이차함수|91. 이차함수 y=ax²+bx+c의 그래프에서 x절편, y절편은 어떻게 구할까?": [{"kind": "방법", "q": "이차함수 y=ax²+bx+c의 그래프에서 x절편과 y절편은 각각 어떻게 구해?", "ideas": [["x절편은 x축과 만나는 점이므로 y=0을 대입해 이차방정식을 푼다", "x축 위의 점은 y좌표가 얼마지?"], ["y절편은 y축과 만나는 점이므로 x=0을 대입하며 상수항 c가 된다", "x=0을 넣으면 ax²+bx+c에서 무엇만 남지?"]], "teach": "x절편은 y=0 → ax²+bx+c=0의 해, y절편은 x=0 → y=c. 예: y=x²+x−2는 (x+2)(x−1)=0이라 x절편 −2, 1, y절편 −2.", "again": "y=x²−4x+3의 x절편과 y절편을 구하는 방법을 말해 봐.", "fig": true, "src": "222쪽", "miscon": "x절편과 y절편에서 0을 넣는 변수를 바꿈", "record": "이차함수 그래프의 x절편·y절편을 구하는 방법을 모름", "figScene": {"title": "y=x²+x−2의 그래프", "axes": {"xMin": -3.5, "xMax": 2.5, "yMin": -3, "yMax": 5, "ticks": true}, "curves": [{"fn": "x^2+x-2", "color": "#185FA5", "label": "y=x²+x−2", "labelAt": 1.9}], "points": {"P": [-2, 0], "Q": [1, 0], "R": [0, -2]}, "labels": [{"text": "", "dx": 0, "dy": 0, "point": "P"}, {"text": "", "dx": 0, "dy": 0, "point": "Q"}, {"text": "", "dx": 0, "dy": 0, "point": "R"}]}}, {"kind": "연결", "q": "이차함수의 그래프에서 x절편이 0개, 1개, 2개일 수 있는 이유를 이차방정식과 연결해 말해 봐.", "ideas": [["x절편은 이차방정식 ax²+bx+c=0의 실수 해이다", "x절편을 구할 때 풀었던 방정식은 무엇이었지?"], ["그 이차방정식의 해가 없으면 0개, 중근이면 1개, 서로 다른 두 해면 2개이다", "이차방정식의 해의 개수는 몇 가지 경우가 있었지?"]], "teach": "x절편=ax²+bx+c=0의 해야. 해가 2개면 x축과 두 점에서, 중근이면 한 점에서 닿고, 해가 없으면 x축과 안 만나. 그래서 x절편은 0, 1, 2개 중 하나야.", "again": "그래프가 x축에 한 점에서만 닿는 이차함수는 이차방정식으로 보면 어떤 경우인지 말해 봐.", "fig": true, "src": "222쪽 참고", "miscon": "이차함수는 항상 x절편이 2개라고 생각함", "record": "x절편의 개수를 이차방정식의 해의 개수와 연결하지 못함", "figScene": {"title": "x축과 만나는 모양이 다른 세 포물선", "axes": {"xMin": -3, "xMax": 3, "yMin": -3, "yMax": 6, "ticks": false}, "curves": [{"fn": "x^2+1", "color": "#185FA5"}, {"fn": "x^2", "color": "#3FB98C"}, {"fn": "x^2-2", "color": "#D85A30"}]}}], "m3-1|4. 이차함수|92. 이차함수 y=ax²+bx+c의 그래프는 어떻게 그릴까?": [{"kind": "방법", "q": "y=x²+2x−3의 그래프를 그리는 순서를 말해 봐.", "ideas": [["x²의 계수의 부호로 볼록한 방향을 정한다", "x²의 계수가 양수면 어느 쪽으로 볼록하지?"], ["y=a(x−p)²+q 꼴로 고쳐 꼭짓점을 구한다", "y=x²+2x−3을 표준형으로 고치면 꼭짓점은 어디지?"], ["x=0을 넣어 y절편을 구하고 점들을 이어 그린다", "y절편은 어떻게 찾았지?"]], "teach": "① 모양: x²의 계수 1>0 → 아래로 볼록 ② 꼭짓점: (x+1)²−4 → (−1,−4) ③ y절편: −3. 이 세 가지로 그래프를 그려. 인수분해가 되면 x절편 −3, 1도 도움이 돼.", "again": "y=−2x²−8x−5의 그래프를 그리는 순서를 말해 봐.", "fig": true, "src": "223쪽", "miscon": "핵심 정보 없이 점만 찍어 그리려 함", "record": "모양·꼭짓점·y절편으로 그래프를 그리는 순서를 모름", "figScene": {"title": "y=x²+2x−3의 그래프", "axes": {"xMin": -4.5, "xMax": 2.5, "yMin": -5, "yMax": 6, "ticks": true}, "curves": [{"fn": "x^2+2*x-3", "color": "#185FA5", "label": "y=x²+2x−3", "labelAt": 2}]}}, {"kind": "연결", "q": "이차함수의 그래프가 x축과 만나는 두 점 x=−3, x=1을 알면 축의 방정식을 바로 알 수 있어. 왜 그럴까?", "ideas": [["포물선은 축에 대칭이므로 x축과 만나는 두 점은 축에서 같은 거리에 있다", "포물선을 축으로 접으면 x축과 만나는 두 점은 어떻게 될까?"], ["그래서 축은 두 x절편의 한가운데인 x=(−3+1)/2=−1이다", "두 수의 한가운데는 어떻게 구하지?"]], "teach": "포물선은 축을 기준으로 좌우 대칭이라 x축과 만나는 두 점도 축에서 같은 거리야. 그래서 축은 두 x절편의 평균, x=(−3+1)/2=−1. 꼭짓점의 x좌표도 −1이야.", "again": "x절편이 2와 6인 포물선의 축을 구하는 방법과 이유를 말해 봐.", "fig": true, "src": "223쪽", "miscon": "축을 두 x절편의 합으로 봄", "record": "포물선의 대칭성으로 축을 구하는 이유를 설명하지 못함", "figScene": {"title": "x축과 두 점에서 만나는 포물선", "axes": {"xMin": -4.5, "xMax": 2.5, "yMin": -5, "yMax": 6, "ticks": true}, "curves": [{"fn": "x^2+2*x-3", "color": "#185FA5"}], "points": {"P": [-3, 0], "Q": [1, 0]}, "labels": [{"text": "−3", "dx": -18, "dy": -8, "point": "P"}, {"text": "1", "dx": 6, "dy": -8, "point": "Q"}]}}], "m3-1|4. 이차함수|93. 이차함수 y=ax²+bx+c의 그래프를 보고 a, b, c의 부호를 알 수 있을까?": [{"kind": "방법", "q": "이차함수 y=ax²+bx+c의 그래프를 보고 a, b, c의 부호는 각각 그래프의 어디를 보고 알아?", "ideas": [["a는 그래프의 볼록한 방향으로 정한다", "아래로 볼록하면 a는?"], ["b는 축의 위치로 정하는데, 축이 y축의 오른쪽이면 a와 b의 부호가 다르고 왼쪽이면 같다", "축의 방정식 x=−b/2a가 양수이려면 a와 b의 부호는 어때야 할까?"], ["c는 그래프가 y축과 만나는 점의 위치로 정한다", "y절편은 식의 어느 항이었지?"]], "teach": "a: 볼록 방향. c: y절편의 위치(x축 위면 c>0). b: 축 x=−b/2a가 y축 오른쪽이면 ab<0(부호 다름), 왼쪽이면 ab>0(부호 같음), y축이면 b=0. b는 a와 함께 봐야 해.", "again": "위로 볼록하고 축이 y축의 왼쪽, y절편이 양수인 그래프의 a, b, c 부호를 판단하는 방법을 말해 봐.", "fig": true, "src": "224쪽", "miscon": "b의 부호를 x절편이나 볼록 방향만으로 판단함", "record": "그래프에서 a·b·c의 부호를 각각 무엇으로 판단하는지 설명하지 못함", "figScene": {"title": "어떤 y=ax²+bx+c의 그래프", "axes": {"xMin": -4, "xMax": 2.5, "yMin": -3, "yMax": 5, "ticks": false}, "curves": [{"fn": "-x^2-2*x+3", "color": "#185FA5"}]}}, {"kind": "이유", "q": "축이 y축의 오른쪽에 있으면 a와 b의 부호가 서로 다른 이유를 설명해 봐.", "ideas": [["축의 방정식은 x=−b/2a이다", "y=ax²+bx+c를 표준형으로 고치면 축은 어떻게 나타나지?"], ["축이 y축 오른쪽이면 −b/2a>0이라 b/a<0, 즉 a와 b의 부호가 다르다", "−b/2a가 양수가 되려면 a와 b를 나눈 값의 부호는?"]], "teach": "표준형으로 고치면 축은 x=−b/2a야. 오른쪽이면 −b/2a>0 → b/2a<0 → a와 b의 부호가 달라. 왼쪽이면 같은 부호, 축이 y축이면 b=0.", "again": "축이 y축의 왼쪽에 있을 때 ab의 부호를 판단하는 이유를 말해 봐.", "fig": true, "src": "224쪽", "miscon": "축의 위치를 b 하나의 부호로만 판단함", "record": "축의 위치와 a·b 부호 관계(x=−b/2a)를 설명하지 못함", "figScene": {"title": "축이 y축의 오른쪽에 있는 포물선", "axes": {"xMin": -1.5, "xMax": 5.5, "yMin": -3, "yMax": 5, "ticks": false}, "curves": [{"fn": "x^2-4*x+2", "color": "#185FA5"}], "lines": [{"x": 2, "color": "#D85A30", "style": "dashed"}]}}], "m3-1|4. 이차함수|94. 꼭짓점의 좌표가 주어진 경우, 이차함수의 식은 어떻게 구할까?": [{"kind": "방법", "q": "꼭짓점이 (−2, 4)이고 점 (0, 1)을 지나는 포물선의 이차함수 식은 어떻게 구해?", "ideas": [["꼭짓점 (p, q)를 이용해 y=a(x+2)²+4로 놓는다", "꼭짓점을 알 때 편한 식의 꼴은 무엇이었지?"], ["지나는 점 (0, 1)을 대입해 a를 구한다", "남은 미지수 a는 어떻게 구하지?"]], "teach": "꼭짓점을 알면 y=a(x−p)²+q 꼴이 편해: y=a(x+2)²+4. 점 (0,1)을 넣으면 1=4a+4 → a=−3/4. 그래서 y=−(3/4)(x+2)²+4.", "again": "꼭짓점이 (1, −2)이고 점 (3, 6)을 지나는 포물선의 식을 구하는 순서를 말해 봐.", "fig": false, "src": "225쪽", "miscon": "꼭짓점 정보를 쓰지 않고 일반형으로 놓음", "record": "꼭짓점이 주어질 때 표준형으로 놓고 a를 구하는 방법을 모름"}, {"kind": "함정", "q": "꼭짓점이 (0, 3)이면 식을 y=a(x−0)²+3, 곧 y=ax²+3으로 놓을 수 있어. 꼭짓점이 (2, 0)이면 어떤 꼴이 되고, 틀리기 쉬운 점은?", "ideas": [["꼭짓점이 (p, 0)이면 q=0이라 y=a(x−p)² 꼴이 되어 y=a(x−2)²으로 놓는다", "꼭짓점의 y좌표가 0이면 표준형에서 무엇이 사라지지?"], ["괄호 안의 부호를 꼭짓점과 반대로 써서 (x+2)²으로 놓지 않도록 조심한다", "x=2일 때 0이 되는 식은 (x−2)²일까, (x+2)²일까?"]], "teach": "꼭짓점 좌표에 따라 표준형이 간단해져: (0,0) → ax², (0,q) → ax²+q, (p,0) → a(x−p)². 꼭짓점 (2,0)이면 y=a(x−2)². x좌표 2를 보고 (x+2)로 쓰면 틀려.", "again": "꼭짓점이 (−3, 0)인 포물선의 식을 놓을 때 괄호 안 부호를 정하는 방법을 말해 봐.", "fig": false, "src": "225쪽 참고", "miscon": "꼭짓점의 x좌표와 괄호 안 부호를 같게 씀", "record": "꼭짓점 좌표에 맞게 표준형을 간단히 놓지 못함"}], "m3-1|4. 이차함수|95. 축의 방정식이 주어진 경우, 이차함수의 식은 어떻게 구할까?": [{"kind": "방법", "q": "축의 방정식이 x=−1이고 두 점 (0, −5), (1, −8)을 지나는 포물선의 식은 어떻게 구해?", "ideas": [["축이 x=−1이면 꼭짓점의 x좌표가 −1이라 y=a(x+1)²+q로 놓는다", "축의 방정식과 꼭짓점의 x좌표는 어떤 관계지?"], ["두 점을 각각 대입해 a와 q에 대한 연립방정식을 푼다", "미지수 a, q가 두 개면 식이 몇 개 필요할까?"]], "teach": "축 x=p는 꼭짓점의 x좌표가 p라는 뜻이라 y=a(x+1)²+q. (0,−5) → a+q=−5, (1,−8) → 4a+q=−8. 연립하면 a=−1, q=−4라 y=−(x+1)²−4.", "again": "축이 x=2이고 두 점을 지나는 포물선의 식을 구할 때 처음 놓는 식을 말해 봐.", "fig": false, "src": "226쪽", "miscon": "축만 알고도 q까지 안다고 생각함", "record": "축이 주어질 때 표준형으로 놓고 a·q를 연립으로 구하지 못함"}, {"kind": "이유", "q": "축의 방정식이 x=−1이라는 조건만으로는 이차함수의 식을 하나로 정할 수 없어. 그 이유와, 몇 개의 점이 더 필요한지 말해 봐.", "ideas": [["축은 꼭짓점의 x좌표만 알려 주므로 a와 q 두 값을 아직 모른다", "y=a(x+1)²+q에서 아직 모르는 값은 몇 개지?"], ["모르는 값이 두 개라 서로 다른 두 점의 좌표가 더 필요하다", "미지수 두 개를 구하려면 식이 몇 개 필요할까?"]], "teach": "축 x=−1은 p=−1만 정해 줘. y=a(x+1)²+q에는 a, q 두 값이 남아서 식이 두 개, 즉 지나는 두 점이 필요해. 꼭짓점을 알면 a 하나만 남아 한 점이면 충분한 것과 달라.", "again": "꼭짓점이 주어질 때는 한 점, 축이 주어질 때는 두 점이 필요한 이유를 말해 봐.", "fig": false, "src": "226쪽", "miscon": "축을 꼭짓점 전체 정보로 착각함", "record": "주어진 조건에 따라 필요한 점의 개수를 판단하지 못함"}], "m3-1|4. 이차함수|96. 꼭짓점이 아닌 세 점의 좌표가 주어지는 경우, 이차함수의 식은 어떻게 구할까?": [{"kind": "방법", "q": "꼭짓점이 아닌 세 점 (0, −3), (1, −3), (−1, −1)을 지나는 포물선의 식은 어떻게 구해?", "ideas": [["꼭짓점을 모르므로 y=ax²+bx+c로 놓는다", "꼭짓점을 모를 때 쓰는 식의 꼴은?"], ["x=0인 점을 먼저 대입해 c를 구하고, 나머지 두 점으로 a, b를 연립해 구한다", "x=0을 넣으면 식에서 무엇이 바로 나오지?"]], "teach": "꼭짓점을 모르면 일반형 y=ax²+bx+c. (0,−3)을 넣으면 c=−3이 바로 나와. 나머지 두 점으로 a+b−3=−3, a−b−3=−1을 풀면 a=1, b=−1이라 y=x²−x−3.", "again": "세 점이 주어졌을 때 y절편인 점을 먼저 대입하면 좋은 이유를 말해 봐.", "fig": false, "src": "226~227쪽", "miscon": "꼭짓점을 모르는데 표준형으로 놓음", "record": "세 점이 주어질 때 일반형으로 놓고 c부터 구하는 방법을 모름"}, {"kind": "이유", "q": "세 점이 주어졌을 때 y=a(x−p)²+q로 놓아도 틀리지는 않지만 y=ax²+bx+c로 놓는 것이 더 편한 이유는 뭘까?", "ideas": [["꼭짓점을 모르면 표준형으로 놓아도 p, q를 따로 구해야 하고 어차피 전개해야 한다", "y=a(x−p)²+q에 점을 넣으면 식이 간단해질까?"], ["일반형에서는 x=0인 점을 넣으면 c가 바로 나와 나머지 계산이 줄어든다", "y=ax²+bx+c에 x=0을 넣으면 무엇이 바로 나오지?"]], "teach": "꼭짓점을 모르면 p, q까지 모르는 채로 제곱을 전개해야 해서 계산이 길어. 일반형은 이미 전개된 꼴이라 세 점을 넣기 쉽고, 특히 (0, c) 꼴의 점을 넣으면 c가 바로 나와.", "again": "세 점 중 y축 위의 점이 없을 때도 일반형으로 놓는 이유를 말해 봐.", "fig": false, "src": "226쪽", "miscon": "조건과 상관없이 표준형만 고집함", "record": "세 점이 주어질 때 일반형이 편한 이유를 설명하지 못함"}], "m3-1|4. 이차함수|97. x축과 만나는 두 점의 좌표가 주어지는 경우, 이차함수의 식은 어떻게 구할까?": [{"kind": "방법", "q": "x축과 두 점 (1, 0), (3, 0)에서 만나고 점 (−1, 8)을 지나는 포물선의 식은 어떻게 구해?", "ideas": [["x축과 만나는 두 점 α, β를 이용해 y=a(x−1)(x−3)으로 놓는다", "x=1과 x=3에서 y가 0이 되는 식은 어떻게 쓸 수 있을까?"], ["나머지 한 점 (−1, 8)을 대입해 a를 구한다", "남은 미지수 a는 어떻게 구하지?"]], "teach": "x절편이 1, 3이면 y=a(x−1)(x−3)으로 놓으면 두 점 조건이 이미 들어가. (−1,8)을 넣으면 8=a(−2)(−4)=8a라 a=1, y=x²−4x+3.", "again": "x절편이 −2와 4이고 점 (0, 16)을 지나는 포물선의 식을 구하는 순서를 말해 봐.", "fig": false, "src": "227쪽", "miscon": "x절편만 보고 a를 1로 정해 버림", "record": "x절편이 주어질 때 a(x−α)(x−β)로 놓고 a를 구하지 못함"}, {"kind": "전략", "q": "이차함수의 식을 구하는 문제에서 주어진 조건에 따라 식을 어떤 꼴로 놓아야 할지 정리해 봐.", "ideas": [["꼭짓점이나 축이 주어지면 y=a(x−p)²+q로 놓는다", "꼭짓점을 알 때 쓴 꼴은?"], ["x축과 만나는 두 점이 주어지면 y=a(x−α)(x−β)로 놓는다", "x절편 두 개를 알 때 쓴 꼴은?"], ["그 밖에 세 점이 주어지면 y=ax²+bx+c로 놓는다", "아무 정보 없이 세 점만 알 때 쓴 꼴은?"]], "teach": "꼭짓점·축 → 표준형 a(x−p)²+q, x절편 두 개 → a(x−α)(x−β), 세 점 → 일반형 ax²+bx+c. 조건에 맞는 꼴로 놓으면 구해야 할 미지수가 줄어 계산이 짧아.", "again": "꼭짓점이 (3, 0)이라는 조건이 주어졌을 때 가장 편한 식의 꼴을 말해 봐.", "fig": false, "src": "225~227쪽", "miscon": "조건과 상관없이 한 가지 꼴만 씀", "record": "조건에 따라 이차함수의 식을 놓는 꼴을 고르지 못함"}]});
